GimCorpus.put(135,0,[[1,1,"מִשְׁלֵי. כָּל דְּבָרָיו דֻּגְמוֹת וּמְשָׁלִים; מְשַׁל הַתּוֹרָה בְּאִשָּׁה טוֹבָה, וּמְשַׁל הָעוֹבְדֵי גִּלּוּלִים בְּאִשָּׁה זוֹנָה:",1,0],[1,2,"לָדַעַת חָכְמָה וּמוּסָר. הַמְּשָׁלִים הָאֵלּוּ אָמַר לְהוֹדִיעַ לַבְּרִיּוֹת חָכְמָה וּמוּסָר שֶׁיִּהְיוּ עֲמֵלִים בַּתּוֹרָה, שֶׁהִיא חָכְמָה וּמוּסָר וּבִינָה:",1,0],[1,3,"צֶדֶק וּמִשְׁפָּט וּמֵישָׁרִים. צֶדֶק, צְדָקָה מִמָּמוֹנוֹ. וּמִשְׁפָּט, לִשְׁפּוֹט אֱמֶת. וּמֵישָׁרִים, הִיא הַפְּשָׁרָה דֶּרֶךְ חָלָק וּמִישׁוֹר שָׁוֶה לָזֶה וְלָזֶה:",1,0],[1,4,"לָתֵת לִפְתָאיִם עָרְמָה. מְשָׁלִים אֵלּוּ אָמַר קֹהֶלֶת לִקְנוֹת בָּהֶם הַפְּתָאיִם עָרְמָה, לְנַעַר דַּעַת, וְגַם לְנַעַר הַמְנֻעָר מִכָּל לִמּוּד שֶׁלֹּא לָמַד עֲדַיִן כְּלוּם:",1,0],[1,4,"מְזִמָּה. מַחֲשֶׁבֶת עֵצָה:",2,0],[1,5,"יִשְׁמַע חָכָם. הַמְּשָׁלִים הַלָּלוּ:",1,0],[1,5,"וְיוֹסֶף. עַל חָכְמָתוֹ:",2,0],[1,5,"לֶקַח. לִמּוּד:",3,0],[1,5,"חָכָם. זֶה בַּעַל הַשְּׁמוּעָה:",4,0],[1,5,"וְנָבוֹן. מוֹסִיף עַל יְדִיעַת חָכָם, שֶׁיּוֹדֵעַ לְהָבִין דָּבָר מִתּוֹךְ דָּבָר וּמוֹסִיף עַל שְׁמוּעָתוֹ:",5,0],[1,6,"לְהָבִין מָשָׁל וּמְלִיצָה. שֶׁיִּתְּנוּ לֵב לְהָבִין בַּמִּקְרָאוֹת שְׁנֵי הַדְּרָכִים: הַמָּשָׁל וְהַמְּלִיצָה, שֶׁיָּבִינוּ אֶת מָה הִמְשִׁיל לַמְּלִיצָה. וְאַף מִן הַמְּלִיצָה לֹא יָסוּרוּ לִבָּם, שֶׁגַּם הִיא צְרִיכִים לְהָבִין. כְּשֶׁאָמַר ״לְהַצִּילְךָ מֵאִשָּׁה זָרָה״ וְ״נָכְרִיָּה״ (משלי ב:טז) – עַל עֲבוֹדָה זָרָה נֶאֱמַר, הֲרֵי הַמָּשָׁל. וְאַף הַמְּלִיצָה שֶׁהוֹצִיא מְשָׁלוֹ בִּלְשׁוֹן ׳אִשָּׁה׳ – הָבֵן בָּהּ וְהִזָּהֵר מֵאִשָּׁה (  זוֹנָה):",1,0],[1,6,"דִּבְרֵי חֲכָמִים וְחִידוֹתָם. דּוֹרְשֵׁי רְשִׁימוֹת: מִקְרָא מָלֵא וְחָסֵר, רֶמֶז, דִּמְיוֹן וְחִידָה:",2,0],[1,7,"יִרְאַת ה׳ רֵאשִׁית דָּעַת. עַד כָּאן פֵּרֵשׁ לְצֹרֶךְ מָה עָשָׂה שְׁלֹמֹה הַסֵּפֶר הַזֶּה, וְעַתָּה מַתְחִיל הַסֵּפֶר:",1,0],[1,7,"יִרְאַת ה׳ רֵאשִׁית דָּעַת. הִיא תְּרוּמַת עִקַּר הַדַּעַת וְהִיא תִּהְיֶה לְךָ הָרִאשׁוֹנָה לָדַעַת. לִפְנֵי חָכְמָתְךָ הַקְדֵּם לְיִרְאָה אֶת יוֹצְרְךָ, וְהִיא תִּתֵּן בְּלִבְּךָ לַעֲשׂוֹת בְּחָכְמָה וּבְדַעַת, כִּי הָאֱוִילִים, אֲשֶׁר אֵינָם יְרֵאִים אֶת ה׳, הֵם בּוֹזִים אֶת הַחָכְמָה וְאֶת הַמּוּסָר:",2,0],[1,8,"שְׁמַע בְּנִי מוּסַר אָבִיךָ. מַה שֶּׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה בִּכְתָב וְעַל פֶּה:",1,0],[1,8,"אִמֶּךָ. אוּמָּתְךָ, כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ: ״מָה אִמְּךָ לְבִיָּא״ (יחזקאל יט:ב). וְהֵם דִּבְרֵי סוֹפְרִים, שֶׁחִדְּשׁוּ וְהוֹסִיפוּ וְעָשׂוּ סְיָגִים לַתּוֹרָה:",2,0],[1,9,"לִוְיַת חֵן. חִבּוּר שֶׁל חֵן הֵם לְרֹאשְׁךָ, כְּלוֹמַר: הַתּוֹרָה וְהַמּוּסָר יִהְיוּ לְרֹאשְׁךָ לִוְיַת חֵן, וְכַעֲנָקִים שֶׁל עֲדִי זָהָב יִהְיוּ:",1,0],[1,9,"לְגַרְגְּרוֹתֶיךָ. לְצַוָּארְךָ, וְעַל שֵׁם שֶׁהַקָּנֶה עֲשׂוּיָה טַבָּעוֹת טַבָּעוֹת, קוֹרֵא הַצַּוָּאר בִּלְשׁוֹן רַבִּים:",2,0],[1,10,"חַטָּאִים. חוֹטְאִים:",1,0],[1,10,"אַל תֹּבֵא. אַל תֹּאבֶה לָהֶם:",2,0],[1,11,"נֶאֶרְבָה לְדָם. לִשְׁפּוֹךְ דָּם:",1,0],[1,11,"נִצְפְּנָה. לְשׁוֹן ״מַאֲרָב״ (יהושע ח:ט):",2,0],[1,11,"נִצְפְּנָה לְנָקִי חִנָּם. הַכָּתוּב אוֹמֵר שֶׁצְּפִינָתָם לְנָקִי – חִנָּם הוּא:",3,0],[1,12,"נִבְלָעֵם. לַנְּקִיִּים כְּשֶׁהֵם חַיִּים:",1,0],[1,12,"כְּשְׁאוֹל. הַבּוֹלֵעַ כָּל גּוּף שָׁלֵם:",2,0],[1,12,"וּתְמִימִים. אֵינוֹ לְשׁוֹן צַדִּיקִים, אֶלָּא מִלְּשׁוֹן שְׁלֵמִים: נִבְלָעֵם כְּשֶׁהֵם שְׁלֵמִים, כְּאָדָם הַיּוֹרֵד בְּתוֹךְ הַבּוֹר כְּשֶׁהוּא שָׁלֵם. כְּלוֹמַר: בְּעוֹדָם בְּעָשְׁרָם נַהַרְגֵם, וְנִירַשׁ נִכְסֵיהֶם:",3,0],[1,14,"גּוֹרָלְךָ תַּפִּיל בְּתוֹכֵנוּ. אִם תִּרְצֶה תַּחֲלֹק, אוֹ אִם תִּרְצֶה יִהְיֶה בְּשֻׁתָּפוּת:",1,0],[1,14,"כִּיס אֶחָד יִהְיֶה לְכֻלָּנוּ. בְּיַחַד:",2,0],[1,16,"לָרַע יָרוּצוּ. לְרָעַת עַצְמָם הֵם רָצִים, וְאֵינָם יוֹדְעִים לָתֵת לֵב לַדָּבָר:",1,0],[1,17,"כִּי חִנָּם מְזֹרָה הָרָשֶׁת. כִּי הָעוֹפוֹת הָרוֹאוֹת חִטִּים וְקִטְנִיּוֹת מְזוֹרִים עַל הָרֶשֶׁת, חִנָּם הוּא בְּעֵינֵיהֶם, שֶׁאֵינָם מַכִּירִים עַל מָה הִיא נִזְרֶת, וְיוֹרְדִין בָּהּ וְאוֹכְלִין:",1,0],[1,18,"וְהֵם לְדָמָם יֶאֱרֹבוּ. וְהַצַּיָּדִים יֶאֱרֹבוּ לְדָמָם שֶׁל עוֹפוֹת:",1,0],[1,19,"כֵּן אָרְחוֹת כָּל בֹּצֵעַ בָּצַע. גּוֹזֵל גְּזֵילָה נָאָה וְנֶחְמֶדֶת הִיא לוֹ, וְחִנָּם הִיא לוֹ (משלי א:יז), וְסוֹפוֹ אֶת נֶפֶשׁ בְּעָלָיו יִקָּח. נֶפֶשׁ עַצְמוֹ, שֶׁנַּעֲשָׂה עַכְשָׁיו בַּעַל הַמָּמוֹן שֶׁגָּזַל מֵחֲבֵרוֹ:",1,0],[1,20,"חָכְמוֹת בַּחוּץ תָּרֹנָּה. הֲרֵי חָכְמוֹתֶיהָ שֶׁל תּוֹרָה בְּחוּצוֹתֶיהָ תִּזְעַקְנָה לְהַזְהִירְכֶם לָסוּר עֲלֵיהֶם. וּמָה הֵן חוּצוֹתֶיהָ? בָּתֵּי מִדְרָשׁוֹת:",1,0],[1,20,"בָּרְחוֹבוֹת. בִּמְקוֹם שֶׁמַּרְחִיבִין אוֹתָהּ. כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, בחקותי ד):",2,0],[1,21,"בְּרֹאשׁ הוֹמִיּוֹת תִּקְרָא. בְּמָקוֹם שֶׁהִיא נִשְׁמַעַת וְנִכְרֶזֶת, שָׁם הִיא קוֹרֵאת וְאוֹמֶרֶת עִנְיָן שֶׁלְּמַטָּה: עַד מָתַי פְּתָיִם וְגוֹ׳:",1,0],[1,21,"בְּפִתְחֵי שְׁעָרִים. הֵם מְקוֹם יְשִׁיבַת הַזְּקֵנִים:",2,0],[1,22,"פְּתָיִם. הַמִּתְפַּתִּים עַל יְדֵי מְסִיתִים וּמִינִים:",1,0],[1,22,"תְּאֵהֲבוּ פֶתִי. הֲסָתָה שֵׁם דָּבָר לְ״פַתְיוּת״ (משלי ט:יג), כְּמוֹ ״כֶּלִי״ (במדבר יט:יז), ״קֶרִי״ (ויקרא כו:כא), (שני סא״א) ״שֶׁפִי״ (במדבר כג:ג):",2,0],[1,24,"נָטִיתִי יָדִי. לִרְמֹז לָהֶם לָסוּר אֵלַי, כְּאָדָם הַמְרַמֵּז לַחֲבֵרוֹ בְּיָדוֹ וְנוֹטֶה יָדוֹ אֵלָיו, לָסוּר אֵלָיו:",1,0],[1,25,"וַתִּפְרְעוּ. וּתְבַטְּלוּ:",1,0],[1,25,"כָּל עֲצָתִי. שֶׁיָּעַצְתִּי לְגַדֵּל אֶתְכֶם בָּעוֹלָם:",2,0],[1,27,"כְּשׁוֹאָה. כְּעָנָן הָעוֹלֶה פִּתְאוֹם:",1,0],[1,27,"כְּסוּפָה. טוֹרְבִּילוֹ״ן בְּלַעַ״ז:",2,0],[1,27,"יֶאֱתֶה. יָבֹא:",3,0],[1,28,"יְשַׁחֲרוּנְנִי. יְבַקְשׁוּנִי:",1,0],[1,31,"מִפְּרִי דַרְכָּם. הַפֵּרוֹת שֶׁאוֹכְלִים בְּחַיֵּיהֶם בַּצָּרוֹת הַמּוֹצְאוֹת אוֹתָם, וְהַקֶּרֶן שְׁמוּרָה לָהֶם בַּגֵּיהִנֹּם:",1,0],[1,32,"מְשׁוּבַת פְּתָיִם. אֶת אֲשֶׁר לִבָּם שׁוֹבָב:",1,0],[1,32,"וְשַׁלְוַת כְּסִילִים תְּאַבְּדֵם. לְפִי שֶׁרוֹאִים הָרְשָׁעִים שֶׁהֵם מַצְלִיחִים, נִדְבָּקִים בְּרָעָתָם וְאֵינָם חוֹזְרִין:",2,0],[1,33,"יִשְׁכָּן בֶּטַח. בָּעוֹלָם הַזֶּה:",1,0],[1,33,"וְשַׁאֲנַן. לְעוֹלָם הַבָּא:",2,0],[1,33,"מִפַּחַד רָעָה. מִדִּינָהּ שֶׁל גֵּיהִנֹּם:",3,0],[1,33,"וְשַׁאֲנַן. וִיהִי שָׁלֵיו וְשָׁקֵט, וְשַׁאֲנַן לְשׁוֹן עָתִיד לָכֵן נָקוּד פַּתַּח:",4,0],[2,1,"בְּנִי אִם תִּקַּח אֲמָרָי. בְּנִי תִּהְיֶה  אִם תִּקַּח אֲמָרָי:",1,0],[2,2,"לְהַקְשִׁיב לַחָכְמָה. לַעֲסוֹק בַּתּוֹרָה:",1,0],[2,5,"אָז תָּבִין יִרְאַת ה׳. מוּסָב עַל עִנְיָן שֶׁלְּמַעְלָה, שֶׁאָמַר כִּי אִם לַבִּינָה תִקְרָא:",1,0],[2,6,"כִּי ה׳ יִתֵּן חָכְמָה. הָא לָמַדְתָּ שֶׁגְּדוֹלָה הִיא, שֶׁהֲרֵי נִתְּנָה מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא, לְכָךְ אַתָּה צָרִיךְ לִקְנוֹתָהּ:",1,0],[2,7,"יִצְפֹּן לַיְשָׁרִים תּוּשִׁיָּה. גְּנָזָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶצְלוֹ (תנחומא, לך לך יא) עֶשְׂרִים וָשֵׁשׁ דּוֹרוֹת עַד שֶׁנְּתָנָהּ לְדוֹר הַמִּדְבָּר:",1,0],[2,7,"מָגֵן לְהוֹלְכֵי תֹם. (יִצְפֹּן מָגֵן לְהוֹלְכֵי תֹם), כְּלוֹמַר: וְהִיא תִּהְיֶה לְךָ לְמָגֵן:",2,0],[2,8,"לִנְצֹר אָרְחוֹת מִשְׁפָּט. שֶׁעַל יָדָהּ יִנְצְרוּ אָרְחוֹת מִשְׁפָּט, וְהוּא דֶּרֶךְ חֲסִידָיו יִשְׁמֹר. שֶׁלֹּא יִכָּשְׁלוּ:",1,0],[2,11,"מְזִמָּה תִּשְׁמֹר עָלֶיךָ. הַתּוֹרָה תִּשְׁמֹר עָלֶיךָ:",1,0],[2,12,"מֵאִישׁ מְדַבֵּר תַּהְפֻּכוֹת. הֵם הָאֶפִּיקוֹרְסִין שֶׁמַּטְעִין אֶת יִשְׂרָאֵל מֵאֱמוּנָתָן וּמְהַפְּכִין אֶת הַתּוֹרָה לְרָעָה:",1,0],[2,15,"וּנְלוֹזִים בְּמַעְגְּלוֹתָם. כָּל לְשׁוֹן ׳נָלוֹז׳ לְשׁוֹן ׳עַקְמִימוּת׳ הוּא, שֶׁבְּכָל מָקוֹם הוּא סָמוּךְ לְ׳עִקֵּשׁ׳ (משלי ד:כד), וְ׳עִקֵּשׁ׳ הוּא לְשׁוֹן ׳עָקוֹם׳, כְּמוֹ שֶׁנֶּאֱמַר ״וּמַעֲקַשִּׁים לְמִישׁוֹר״ (ישעיה מב:טז):",1,0],[2,15,"וּנְלוֹזִים בְּמַעְגְּלוֹתָם. הֵם עֲקוּמִים בְּדַרְכֵיהֶם הַמְקֻלְקָלִים:",2,0],[2,16,"מֵאִשָּׁה זָרָה. מִכְּנֵסִיָּה שֶׁל אֲפִיקוֹרְסוּת וְהִיא הַמִּינוּת. וְלֹא יִתָּכֵן לוֹמַר, שֶׁלֹּא דִּבֵּר אֶלָּא עַל הַמְנָאֶפֶת מַמָּשׁ, כִּי מַה שִּׁבְחָהּ שֶׁל תּוֹרָה שֶׁאָמַר כָּאן לְהַצִּילְךָ מֵאִשָּׁה זָרָה וְלֹא מֵעֲבֵירָה אַחֶרֶת? אֶלָּא זוֹ מִינוּת, שֶׁהוּא פְּרִיקַת עֹל שֶׁל כָּל הַמִּצְווֹת:",1,0],[2,18,"כִּי שָׁחָה אֶל מָוֶת בֵּיתָהּ. מוּסָב עַל לְהַצִּילְךָ וְגוֹ׳, כִּי תָבֹא אֶל בֵּיתָהּ, יָשַׁח וּמַחֲלִיק כְּמִדְרוֹן הַיּוֹרֵד אֶל מָוֶת. וְהַתּוֹרָה תִּשְׁמֹר עָלֶיךָ מִנְּפִילָה זוֹ, הֲרֵי דָּבָר גָּדוֹל הוּא לְךָ:",1,0],[2,18,"רְפָאִים. נִרְפִּים מִדֶּרֶךְ הַטּוֹב וְנֶעֱזָבִים מֵאֵין סוֹמֵךְ, עַד שֶׁנּוֹפְלִים בַּגֵּיהִנֹּם:",2,0],[2,19,"לֹא יְשׁוּבוּן. יִקְשֶׁה בְּעֵינֵיהֶם לִפְרֹשׁ מִמֶּנָּה וְלַחֲזֹר בָּהֶם:",1,0],[2,20,"לְמַעַן תֵּלֵךְ. מוּסָב עַל הַמִּקְרָא שֶׁלְּמַעְלָה לְהַצִּילְךָ מִדֶּרֶךְ רָעָה, לְמַעַן הוֹלִיכְךָ בְּדֶרֶךְ טוֹבִים:",1,0],[2,21,"כִּי יְשָׁרִים יִשְׁכְּנוּ אָרֶץ. לָעוֹלָם הַבָּא:",1,0],[2,21,"יִוָּתְרוּ בָהּ. כְּשֶׁיֵּרְדוּ רְשָׁעִים לְגֵיהִנֹּם:",2,0],[3,2,"אֹרֶךְ יָמִים וְגוֹ׳ וְשָׁלוֹם יוֹסִיפוּ לָךְ. תּוֹרָתִי וּמִצְווֹתַי:",1,0],[3,5,"בְּטַח אֶל ה׳. וּפַזֵּר מְעוֹתֶיךָ לְבַקֵּשׁ לְךָ רַב לִלְמֹד מִמֶּנּוּ, וְאֶל בִּינָתְךָ אַל תִּשָּׁעֵן:",1,0],[3,7,"אַל תְּהִי חָכָם בְּעֵינֶיךָ. לִהְיוֹת מוֹאֵס בְּדִבְרֵי מוֹכִיחֶךָ:",1,0],[3,8,"רִפְאוּת תְּהִי לְשָׁרֶּךָ. הַחָכְמָה. שָׁרֶּךָ כְּמוֹ ״שָׁרְרֵךְ״ (שיר השירים ז:ג), וְזֶהוּ טִיבּוּרֶךָ:",1,0],[3,8,"וְשִׁקּוּי לְעַצְמוֹתֶיךָ. הוּא הַמֹּחַ, כְּעִנְיָן שֶׁנֶּאֱמַר ״וּמֹחַ עַצְמוֹתָיו יְשֻׁקֶּה״ (איוב כא:כד):",2,0],[3,9,"מֵהוֹנֶךָ. מִכָּל מַה שֶּׁחֲנָנְךָ, אֲפִלּוּ מִקּוֹל עָרֵב. (אַל תִּקְרִי מֵהוֹנֶךָ אֶלָּא מִגְּרוֹנֶךָ):",1,0],[3,9,"וּמֵרֵאשִׁית. אֵלּוּ תְּרוּמוֹת וּמַעַשְׂרוֹת:",2,0],[3,11,"מוּסַר ה׳ בְּנִי אַל תִּמְאָס. אִם יָבוֹאוּ עָלֶיךָ יִסּוּרִין, יִהְיוּ חֲבִיבִין עָלֶיךָ (תנחומא, יתרו טז):",1,0],[3,11,"וְאַל תָּקֹץ. מִלְּשׁוֹן ״קַצְתִּי בְחַיַּי״ (בראשית כז:מו):",2,0],[3,12,"וּכְאָב אֶת בֵּן יִרְצֶה. שֶׁרוֹצֶה בִּבְנוֹ לְהֵיטִיב לוֹ וִיפַיְּסֵהוּ לְאַחַר שֶׁמַּכֵּהוּ בַּשֵּׁבֶט, כֵּן יֶעֱרַב לְךָ הַטּוֹבָה אַחַר הַמַּכָּה:",1,0],[3,13,"אַשְׁרֵי אָדָם מָצָא חָכְמָה וְאָדָם יָפִיק תְּבוּנָה. שֶׁלּוֹמֵד חָכְמָה עַד שֶׁשְּׁגוּרָה הִיא לְהוֹצִיא מִפִּיו:",1,0],[3,14,"כִּי טוֹב סַחְרָהּ מִסְּחַר כָּסֶף. כָּל חִלּוּפִין שֶׁאָדָם מַחֲלִיף בִּסְחוֹרָה, זֶה נוֹטֵל זֶה וְזֶה נוֹטֵל זֶה. אֲבָל הָאוֹמֵר לַחֲבֵירוֹ: שְׁנֵה לִי פִּרְקְךָ וַאֲנִי אֶשְׁנֶה לְךָ פִּרְקִי, נִמְצְאוּ שְׁנֵיהֶם בְּיַד כָּל אֶחָד וְאֶחָד:",1,0],[3,14,"חָרוּץ. מִין זָהָב הוּא:",2,0],[3,15,"וְכָל־חֲפָצֶיךָ. כָּל חֲמֻדּוֹתֶיךָ:",1,0],[3,15,"לֹא יִשְׁווּ בָהּ. לֹא יִהְיוּ שָׁוִין בְּשָׁוְיָהּ וְדָמֵיהֶן בְּדָמֶיהָ:",2,0],[3,16,"בִּימִינָהּ. לַמְּיַמִּינִים בָּהּ וְעוֹסְקִים בָּהּ לִשְׁמָהּ, אֹרֶךְ יָמִים, וְכָל שֶׁכֵּן עֹשֶׁר וְכָבוֹד. וְלַמַּשְׂמִאילִים בָּהּ, שֶׁעוֹסְקִים בָּהּ שֶׁלֹּא לִשְׁמָהּ, מִכָּל מָקוֹם עֹשֶׁר וְכָבוֹד יֵשׁ (שבת סג.):",1,0],[3,18,"לַמַּחֲזִיקִים בָּהּ. לָאוֹחֲזִים בָּהּ, כְּמוֹ ״וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ״ (שמות ד:ד):",1,0],[3,18,"וְתוֹמְכֶיהָ מְאֻשָּׁר. הַמִּתְקָרְבִים לָהּ, וְכֵן כָּל לְשׁוֹן תְּמִיכָה שֶׁבְּסֵפֶר זֶה – שֶׁהוּא אוֹחֵז בָּהּ:",2,0],[3,19,"ה׳ בְּחָכְמָה יָסַד אָרֶץ. עַל פִּי הַתּוֹרָה, וְהִיא הַתּוֹרָה וְהִיא הַתְּבוּנָה וְהוּא הַדַּעַת. וְאַחַר שֶׁכָּל הָעוֹלָם נִבְרָא בָהֶם, לְכָךְ:",1,0],[3,20,"יִרְעֲפוּ. כְּמוֹ יַטִּיפוּ:",1,0],[3,21,"אַל יָלֻזוּ מֵעֵינֶיךָ. אַל יִתְעַקְּמוּ מִנֶּגֶד עֵינֶיךָ לַהֲסִירָם מִכְּנֶגְדְּךָ:",1,0],[3,22,"וְיִהְיוּ חַיִּים לְנַפְשֶׁךָ. שֶׁהֲרֵי עֵץ חַיִּים הוּא:",1,0],[3,22,"וְחֵן לְגַרְגְּרוֹתֶיךָ. שֶׁהֲרֵי זֶה שִׁבְחָהּ הָאָמוּר לְמַעְלָה ״וַעֲנָקִים לְגַרְגְּרוֹתֶיךָ״ (משלי א:ט):",2,0],[3,23,"לֹא תִגּוֹף. לְשׁוֹן כִּשָּׁלוֹן, אצופי״ר בְּלַעַ״ז, וְכֵן ״פֶּן תִּגּוֹף בָּאֶבֶן״ (תהלים צא:יב), וְכֵן ״בְּטֶרֶם יִתְנַגְּפוּ רַגְלֵיכֶם״ (ירמיה יג:טז), וְכֵן ״וְנָגְפוּ אִשָּׁה הָרָה״ (שמות כא:כב):",1,0],[3,24,"וְשָׁכַבְתָּ וְעָרְבָה שְׁנָתֶךָ. וְתִנְעַם שְׁנָתְךָ כְּשֶׁתִּישַׁן, שֶׁלֹּא תִירָא מִפַּחַד פִּתְאוֹם:",1,0],[3,25,"וּמִשּׁוֹאַת. כְּשֶׁתָּבוֹא עַל הָרְשָׁעִים:",1,0],[3,26,"כִּי ה׳ יִהְיֶה בְכִסְלֶךָ. בְּמִבְטַחֲךָ. דָּבָר אַחֵר: בַּדְּבָרִים שֶׁאַתָּה כְּסִיל בָּהֶן. כָּךְ מָצָאתִי בִּירוּשַׁלְמִי (פאה א:א):",1,0],[3,27,"אַל תִּמְנַע טוֹב מִבְּעָלָיו. אִם רָאִיתָ חֲבֵירְךָ חָפֵץ לְהֵיטִיב לָעֲנִיִּים, אַל תִּמְנָעֵהוּ:",1,0],[3,27,"בִּהְיוֹת לְאֵל יָדְךָ. לְהַחֲדִילוֹ. דָּבָר אַחֵר: אַל תִּמְנַע טוֹב מִבְּעָלָיו, אַל תִּמְנַע צְדָקָה מִן הֶעָנִי, בִּהְיוֹת לְאֵל יָדְךָ לַעֲשׂוֹת צְדָקָה, שֶׁמָּא יָבוֹא יוֹם וְאֵין לְאֵל יָדְךָ:",2,0],[3,28,"וְכֵן אַל תֹּאמַר לְרֵעֲךָ. לֶעָנִי:",1,0],[3,28,"וְיֵשׁ אִתָּךְ. מַה שֶּׁתִּתֵּן לוֹ. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (בבא מציעא קי:): לֵךְ וָשׁוּב; עַל ״שְׂכַר שָׂכִיר״ (דברים טו:יח):",2,0],[3,29,"אַל תַּחֲרֹשׁ עַל רֵעֲךָ. אַל תַּחְשֹׁב. וְאֵינוֹ זָז מִמַּשְׁמָעוּת חֲרִישָׁה: מַה דֶּרֶךְ הַחוֹרֵשׁ – מֵכִין מָקוֹם לִזְמַן הַזְּרִיעָה, אַף הַחוֹשֵׁב רָעָה מֵכִין מָקוֹם תַּחְבּוּלוֹת בְּלִבּוֹ, אֵיךְ יַעֲמֹד וְיַעֲשֶׂנָּה:",1,0],[3,30,"אַל תָּרִיב עִם אָדָם. לְהִתְלוֹנֵן עָלָיו:",1,0],[3,30,"אִם לֹא גְמָלְךָ רָעָה. שֶׁעָבַר עַל הַמִּצְוָה הַכְּתוּבָה בַּתּוֹרָה ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״ (ויקרא יט:יח). וּמִי שֶׁהוּא רָשָׁע, רַשַּׁאי אַתָּה לְשָׂנְאוֹ:",2,0],[3,31,"אַל תְּקַנֵּא בְּאִישׁ חָמָס. לַעֲשׂוֹת כְּמַעֲשָׂיו, אִם תִּרְאֵהוּ מַצְלִיחַ:",1,0],[3,32,"כִּי תוֹעֲבַת ה׳ נָלוֹז. מְעֻוָּת בִּדְרָכָיו:",1,0],[3,32,"וְאֶת יְשָׁרִים סוֹדוֹ. וְעִם יְשָׁרִים סוֹדוֹ:",2,0],[3,34,"אִם לַלֵּצִים. אָדָם נִמְשָׁךְ אַחֲרֵיהֶם, לְסוֹף אַף הוּא יִהְיֶה לֵץ עִמָּהֶם:",1,0],[3,34,"וְלַעֲנָוִים יִתֶּן חֵן. אִם לַעֲנָוִים יִתְחַבֵּר, סוֹף שֶׁיִּתְּנוּ מַעֲשָׂיו חֵן בְּעֵינֵיהֶם שֶׁל בְּרִיּוֹת:",2,0],[3,35,"כָּבוֹד חֲכָמִים יִנְחָלוּ וּכְסִילִים מֵרִים קָלוֹן. לְעַצְמוֹ מַפְרִישׁ קָלוֹן לְחֶלְקוֹ:",1,0],[4,1,"שִׁמְעוּ בָנִים מוּסַר אָב. הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[4,2,"נָתַתִּי לָכֶם. הַנָּבִיא מִתְנַבֵּא וּמְדַבֵּר בִּשְׁלִיחוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי הוּא כְּפִיו:",1,0],[4,3,"כִּי בֵן הָיִיתִי לְאָבִי. אִם תֹּאמַר: שְׁלֹמֹה הָיָה שׂוֹנֵא הַבְּרִיּוֹת, שֶׁהִזְהִירָן עַל הַגָּזֵל וְעַל הָעֲרָיוֹת, דָּבָר שֶׁנַּפְשׁוֹ שֶׁל אָדָם מִתְאַוָּה לָהֶם, לְכָךְ נֶאֱמַר: כִּי בֵן הָיִיתִי וְגוֹ׳ רַךְ וְיָחִיד וְגוֹ׳. שֶׁהָיָה אוֹהֵב אוֹתִי יוֹתֵר:",1,0],[4,4,"וַיּוֹרֵנִי. עַל כָּךְ וַיּוֹכִיחֵנִי וַיֹּאמֶר לִי יִתְמָךְ דְבָרַי לִבֶּךָ. וּלְפִי שֶׁהוֹכִיחֵנִי בִּדְבָרִים אֵלּוּ, לְכָךְ אֲנִי מַזְהִירְכֶם עַל כָּךְ (רבי יוסף קרא). דָּבָר אַחֵר: כִּי בֵן הָיִיתִי לְאָבִי, הַנָּבִיא אוֹמֵר: בֵּן הָיִיתִי לְהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִשְׁרָה רוּחוֹ עָלַי. וּמָצִינוּ שֶׁקְּרָאוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁלֹמֹה בֵּן, שֶׁנֶּאֱמַר ״אֲנִי אֶהְיֶה לּוֹ לְאָב וְגוֹ׳״ (שמואל ב ז:יד):",1,0],[4,4,"רַךְ וְיָחִיד לִפְנֵי אִמִּי. לְאֻמָּתִי אֲנִי נִבְחָר וְחָבִיב כְּבֵן רַךְ וְיָחִיד, לְכָךְ וַיּוֹרֵנִי אָבִי:",2,0],[4,6,"אַל תַּעַזְבֶהָ וְגוֹ׳ אֱהָבֶהָ. אֱהוֹב אוֹתָהּ:",1,0],[4,7,"רֵאשִׁית חָכְמָה קְנֵה חָכְמָה. תְּחִלַּת חָכְמָתְךָ לְמוֹד מֵאֲחֵרִים, קְנֵה לְךָ שְׁמוּעָה מִפִּי הָרַב, וְאַחַר כָּךְ בְּכָל קִנְיָנְךָ קְנֵה בִינָה, תִּתְבּוֹנֵן בָּהּ מֵעַצְמְךָ לְהַשְׂכִּיל הַטְּעָמִים, דָּבָר מִתּוֹךְ דָּבָר:",1,0],[4,8,"סַלְסְלֶהָ. חַפְּשֶׂהָ, הֱיֵה חוֹזֵר עָלֶיהָ לְדַקְדֵּק בָּהּ. כְּמוֹ ״כְּבוֹצֵר עַל סַלְסִלּוֹת״ (ירמיהו ו:ט) – הַחוֹזֵר וְהוֹלֵךְ בַּכֶּרֶם וּמֵשִׁיב יָדוֹ לְבַקֵּשׁ אֶת הָעוֹלֵלוֹת. וּבִלְשׁוֹן חֲכָמִים (תנחומא, וישב ח): מְסַלְסֵל בִּשְׂעָרוֹ:",1,0],[4,9,"תִּתֵּן לְרֹאשְׁךָ לִוְיַת חֵן. חֶבְרַת חֵן, כְּמוֹ ״לִוְיַת חֵן הֵם לְרֹאשֶׁךָ״ (משלי א:ט):",1,0],[4,10,"שמע בני וקח אמרי וגו':",1,0],[4,12,"בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ. מִי שֶׁאֵינוֹ מַרְחִיק רַגְלָיו, קָרוֹב לִיפּוֹל:",1,0],[4,13,"הַחֲזֵק בַּמּוּסָר אַל תֶּרֶף. אֱחוֹז בַּתּוֹרָה, כְּמוֹ ״וְהַחֲזִיקִי אֶת יָדֵךְ בּוֹ״ (בראשית כא:יח), ״וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ״ (שמות ד:ד):",1,0],[4,14,"בְּאֹרַח רְשָׁעִים אַל תָּבֹא וְאַל תְּאַשֵּׁר. וְאַל תִּדְרֹךְ, כְּמוֹ ״בַּאֲשֻׁרוֹ אָחֲזָה רַגְלִי״ (איוב כג:יא), וְכֵן ״וְנָבוֹן יָבִין לַאֲשֻׁרוֹ״ (משלי יד:טו):",1,0],[4,15,"פְּרָעֵהוּ. בַּטְּלֵהוּ:",1,0],[4,15,"שְׂטֵה מֵעָלָיו. סוּר:",2,0],[4,16,"כִּי לֹא יִשְׁנוּ. אֵינָם יְכוֹלִין לִישֹׁן:",1,0],[4,18,"וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. שֶׁהוֹלֵךְ וּמֵאִיר מֵעַמּוּד הַשַּׁחַר:",1,0],[4,18,"עַד נְכוֹן הַיּוֹם. עַד חֲצוֹת הַיּוֹם, שֶׁהוּא בֵּרוּרוֹ שֶׁל יוֹם:",2,0],[4,19,"דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ. פִּתְאוֹם יָבֹא לָהֶם מִכְשׁוֹל, וְלֹא יֵדְעוּ לְהִזָּהֵר מִמֶּנּוּ:",1,0],[4,20,"בְּנִי לִדְבָרַי הַקְשִׁיבָה וְגוֹ׳:",1,0],[4,22,"לְמוֹצְאֵיהֶם. לְשׁוֹן מְצִיאָה:",1,0],[4,23,"מִכָּל מִשְׁמָר. מִכָּל מַה שֶּׁאָמְרָה תּוֹרָה הִשָּׁמֶר נְצֹר לִבְּךָ (מֵעֲבוֹר עָלָיו), בֵּין עֲבֵרָה קַלָּה בֵּין עֲבֵרָה חֲמוּרָה:",1,0],[4,23,"כִּי מִמֶּנּוּ תּוֹצְאוֹת חַיִּים. כִּי מֵאוֹתוֹ שֶׁהוּא קַל יִהְיוּ לְךָ חַיִּים וְשָׂכָר גָּדוֹל אִם תְּקַיְּמֶנּוּ. כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, כי תצא ב):",2,0],[4,24,"הָסֵר מִמְּךָ עִקְּשׁוּת פֶּה. לֹא תַּעֲשֶׂה דָבָר שֶׁיַּלְעִיזוּ בּוֹ הַבְּרִיּוֹת וְיַעֲקִימוּ עָלֶיךָ פִּיהֶם:",1,0],[4,24,"עִקְּשׁוּת פֶּה. לְשׁוֹן עִקּוּם, כְּמוֹ ״תָּם אָנִי וַיַּעְקְּשֵׁנִי״ (איוב ט:כ). וּבַמִּשְׁנָה (חולין נו.): שִׁנֶּיהָ עֲקוּמוֹת וַעֲקוּשׁוֹת:",2,0],[4,24,"וּלְזוּת שְׂפָתַיִם. עִקְּמִימוּת שְׂפָתַיִם, שֶׁלֹּא יַרְחִיבוּ הַבְּרִיּוֹת פֶּה עָלֶיךָ:",3,0],[4,25,"עֵינֶיךָ לְנֹכַח יַבִּיטוּ. יִסְתַּכְּלוּ אֶל הָאֱמֶת וְאֶל הַיֹּשֶׁר:",1,0],[4,25,"יַיְשִׁרוּ נֶגְדֶּךָ. יִסְתַּכְּלוּ עַל הַיְשָׁרָה, לְיַשֵּׁר דַּרְכְּךָ נֶגְדֶּךָ:",2,0],[4,26,"פַּלֵּס מַעְגַּל רַגְלֶךָ. שְׁקוֹל דַּרְכְּךָ: הֶפְסֵד מִצְוָה כְּנֶגֶד שְׂכָרָהּ, וּשְׂכַר עֲבֵרָה כְּנֶגֶד הֶפְסֵדָהּ (אבות ב:א), וְאָז כָּל דְּרָכֶיךָ יִכֹּנוּ:",1,0],[4,27,"אַל תֵּט יָמִין וּשְׂמֹאול. מִן הַמִּשְׁקָל הַטּוֹב:",1,0],[5,1,"בְּנִי לְחָכְמָתִי הַקְשִׁיבָה וְגוֹ׳:",1,0],[5,3,"כִּי נֹפֶת תִּטֹּפְנָה. לְשׁוֹן ״מָתוֹק״ (משלי כד:יג):",1,0],[5,3,"שִׂפְתֵי זָרָה. אֲפִיקוֹרְסוּת:",2,0],[5,3,"וְחָלָק מִשֶּׁמֶן חִכָּהּ. לְשׁוֹן ״חֵךְ״ (איוב יב:יא):",3,0],[5,5,"רַגְלֶיהָ יוֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמֹכוּ. לְשׁוֹן קוּרְבָה:",1,0],[5,6,"אֹרַח חַיִּים פֶּן תְּפַלֵּס. כָּךְ דְּרָשׁוּהוּ חֲכָמִים (דברים רבה ו:ב): סִלְסֵל הַקָּדוֹשׁ בָּרוּךְ הוּא מַתַּן שְׂכָרָן שֶׁל מִצְווֹת וְלֹא פֵּרְשָׁן, כְּדֵי שֶׁלֹּא יִרְאֶה אָדָם מִצְוָה שֶׁמַּתַּן שְׂכָרָהּ מְרֻבֶּה וְיִדְבַּק בָּהּ, וְיַנִּיחַ שְׁאָר הַמִּצְווֹת. וְזֶה פִּתְרוֹנוֹ: כְּדֵי שֶׁלֹּא תְּפַלֵּס אָרְחוֹת הַתּוֹרָה, אֵי זוֹ לִיקַּח וְאֵי זוֹ לְהַנִּיחַ, לְכָךְ נָעוּ מַעְגְּלֹתֶיהָ. הֵנִיעַ הַקָּדוֹשׁ בָּרוּךְ הוּא נְתִיבוֹתֶיהָ וְלֹא הוֹדִיעָם. זֶהוּ מִדְרַשׁ אַגָּדָה (תנחומא, עקב ב). אֲבָל לְפִי סֵדֶר הַמִּקְרָאוֹת שֶׁכָּתוּב אַחֲרָיו הַרְחֵק מֵעָלֶיהָ דַרְכֶּךָ – נִרְאֶה, שֶׁעֲדַיִן לֹא הִפְסִיק בְּעִנְיַן אִשָּׁה הַזּוֹנָה, וְכֵן יֵשׁ לְפָרֵשׁ: אֹרַח חַיִּים פֶּן תְּפַלֵּס. אַל תִּשְׁקֹל אֹרַח חַיִּים אֵצֶל אוֹתָהּ זָרָה, לוֹמַר: אֵיזוֹ לַעֲשׂוֹת זוֹ אוֹ זוֹ? כִּי מַעְגְּלוֹת הַזּוֹנָה נָעוּ לִשְׁאוֹל, וְלֹא תֵדַע לְהִזָּהֵר עַד אֲשֶׁר תָּנוּעַ וְתִפּוֹל:",1,0],[5,7,"וְעַתָּה בָנִים שִׁמְעוּ לִי וְאַל תָּסוּרוּ מֵאִמְרֵי פִי:",1,0],[5,9,"פֶּן תִּתֵּן לַאֲחֵרִים הוֹדֶךָ. פֶּן תַּפְנֶה לִבְּךָ לֵאלֹהִים אֲחֵרִים, לָתֵת לָהֶם תִּפְאֶרֶת הוֹדְךָ וְשִׁבְחֲךָ:",1,0],[5,9,"וּשְׁנוֹתֶיךָ לְאַכְזָרִי. לְשַׂר שֶׁל גֵּיהִנֹּם:",2,0],[5,10,"פֶּן יִשְׂבְּעוּ זָרִים כֹּחֶךָ. נְבִיאֵי הַבַּעַל הַגּוֹבִין מָמוֹן בְּשִׁקְרֵיהֶם וּבְפַחֲזוּתָם (ירמיהו כג:לב):",1,0],[5,10,"וַעֲצָבֶיךָ. עֲצָבֶיךָ וִיגִיעֲךָ, שֶׁנֶּעֱצַבְתָּ וְטָרַחְתָּ בּוֹ:",2,0],[5,10,"בְּבֵית נָכְרִי. בְּבֵית עוֹבְדֵי גִּלּוּלִים:",3,0],[5,11,"וְנָהַמְתָּ בְאַחֲרִיתֶךָ. סוֹף שֶׁתִּנְהוֹם בְּאַחֲרִיתֶךָ:",1,0],[5,14,"כִּמְעַט הָיִיתִי בְכָל רָע. כְּפֶשַׂע בֵּינִי וּבֵין גֵּיהִנֹּם, (כְּלוֹמַר: בִּשְׁבִיל דָּבָר מוּעָט הָיִיתִי עַכְשָׁיו בְּכָל רָע, שֶׁלֹּא שָׁמַעְתִּי לְקוֹל מוֹרַי; שֶׁאִלּוּ שָׁמַעְתִּי לָהֶם, לֹא יֶאֱרַע בִּי כָּךְ רבי יוסף קרא):",1,0],[5,15,"שְׁתֵה מַיִם מִבּוֹרֶךָ. מִבּוֹר שֶׁנָּתַן לְךָ הַקָּדוֹשׁ בָּרוּךְ הוּא לְחֶלְקְךָ, הִיא תּוֹרַת מֹשֶׁה:",1,0],[5,15,"בּוֹרֶךָ. מַיִם מְכֻנָּסִים:",2,0],[5,15,"וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךָ. מַיִם חַיִּים. כְּלוֹמַר: תְּחִלָּה כְּמַיִם מְכֻנָּסִים, וּלְבַסּוֹף נוֹבְעִין הֵם וְהוֹלְכִין:",3,0],[5,16,"יָפוּצוּ מַעְיְנוֹתֶיךָ חוּצָה. סוֹף שֶׁתִּקְנֶה תַּלְמִידִים, וְתוֹרֶה הוֹרָאוֹת בָּרַבִּים, וְיֵצֵא לְךָ שֵׁם:",1,0],[5,16,"בָּרְחוֹבוֹת. עִיר תְּפוּצֶינָה פַּלְגֵי מֵימֶיךָ:",2,0],[5,17,"יִהְיוּ לְךָ לְבַדֶּךָ. אַתָּה לְבַדְּךָ תִּתְכַּבֵּד בָּהֶם, וְלֹא יַחֲלֹק אַחֵר עִמְּךָ. לְפִי שֶׁאָמַר לְמַעְלָה פֶּן יִשְׂבְּעוּ זָרִים כֹּחֶךָ, אָמַר כָּאן יִהְיוּ לְךָ לְבַדֶּךָ; וּמִתּוֹךְ כָּךְ:",1,0],[5,18,"יְהִי מְקוֹרְךָ בָרוּךְ וּשְׂמַח מֵאֵשֶׁת נְעוּרֶיךָ. הִיא הַתּוֹרָה שֶׁלָּמַדְתָּ מִנְּעוּרֶיךָ:",1,0],[5,19,"תִּשְׁגֶּה תָמִיד. רָאִיתִי בְּדִבְרֵי רַבִּי מֹשֶׁה הַדַּרְשָׁן: תִּשְׁגֶּה. תַּעֲסֹק תָּמִיד, וְהוּא לְשׁוֹן עֲרָבִי. וְהֵבִיא רְאָיָה, כְּמוֹ ׳לְבַקֵּשׁ שְׁגִייָה – לְבַקֵּשׁ עֵסֶק׳; וְלֹא יָדַעְתִּי אֵיפֹה נִשְׁנֵית. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (עירובין נד:): לְשׁוֹן ׳מַשְׁגֶּה׳ כְּמַשְׁמָעוֹ: בַּעֲבוּר אַהֲבָתָהּ תִּהְיֶה שׁוֹגֵג בִּשְׁאָר עֲסָקֶיךָ, כִּי הִיא מְשַׁמֶּרֶת עַל שֶׁלְּךָ. אָמְרוּ עָלָיו עַל רַבִּי אֱלִיעֶזֶר בֶּן פְּדָת, שֶׁהָיָה דּוֹרֵשׁ בַּשּׁוּק הַתַּחְתּוֹן, וְסְדִינוֹ מֻטָּל בַּשּׁוּק הָעֶלְיוֹן. פַּעַם אַחַת בָּא אָדָם אֶחָד וּמָצָא נָחָשׁ כָּרוּךְ עָלָיו:",1,0],[5,21,"כִּי נֹכַח עֵינֵי ה׳ דַּרְכֵי אִישׁ וְגוֹ׳ מְפַלֵּס. – שׁוֹקֵל דְּרָכָיו וְיוֹדֵעַ כַּמָּה עֲוֹנוֹת וְכַמָּה זְכֻיּוֹת בְּיָדוֹ:",1,0],[5,22,"עֲווֹנוֹתָיו יִלְכְּדֻנוֹ. כְּמוֹ יִלְכְּדוּהוּ:",1,0],[5,22,"וּבְחַבְלֵי חַטָּאתוֹ יִתָּמֵךְ. יִתָּלֶה, שֶׁהַתָּלוּי נִתְמָךְ בַּחֶבֶל שֶׁהוּא תָּלוּי בָּהּ:",2,0],[5,23,"הוּא יָמוּת בְּאֵין מוּסָר. בִּשְׁבִיל שֶׁלֹּא לָקַח מוּסָר:",1,0],[6,1,"בְּנִי אִם עָרַבְתָּ. עֲרֵבוּת מָמוֹן כְּמַשְׁמָעוֹ, פֵּרְשׁוּ רַבּוֹתֵינוּ (בבא בתרא קעג:):",1,0],[6,2,"נוֹקַשְׁתָּ בְאִמְרֵי פִיךָ. שֶׁתָּקַעְתָּ כַּף לְהִדָּבֵר עִם הַזָּרִים (יומא פז.):",1,0],[6,3,"לֵךְ הִתְרַפֵּס. הַתֵּר לוֹ פַּס יָד, לְשַׁלֵּם לוֹ מָמוֹנוֹ:",1,0],[6,3,"וּרְהַב רֵעֶיךָ. וְאִם אֵין לוֹ מָמוֹן עִמְּךָ, אֶלָּא שֶׁנּוֹקַשְׁתָּ בְּאִמְרֵי פִיךָ לְדַבֵּר לוֹ קָשׁוֹת, הַרְבֵּה עָלָיו רֵעִים לְבַקֵּשׁ מִמֶּנּוּ שֶׁיִּמְחוֹל לְךָ:",2,0],[6,3,"דָּבָר אַחֵר: בְּנִי אִם עָרַבְתָּ לְרֵעֶךָ. אַחַר שֶׁנַּעֲשֵׂיתָ עָרֵב לְהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא רֵעֲךָ, כְּדִכְתִיב ״זֶה דוֹדִי וְזֶה רֵעִי״ (שיר השירים ה:טז), וְקִבַּלְתָּ עָלֶיךָ בְּסִינַי וּבְעַרְבוֹת מוֹאָב בְּאָלָה וּבִשְׁבוּעָה לִשְׁמֹר מִצְווֹתָיו:",3,0],[6,3,"תָּקַעְתָּ לַזָּר כַּפֶּיךָ. שֶׁתָּשׁוּב וְתָסוּר מִדְּרָכָיו וְתִדְבַּק בָּאֶפִּיקוֹרְסִין לָלֶכֶת בְּדַרְכֵיהֶם:",4,0],[6,3,"נוֹקַשְׁתָּ בְּאִמְרֵי פִיךָ. שֶׁתָּקַעְתָּ כַּף לְהִדָּבֵר עִם הַזָּרִים:",5,0],[6,3,"עֲשֵׂה זֹאת אֵפוֹא בְּנִי וְהִנָּצֵל. הוֹאִיל וּבָאתָ בְכַף רֵעֶךָ בְּסִינַי, וְקִבַּלְתָּ אֱלֹהוּתוֹ עָלֶיךָ:",6,0],[6,3,"לֵךְ הִתְרַפֵּס. הִכָּנַע לְפָנָיו כַּאֲסְקוּפָּה הַנִּרְפֶּסֶת וְנִדְרֶסֶת:",7,0],[6,3,"וּרְהַב רֵעֶיךָ. הַרְבֵּה רֵעִים שֶׁיִּתְפַּלְּלוּ עָלֶיךָ לְפָנָיו. וְכֵן נִדְרַשׁ בְּמִדְרַשׁ תְּהִלִּים :",8,0],[6,5,"הִנָּצֵל כִּצְבִי מִיָּד. מַהֵר וְהִשָּׁמֵט מִשָּׁם כִּצְבִי הַנִּמְלָט מִיַּד הָאָדָם:",1,0],[6,6,"לֵךְ אֶל נְמָלָה עָצֵל וְגוֹ׳. וַחֲכָם – וְהִתְחַכֵּם:",1,0],[6,7,"אֲשֶׁר אֵין לָהּ קָצִין. שֶׁיּוֹכִיחַ אוֹתָהּ וִיזָרְזֶנָּה וְיוֹצִיא מִיָּדָהּ אִם תִּגְזֹל דָּבָר מֵחֲבֶרְתָּהּ, וְאַף עַל פִּי כֵן:",1,0],[6,8,"תָּכִין בַּקַּיִץ לַחְמָהּ אָגְרָה בַקָּצִיר מַאֲכָלָהּ. מְזוֹנָהּ, כָּל אַחַת וְאַחַת אֵינָהּ גּוֹזֶלֶת מֵחֲבֶרְתָּהּ:",1,0],[6,10,"חִבּוּק יָדַיִם. הַיָּשֵׁן חוֹבֵק יָדָיו, אַבְרַאצַ״ר בְּלַעַ״ז:",1,0],[6,11,"וּבָא כִמְהַלֵּךְ רֵאשֶׁךָ. אִם תַּעֲשֶׂה כֵּן יָבֹא חֶסְרוֹנְךָ, וְדָבָר שֶׁאַתָּה רָשׁ מִמֶּנּוּ יָבֹא לְךָ מִיָּד, כְּאָדָם הַמְהַלֵּךְ מַהֵר; וּמַחְסֹרְךָ יָבֹא וְיִתְמַלֵּא:",1,0],[6,11,"כְּאִישׁ מָגֵן. הַבָּא מַהֵר לְהָגֵן עַל אֲדוֹנָיו. הַמִּקְרָאוֹת אֵלּוּ – עִקָּרָן מָשָׁל עַל הַמִּתְעַצְּלִין לַעֲסֹק בַּתּוֹרָה:",2,0],[6,12,"הוֹלֵךְ עִקְּשׁוּת פֶּה. הַהוֹלֵךְ בַּעֲקִימַת שְׂפָתַיִם:",1,0],[6,13,"קוֹרֵץ בְּעֵינָיו. רְמִיזוֹת שֶׁל מִרְמָה:",1,0],[6,13,"מוֹלֵל בְּרַגְלָיו. כְּלוֹמַר: מְשַׁפְשֵׁף זֶה עַל זֶה:",2,0],[6,13,"וּמֹרֶה בְּאֶצְבְּעוֹתָיו. כֻּלָּם מִן לְשׁוֹן רְמָזִים הֵם, זֶה נוֹפֵל עַל הָעַיִן וְזֶה נוֹפֵל עַל הָרֶגֶל וְזֶה נוֹפֵל עַל הָאֶצְבַּע. וְהָעִקָּר – הוּא מְדַבֵּר עַל הָרְשָׁעִים הַמְּסִיתִין אֶת הַבְּרִיּוֹת לַעֲבוֹדָת גִּלּוּלִים:",3,0],[6,14,"מִדְיָנִים יְשַׁלֵּחַ. בֵּין אָדָם לְבוֹרְאוֹ:",1,0],[6,15,"פִּתְאוֹם. וּפֶתַע לְשׁוֹן תְּכִיפָה הִיא. וְלֹא יָדַע אֶת הַמַּפָּלָה הַקְּרוֹבָה לִפּוֹל עָלָיו:",1,0],[6,16,"שֵׁשׁ הֵנָּה שָׂנֵא ה׳ וְשֶׁבַע. תּוֹעֲבַת נַפְשׁוֹ, כְּלוֹמַר: גַּם הַשְּׁבִיעִית עִמָּהֶם:",1,0],[6,19,"יָפִיחַ. לְשׁוֹן דִּבּוּר הוּא, כִּי כָל דִּבּוּר בְּרוּחַ הַפֶּה הוּא:",1,0],[6,20,"נְצֹר בְּנִי מִצְוַת אָבִיךָ:",1,0],[6,21,"עָנְדֵם. לְשׁוֹן קֶשֶׁר הוּא, כְּמוֹ ״אֶעֶנְדֶנּוּ עֲטָרוֹת לִי״ (איוב לא:לו):",1,0],[6,22,"בְּהִתְהַלֶּכְךָ. בְּחַיֶּיךָ:",1,0],[6,22,"תַּנְחֶה אוֹתָךְ. כְּמוֹ תַּנְהִיגְךָ:",2,0],[6,22,"בְּשָׁכְבְּךָ. בַּקֶּבֶר:",3,0],[6,22,"וְהַקִיצוֹתָ הִיא תְשִׂיחֶךָ. לִתְחִיַּת הַמֵּתִים, לַעֲמֹד בַּדִּין:",4,0],[6,22,"הִיא תְשִׂיחֶךָ. תָּלִיץ בַּעֲדֶךָ (תנחומא, ויצא ב):",5,0],[6,23,"כִּי נֵר מִצְוָה וְתוֹרָה אוֹר. כְּמוֹ שֶׁהָאוֹר מֵאִיר לָעוֹלָם תָּמִיד, כָּךְ הַתּוֹרָה עוֹמֶדֶת זְכוּתָהּ לְעוֹלָם אֶל הָאָדָם; וּזְכוּת מִצְוָה לְפִי שָׁעָה, כְּאוֹר הַנֵּר. דָּבָר אַחֵר: כִּי נֵר מִצְוָה וְגוֹ׳ מִצְוַת הָאָב הוּא נֵר: כָּל מִי שֶׁמְּקַיֵּם מִצְוַת אָבִיו, כְּאִלּוּ נוֹטֵל נֵר בְּיָדוֹ לְהַדְלִיק בִּמְקוֹם חֹשֶׁךְ, וְאִם אָבַד שׁוּם דָּבָר, שָׁם הוּא מוֹצְאוֹ לְאוֹרוֹ. וְכֵן מִי שֶׁהוּא מְקַיֵּם הוֹרָאַת אִמּוֹ, אוֹרָה הִיא לוֹ; וְכֵן הוּא אוֹמֵר ״אַל תִּטֹּשׁ תּוֹרַת אִמֶּךָ״ (משלי א:ח). וְכֵן הוּא וַדַּאי, שֶׁמִּקְרָא זֶה מְדַבֵּר בְּמִצְוַת אָבִיו וְאִמּוֹ, דִּכְתִיב ״מְקַלֵּל אָבִיו וְאִמּוֹ יִדְעַךְ נֵרוֹ בֶּאֱשׁוּן חֹשֶׁךְ״ (משלי כ:כ). וְאִם נֵר שֶׁל אָדָם יִדְעַךְ (כּוֹהֶה) כְּשֶׁאֵין מְקַיֵּם מִצְוֹת, נִמְצָא כְּשֶׁמְּקַיֵּם מִצְוֹת, מֵאִיר נֵרוֹ (רבי יוסף קרא):",1,0],[6,23,"וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. תּוֹכְחוֹת הַמּוּסָר הֵם מַטִּים אֶת הָאָדָם לְחַיִּים, נִמְצָא שֶׁהֵם דֶּרֶךְ הַחַיִּים:",2,0],[6,24,"לִשְׁמָרְךָ מֵאֵשֶׁת רָע. הַתּוֹרָה תִּשְׁמָרְךָ מֵאִשָּׁה שֶׁל מִנְהָג רָע. וְעַל כָּרְחֲךָ לֹא דִּבֵּר שְׁלֹמֹה אִשָּׁה רָעָה, אֶלָּא כְּנֶגֶד עֲבוֹדַת גִּלּוּלִים שֶׁהִיא שְׁקוּלָה כְּנֶגֶד הַכֹּל. שֶׁאִם תֹּאמַר: אִשָּׁה זוֹנָה מַמָּשׁ, וְכִי כָּל שְׂכָרָהּ וְשִׁבְחָהּ שֶׁל תּוֹרָה שֶׁשּׁוֹמֶרֶת מִן הַזּוֹנָה לְבַדָּהּ?! אֶלָּא עַל כָּרְחֲךָ זוֹ עֲבוֹדַת גִּלּוּלִים, שֶׁהִיא חֲמוּרָה כְּנֶגֶד הַכֹּל:",1,0],[6,24,"מֵחֶלְקַת לָשׁוֹן. מִטְּחוֹת עֵינַיִם שֶׁל לָשׁוֹן נָכְרִיָּה:",2,0],[6,25,"וְאַל תִּקָּחֲךָ. וְאַל תִּטּוֹל חָכְמָתְךָ מִמְּךָ בְּעַפְעַפֵּי עֵינֶיהָ, שֶׁקּוֹרֶצֶת בָּהֶם, בְּעַפְעַפֶּיהָ:",1,0],[6,26,"כִּי בְעַד אִשָּׁה זוֹנָה עַד כִּכַּר לָחֶם. לִידֵי עֲנִיּוּת וְחֹסֶר כָּל טוֹב:",1,0],[6,26,"נֶפֶשׁ יְקָרָה תָצוּד. נֶפֶשׁ שֶׁהָיְתָה יְקָרָה קוֹדֶם לָכֵן, בָּאָה וְצָדָה לְגֵיהִנֹּם (סוטה ד:):",2,0],[6,27,"הֲיַחְתֶּה אִישׁ. הֲיִשְׁאַב אִישׁ גֶּחָלִים בְּשִׁפּוּלֵי בְגָדָיו וְלֹא יִשָּׂרְפוּ?! כָּל לְשׁוֹן חֲתִיַּת גֶּחָלִים לְשׁוֹן שְׁאִיבָה הוּא כְּמַשְׁמָעָהּ: כְּשֶׁמְּמַלֵּא הַכְּלִי בְּתוֹךְ הַמְּדוּרָה:",1,0],[6,29,"אֶל אֵשֶׁת רֵעֵהוּ. כְּמַשְׁמָעוֹ. וְאַף עַל עֲבוֹדָת גִּלּוּלִים יֵשׁ לְדָרְשָׁהּ (שמות רבה לג:ז), שֶׁהִיא מְיֻחֶדֶת לַגּוֹיִם וְלֹא לְךָ:",1,0],[6,30,"לֹא יָבוּזוּ וְגוֹ׳ וְנִמְצָא יְשַׁלֵּם וְגוֹ׳ נֹאֵף אִשָּׁה וְגוֹ׳. שְׁלָשְׁתָּם מְחֻבָּרִים בְּדִבּוּר אֶחָד. אִם יִגְנֹב הַגַּנָּב גְּנֵבָה אֵין לְבַזּוֹתוֹ כָּל כָּךְ כְּמוֹ הַנּוֹאֵף, לָמָּה כִּי לְרַעֲבוֹן נַפְשׁוֹ הוּא עוֹשֶׂה וְאוּלַי אֵין לוֹ מַה יֹּאכַל, וּכְשֶׁנִּמְצָא יֵשׁ לוֹ תַּקָּנָה בְּתַשְׁלוּמִין, וּלְכָל הַיּוֹתֵר יְשַׁלֵּם שִׁבְעָתַיִם כְּלוֹמַר תַּשְׁלוּמֵי כֶּפֶל הַרְבֵּה וַאֲפִלּוּ חֲמִשִּׁים עַל אֶחָד, וְיֵשׁ מְפָרְשִׁים שִׁבְעָתַיִם כְּמוֹ גּוֹנֵב שׁוֹר וְכֵלָיו וּטְבָחוֹ שֶׁמְּשַׁלֵּם חֲמִשָּׁה בָקָר וְתַשְׁלוּמֵי כֶּפֶל עַל הַכֵּלִים (שמות כא:לז) הֲרֵי שִׁבְעָה: אֶת כָּל הוֹן בֵּיתוֹ יִתֵּן. וַאֲפִלּוּ צָרִיךְ לִמְכֹּר כָּל אֲשֶׁר לוֹ עַל זֶה מִכָּל מָקוֹם יֵשׁ לוֹ תַּקָּנָה וּמִתְּחִלָּה מֵחֲמַת רָעָב עָשָׂה, אֲבָל:",1,0],[6,32,"נוֹאֵף אִשָּׁה חֲסַר לֵב. הוּא, שֶׁהֲרֵי לֹא לְרַעֲבוֹן עָשָׂה:",1,0],[6,32,"מַשְׁחִית נַפְשׁוֹ הוּא יַעֲשֶׂנָּה. הַזִּמָּה:",2,0],[6,33,"נֶגַע וְקָלוֹן יִמְצָא. עַל עֲבוֹדַת גִּלּוּלִים וְעַל גִּלּוּי עֲרָיוֹת הַנְּגָעִים בָּאִים:",1,0],[6,34,"כִּי קִנְאָה. מִתְקַנֵּא בּוֹ לְהִפָּרַע בּוֹ חֲמָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא גִּבּוֹר עַל כֹּל, וְלֹא יַחְמוֹל בְּיוֹם נָקָם:",1,0],[6,35,"לֹא יִשָּׂא. פָּנִים, לְכָל מָמוֹן לְכַפֵּר עַל אֲשֶׁר כָּפַר בּוֹ וְנִדְבַּק בַּעֲבוֹדַת גִּלּוּלִים. וְרַבּוֹתֵינוּ דָּרְשׁוּ (תוספתא בבא קמא ז:יג): לֹא יָבוּזוּ לַגַּנָּב, זֶה הַמִּתְגַּנֵּב מֵאַחַר חֲבֵירוֹ הוֹלֵךְ לְבֵית הַמִּדְרָשׁ וְעוֹסֵק בַּתּוֹרָה, וְנִמְצָא יְשַׁלֵּם שִׁבְעָתַיִם, סוֹפוֹ שֶׁמִּתְמַנֶּה דַּיָּן וּמוֹרֶה הוֹרָאוֹת שֶׁאֵין שִׁבְעָתַיִם אֶלָּא תּוֹרָה שֶׁנֶּאֱמַר ״מְזֻקָּק שִׁבְעָתָיִם״ (תהלים יב:ז):",1,0],[7,1,"בני שמור אמרי ומצותי:",1,0],[7,2,"וְתוֹרָתִי כְּאִישׁוֹן עֵינֶיךָ. שָׁחוֹר שֶׁל עַיִן שֶׁהוּא דּוֹמֶה לַחֹשֶׁךְ, כְּמוֹ אִישׁוֹן לַיְלָה:",1,0],[7,4,"(אֲחוֹתִי אָתְּ. קָרְבֶנָּה אֵלֶיךָ):",1,0],[7,4,"וּמוֹדָע. קָרוֹב, כְּמוֹ ״בֹּעַז מוֹדַעְתֵּנוּ״ (רות ג:ב) – קְרוֹבֵנוּ. כְּלוֹמַר: קָרְבֶנָּה אֶצְלְךָ תָּמִיד:",2,0],[7,7,"אָבִינָה. הִבְחַנְתִּי וְרָאִיתִי:",1,0],[7,8,"אֵצֶל פִּנָּה. פִּנָּה שֶׁל זוֹנָה וַעֲבוֹדַת גִּלּוּלִים:",1,0],[7,10,"וְהִנֵּה אִשָּׁה. כְּמַשְׁמָעָהּ. דָּבָר אַחֵר: אֶחָד מִן אֶפִּיקוֹרְסִים:",1,0],[7,10,"שִׁית זוֹנָה. כְּמוֹ ״שְׁתוֹתֵיהֶם״ (שמואל ב י:ד), כְּלוֹמַר: עֶרְוַת זוֹנָה:",2,0],[7,10,"וּנְצוּרַת לֵב. כְּמוֹ ״עִיר נְצוּרָה״ (ישעיה א:ח) הַמּוּקֶּפֶת כַּרְכּוֹם, וְכֵן לִבָּהּ שֶׁל זוֹ מוּקֶּפֶת זִמָּה אִוֶּלֶת:",3,0],[7,11,"וְסוֹרָרֶת. סָרָה מִן הַדֶּרֶךְ:",1,0],[7,14,"זִבְחֵי שְׁלָמִים עָלָי. כְּלוֹמַר: סְעוּדָּה גְּדוֹלָה הֲכִינוֹתִי, כִּי הַיּוֹם הִקְרַבְתִּי נְדָרַי וּשְׁלָמַי:",1,0],[7,15,"וָאֶמְצָאֶךָּ. כְּדֵי שֶׁאֶמְצָאֶךָּ:",1,0],[7,16,"מַרְבַּדִּים. בִּגְדֵי חֹפֶשׁ וְנוֹי, וְדֻגְמָתוֹ בְּסוֹף הַסֵּפֶר, שֶׁנֶּאֱמַר ״מַרְבַדִּים עָשְׂתָה לָּהּ״ (משלי לא:כב):",1,0],[7,16,"רָבַדְתִּי עַרְשִׂי. קִשַּׁטְתִּי:",2,0],[7,16,"חֲטוּבוֹת אֵטוּן מִצְרָיִם. מְהֻלָּלוֹת בִּגְדֵי כְּלֵי פִשְׁתָּן חֲשׁוּבִין הַבָּאִים מִמִּצְרַיִם, שֶׁשָּׁם הַפִּשְׁתָּן מָצוּי, כְּדִכְתִיב בְּסֵפֶר (ישעיהו יט:ט) ״וּבֹשׁוּ עֹבְדֵי פִשְׁתִּים״. אֵטוּן תַּרְגּוּם ״מֵיתְרֵיהֶם״ (שמות לה:יח) ״אֲטוּנֵיהוֹן״:",3,0],[7,17,"נַפְתִּי מִשְׁכָּבִי. הֲנִיפוֹתִי הָרֵיחַ, כְּמֵנִיף בְּסוּדָר בְּבֵית הַבֹּשֶׂם, לְהָבִיא הָרֵיחַ מִלְמַעְלָה לְמַטָּה. וְדוּנָשׁ פֵּרֵשׁ לְשׁוֹן קִטּוּר, וְאָמַר שֶׁאֵין לוֹ דִּמְיוֹן:",1,0],[7,19,"כִּי אֵין הָאִישׁ בְּבֵיתוֹ. רְאִיתֶם שֶׁסִּלֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁכִינָתוֹ, וְכָל טוֹב נָתַן לְעוֹבְדֵי גִּלּוּלִים:",1,0],[7,20,"צְרוֹר הַכֶּסֶף. הַטּוֹבִים שֶׁבָּהֶם הָרַג:",1,0],[7,20,"לְיוֹם הַכֵּסֶא. לִזְמַן הַמּוֹעֵד הַקָּבוּעַ, וְכֵן ״בַּכֶּסֶה לְיוֹם חַגֵּנוּ״ (תהלים פא:ד):",2,0],[7,21,"הִטַּתּוּ. לְאוֹתוֹ חֲסַר לֵב (משלי ז:ז) אֵלֶיהָ:",1,0],[7,21,"בְּרֹב לִקְחָהּ. שֶׁהִיא לְמוּדָה לְהַרְגִּיל בְּכָךְ אֲנָשִׁים:",2,0],[7,21,"בְּחֵלֶק שְׂפָתֶיהָ. בְּדִבּוּר חֲלַקְלַק תַּדִּיחֶנּוּ מִן הַדֶּרֶךְ:",3,0],[7,22,"וּכְעֶכֶס. זֶה אֶרֶס נָחָשׁ:",1,0],[7,22,"אֶל מוּסַר אֱוִיל. כְּנָחָשׁ הַמְּמַהֵר לָרוּץ בִּשְׁלִיחוּת הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַסֵּר הָאֱוִיל, הַמְחֻיָּב לַמָּקוֹם בָּרוּךְ הוּא, כֵּן זֶה רָץ אַחֲרֶיהָ עַד שֶׁנִּכְשַׁל בָּהּ, וַיְפַלַּח חִצָּהּ אֶת כְּבֵדוֹ:",2,0],[7,23,"כְּמַהֵר צִפּוֹר. לָרוּץ אֶל הַפַּח, וְאֵינוֹ יוֹדֵעַ כִּי הַפַּח נִפְרַשׂ שָׁם בְּנַפְשׁוֹ שֶׁל צִפּוֹר:",1,0],[7,24,"וְעַתָּה בָנִים שִׁמְעוּ לִי וְגוֹ׳:",1,0],[8,1,"הֲלֹא חָכְמָה תִקְרָא. הֲלֹא הַתּוֹרָה מַכְרֶזֶת אֲלֵיכֶם דְּבָרִים הָאֲמוּרִים לְמַטָּה בָּעִנְיָן:",1,0],[8,3,"לְפִי קָרֶת. תִּקְרָה הַנְּתוּנָה עַל הַשַּׁעַר, וְיוֹשְׁבִים עָלֶיהָ:",1,0],[8,3,"תָּרֹנָּה. תִּזְעַקְנָה. וּמָה הִיא אוֹמֶרֶת? אֲלֵיכֶם אִישִׁים אֶקְרָא:",2,0],[8,6,"שִׁמְעוּ כִּי נְגִידִים אֲדַבֵּר. דִּבְרֵי נְגִידוּת וַחֲשִׁיבוּת:",1,0],[8,8,"נִפְתָּל וְעִקֵּשׁ. עַקְמוּמִיּוּת:",1,0],[8,10,"מֵחָרוּץ. מִמִּינֵי הַזָּהָב הוּא:",1,0],[8,11,"מִפְּנִינִים. מַרְגָּלִיּוֹת:",1,0],[8,11,"לֹא יִשְׁווּ בָהּ. לֹא יִדְמוּ לְשָׁוְיָהּ:",2,0],[8,12,"שָׁכַנְתִּי עָרְמָה. אֵצֶל עָרְמָה, שֶׁכֵּיוָן שֶׁלָּמַד אָדָם תּוֹרָה, נִכְנַס בּוֹ עַרְמִימוּת שֶׁל כָּל דָּבָר (סוטה כא:):",1,0],[8,13,"יִרְאַת ה׳ שְׂנֹאת רָע. זֶהוּ הַמּוּסָר שֶׁהַחָכְמָה מַכְרֶזֶת לַבְּרִיּוֹת:",1,0],[8,15,"בִּי מְלָכִים יִמְלֹכוּ. שֶׁהַדִּינִים וְהַמִּשְׁפָּטִים אֲנִי מְלַמְּדָם:",1,0],[8,17,"אֵהַב. כְּמוֹ אֶאֱהַב:",1,0],[8,17,"אֹהֲבַי. אֹהֲבֶיהָ כְּתִיב, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֲנִי אֹהֲבֶיהָ שֶׁל תּוֹרָה אֵהָב. זוֹ שָׁמַעְתִּי מֵרַבִּי אַהֲרֹן, בְּשֵׁם רַבִּי נָתָן:",2,0],[8,17,"יִמְצָאֻנְנִי. נוּ״ן יְתֵרָה: חֲמִשִּׁים שַׁעֲרֵי בִינָה אַמְצִיאֶנּוּ:",3,0],[8,21,"לְהַנְחִיל אוֹהֲבַי יֵשׁ. יֵשׁ אִתִּי נַחֲלָה רַבָּה:",1,0],[8,22,"רֵאשִׁית דַּרְכּוֹ. קוֹדֶם בְּרִיאָתוֹ שֶׁל עוֹלָם (פסחים נד.):",1,0],[8,23,"נִסַּכְתִּי מֵרֹאשׁ. לְשׁוֹן נְסִיכֵי בְּנֵי אָדָם (מיכה ה:ד):",1,0],[8,24,"חוֹלָלְתִּי. נִבְרֵאתִי:",1,0],[8,25,"בְּטֶרֶם הָרִים הָטְבָּעוּ. בְּתוֹךְ הַמָּיִם:",1,0],[8,26,"אֶרֶץ וְחוּצוֹת. אֶרֶץ יִשְׂרָאֵל וּשְׁאָר אֲרָצוֹת (תענית י.):",1,0],[8,26,"וְרֹאשׁ עַפְרוֹת תֵּבֵל. אָדָם הָרִאשׁוֹן (סנהדרין לח.):",2,0],[8,27,"בְּחֻקּוֹ חוּג עַל פְּנֵי תְהוֹם. כְּשֶׁרָקַע חוּג הָאָרֶץ עַל הַמַּיִם, חֹק גְּבוּל בַּל יַעֲבֹר:",1,0],[8,27,"חוּג. לְשׁוֹן הֶקֵּף, כְּמוֹ ״וּבַמְּחוּגָה יְתָאֲרֵהוּ״ (ישעיה מד:יג). קוֹנְפָּא״שׁ בְּלַעַ״ז:",2,0],[8,28,"בַּעֲזוֹז. כְּשֶׁהִגְבִּיר מַעְיְנוֹת תְּהוֹם:",1,0],[8,29,"בְּשׂוּמוֹ לַיָּם חֻקּוֹ. וְגָזַר עַל יַם סוּף כְּשֶׁבְּרָאוֹ, עַל מְנָת לְהִבָּקַע לִפְנֵי מֹשֶׁה (שמות יד:כא):",1,0],[8,29,"בְּחֻקּוֹ מוֹסְדֵי אָרֶץ. בְּחִקָּתוֹ, מִלְּשׁוֹן חֻקּוֹ; כְּמוֹ ״עַל כַּפַּיִם חַקֹּתִיךְ״ (ישעיה מט:טז); וְכֵן ״וּמֵחֵיק הָאָרֶץ״ (יחזקאל מג:יד):",2,0],[8,30,"אָמוֹן. גְּדֵלָה אֶצְלוֹ, לְשׁוֹן ״הָאֲמוּנִים עֲלֵי תוֹלָע״ (איכה ד:ה):",1,0],[8,30,"יוֹם יוֹם. אַלְפַּיִם שָׁנָה (תהלים צ:ד; ויקרא רבה יט:א):",2,0],[8,31,"מְשַׂחֶקֶת בְּתֵבֵל אַרְצוֹ. כָּל דּוֹרוֹת הָרְשָׁעִים שֶׁהָיוּ מֵאָדָם וְעַד נֹחַ וּמִנֹּחַ וְעַד אַבְרָהָם הָיִיתִי מְשַׂחֶקֶת עֲלֵיהֶם:",1,0],[8,31,"וְשַׁעֲשֻׁעַי. צָפִיתִי עַד בֹּא דּוֹר הַמִּדְבָּר וִיקַבְּלוּנִי:",2,0],[8,32,"וְעַתָּה בָנִים שִׁמְעוּ לִי:",1,0],[8,33,"וְאַל תִּפְרָעוּ. וְאַל תְּבַטְּלוּ מוּסָרִי:",1,0],[8,34,"לִשְׁקֹד. לִשְׁמֹר:",1,0],[8,34,"עַל דַּלְתוֹתַי. לְהִכָּנֵס רִאשׁוֹן לְבֵית הַמִּדְרָשׁ וּלְבֵית הַכְּנֶסֶת וְלָצֵאת אַחֲרוֹן:",2,0],[9,1,"חָכְמוֹת בָּנְתָה בֵיתָהּ. בְּחָכְמָה בָּנָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם:",1,0],[9,1,"חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. שִׁבְעַת יְמֵי בְרֵאשִׁית. דָּבָר אַחֵר: שִׁבְעָה סְפָרִים שֶׁיֵּשׁ בַּתּוֹרָה – ״וַיְהִי בִּנְסֹעַ הָאָרֹן״ (במדבר י:לה) סֵפֶר לְעַצְמוֹ; בְּמַסֶּכֶת שַׁבָּת (שבת קטז.):",2,0],[9,2,"טָבְחָה טִבְחָהּ מָסְכָה יֵינָהּ. מְזָגָם בְּמַיִם, כְּמוֹ יַיִן חָזָק שֶׁאֵינוֹ רָאוּי לִשְׁתּוֹת חַי:",1,0],[9,2,"אַף עָרְכָה שֻׁלְחָנָהּ. כָּל יְצִירַת לַח וְיָבֵשׁ:",2,0],[9,3,"שָׁלְחָה נַעֲרוֹתֶיהָ. אָדָם וְחַוָּה (סנהדרין לח.), דָּבָר אַחֵר: מֹשֶׁה וְאַהֲרֹן (ויקרא רבה א,ד):",1,0],[9,4,"מִי פֶתִי יָסוּר הֵנָּה. וְיִלְמַד אוֹתִי וְיֶחְכַּם:",1,0],[9,5,"לְכוּ לַחֲמוּ בְלַחֲמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. בְּיַיִן שֶׁמָּזַגְתִּי:",1,0],[9,6,"עִזְבוּ פְתָאיִם וִחְיוּ. אֶת דֶּרֶךְ הַפַּתְיוּת:",1,0],[9,6,"וְאִשְׁרוּ. לְשׁוֹן פַּעַם, כְּמוֹ ״בַּאֲשֻׁרוֹ אָחֲזָה רַגְלִי״ (איוב כג:יא):",2,0],[9,7,"וּמוֹכִיחַ לְרָשָׁע מוּמוֹ. מוּם הוּא לַמּוֹכִיחַ, שֶׁזֶּה מְחָרְפוֹ וְאֵינוֹ שׁוֹמֵעַ לוֹ. זוֹ הִיא אַזְהָרָה שֶׁאָסוּר לְדַבֵּר עִם הַמְּסִיתִים מִדֶּרֶךְ הַיְשָׁרָה, אֲפִלּוּ לְהוֹכִיחָם וּלְקָרְבָם:",1,0],[9,9,"תֵּן לְחָכָם וְיֶחְכַּם עוֹד. לְתַלְמִיד הָגוּן שְׁנֵה. וּמִדְרַשׁ אַגָּדָה (שמות רבה נ:ב): נֶאֱמַר לְנֹחַ ״מִכָּל הַבְּהֵמָה הַטְּהוֹרָה וְגוֹ׳״ (בראשית ז:ב), וּכְשֶׁיָּצָא ״וַיִּקַּח מִכָּל הַבְּהֵמָה וְגוֹ׳״ (בראשית ח:כ). אָמַר: מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַרְבּוֹת בְּאֵלּוּ? אֶלָּא שֶׁרָצָה שֶׁאַקְרִיב לוֹ מֵהֶן:",1,0],[9,9,"הוֹדַע לְצַדִּיק. חָכְמָה וְהוּא יוֹסֶף לֶקַח. מִדַּעְתּוֹ וְעַל שְׁמוּעָתוֹ:",2,0],[9,10,"תְּחִלַּת חָכְמָה יִרְאַת ה׳, וְדַעַת קְדוֹשִׁים. הִיא עִקַּר הַבִּינָה:",1,0],[9,11,"וְיוֹסִיפוּ לְךָ שְׁנוֹת חַיִּים. שָׁנִים שֶׁל חַיִּים הֵם שֶׁל פַּרְנָסָה וְעֹשֶׁר:",1,0],[9,16,"חֲסַר לֵב, וְאָמְרָה לּוֹ. הַדְּבָרִים הַלָּלוּ, מָה אָמְרָה לוֹ:",1,0],[9,17,"מַיִם גְּנוּבִים יִמְתָּקוּ. אֵין טַעַם בִּיאַת פְּנוּיָה כְּטַעַם אֵשֶׁת אִישׁ. אַף לְעִנְיַן הַמִּצְוָה, מַיִם גְּנוּבִים יִמְתָּקוּ. שֶׁהָיוּ יְרֵאִים לַעֲשׂוֹת בְּגָלוּי וְעוֹשִׂין בְּסֵתֶר:",1,0],[10,1,"מִשְׁלֵי שְׁלֹמֹה בֵּן חָכָם יְשַׂמַּח אָב. זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא (מדרש משלי י:א). דָּבָר אַחֵר: אָבִיו מַמָּשׁ:",1,0],[10,1,"וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תָּמִיד הוּא עִם אִמּוֹ בַּבַּיִת, וְרוֹאָה אֶת שְׁטוּתוֹ וּמְצֵרָה. וּלְפִי הַמָּשָׁל: בֵּן כְּסִיל כְּמוֹ יָרָבְעָם בֶּן נְבָט (ברכות לה:):",2,0],[10,1,"תּוּגַת אִמּוֹ. תּוּגַת כְּנִסִיּוֹתוֹ:",3,0],[10,2,"לֹא יוֹעִילוּ אוֹצְרוֹת רֶשַׁע. שֶׁהָיָה מִשְׁתַּבֵּחַ בְּעָשְׁרוֹ, שֶׁנֶּאֱמַר: ״וַיֹּאמֶר אֶפְרַיִם אַךְ עָשַׁרְתִּי וְגוֹמֵר״ (הושע יב:ט):",1,0],[10,2,"וּצְדָקָה תַּצִּיל מִמָּוֶת. וְאִם תֹּאמַר: צַדִּיק שֶׁיְּבַזְבֵּז נְכָסָיו לִצְדָקָה, מֵהֵיכָן יִתְפַּרְנֵס?",2,0],[10,3,"לֹא יַרְעִיב ה׳ נֶפֶשׁ צַדִּיק, וְהַוַּת רְשָׁעִים יֶהְדֹּף. יִדְחוֹף אוֹתָם וְתִפּוֹל:",1,0],[10,4,"רָאשׁ עֹשֶׂה כַף רְמִיָּה. מִי שֶׁעָנִי בַּתּוֹרָה, מוֹרֶה הוֹרָאוֹת שֶׁקֶר:",1,0],[10,4,"כַּף רְמִיָּה. מֹאזְנַיִם שֶׁל רְמִיָּה. לְפִי פְּשׁוּטוֹ מַשְׁמַע בַּתַּגָּרִים:",2,0],[10,4,"וְיַד חָרוּצִים. יְשָׁרִים, שֶׁחוֹרְצִים דָּבָר בַּאֲמִתּוֹ וּמִשְׁפָּטוֹ בְּלֹא עַוְלָה:",3,0],[10,6,"וּפִי רְשָׁעִים יְכַסֶּה חָמָס. הֶחָמָס יְכַסֶּה עַל פִּיהֶם וְיַהַרְגֵם:",1,0],[10,7,"זֵכֶר צַדִּיק לִבְרָכָה. הַמַּזְכִּיר צַדִּיק מְבָרְכוֹ:",1,0],[10,7,"וְשֵׁם רְשָׁעִים יִרְקָב. רִקָּבוֹן עוֹלֶה בִּשְׁמָם, שֶׁאֵין אָדָם חָפֵץ לְהַזְכִּיר שְׁמוֹ וְהוּא מִשְׁתַּכֵּחַ מֵאֵלָיו (יומא לח:):",2,0],[10,8,"חֲכַם לֵב יִקַּח מִצְוֺת. מֹשֶׁה רַבֵּינוּ, שֶׁכָּל יִשְׂרָאֵל הָיוּ עוֹסְקִין בְּבִזַּת מִצְרַיִם, וְהוּא הָיָה עוֹסֵק בְּמִצְוֹת, שֶׁנֶּאֱמַר ״וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף וְגוֹ׳״ (שמות יג:יט):",1,0],[10,8,"וֶאֱוִיל שְׂפָתַיִם יִלָּבֵט. לְשׁוֹן יְגִיעָה. וְיֵשׁ בְּסִפְרֵי בְּפָרָשָׁה ״וַיְהִי הָעָם כְּמִתְאֹנְנִים״ (במדבר יא:א): אָמְרוּ: כַּמָּה נִתְלַבַּטְנוּ בַדֶּרֶךְ:",2,0],[10,9,"וּמְעַקֵּשׁ דְּרָכָיו יִוָּדֵעַ. יִשָּׁבֵר וְיִתְיַסֵּר, כְּמוֹ ״וַיֹּדַע בָּהֶם אֶת אַנְשֵׁי סֻכּוֹת״ (שופטים ח:טז):",1,0],[10,10,"קוֹרֵץ עַיִן יִתֵּן עַצָּבֶת. זֶה הַמֵּסִית אָדָם בִּקְרִיצוֹתָיו לְרָעָה:",1,0],[10,11,"מְקוֹר חַיִּים פִּי צַדִּיק וּפִי רְשָׁעִים וְגוֹ׳. פִּיהֶם יְכַסֶּה חָמָס שֶׁבְּלִבָּם, שֶׁמַּחֲלִיקִין אֶת שִׂפְתֵיהֶם וְשִׂנְאָה טְמוּנָה בְּלִבָּם. וְאֵין פִּתְרוֹן מִקְרָא זֶה דּוֹמֶה לְפִתְרוֹן הָעֶלְיוֹן (משלי י:ו), וְהָעִנְיָן יוֹרֶה עֲלֵיהֶם:",1,0],[10,12,"שִׂנְאָה תְּעוֹרֵר מְדָנִים. אֲפִלּוּ עֲבֵרָה שֶׁנִּתְּנָה לְשִׁכְחָה נִזְכֶּרֶת עַל יְדֵי מַרְבִּית עֲוֹנוֹת; בָּאָה שִׂנְאָה אַחֲרוֹנָה וּמְעוֹרֶרְתָּן. שֶׁכֵּן יְחֶזְקֵאל הוֹכִיחַ אֶת יִשְׂרָאֵל עַל עֲבֵרוֹת מִצְרַיִם: ״וָאֹמַר אֲלֵהֶם אִישׁ אֶת שִׁקּוּצֵי עֵינָיו הַשְׁלִיכוּ וְגוֹ׳״ (יחזקאל כ:ז) – כַּמָּה שָׁנִים הָיְתָה שִׂנְאָה זוֹ כְּבוּשָׁה וְלֹא הִזְכִּירָהּ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד עַכְשָׁו, שֶׁהִרְבּוּ עֲבֵרוֹת עַל פִּשְׁעֵיהֶם (ויקרא רבה ז:א):",1,0],[10,12,"וְעַל כָּל פְּשָׁעִים תְּכַסֶּה אַהֲבָה. כְּשֶׁיִּשְׂרָאֵל מֵטִיבִים מַעֲשֵׂיהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַסֶּה עַל פְּשָׁעֵיהֶם:",2,0],[10,13,"בְּשִׂפְתֵי נָבוֹן תִּמָּצֵא חָכְמָה. כְּשֶׁאָדָם מוֹכִיחַ לְנָבוֹן, מֵשִׁיב לוֹ: חָטָאתִי! כְּגוֹן דָּוִד שֶׁאָמַר לְנָתָן: ״חָטָאתִי״ (שמואל ב יב:יג):",1,0],[10,13,"וְשֵׁבֶט לְגֵו חֲסַר לֵב. אֲבָל חֲסַר לֵב אֵינוֹ שׁוֹמֵעַ עַד שֶׁיִּלְקֶה, כְּמוֹ פַּרְעֹה (שמות ז:יד-יא:י):",2,0],[10,14,"חֲכָמִים יִצְפְּנוּ דָעַת. יִשְׁמְרוּהוּ בְּלִבָּם, שֶׁלֹּא יִשְׁכָּחוּהוּ:",1,0],[10,15,"הוֹן עָשִׁיר. בַּתּוֹרָה:",1,0],[10,15,"קִרְיַת עֻזּוֹ. הִיא לוֹ:",2,0],[10,15,"מְחִתַּת דַּלִּים רֵישָׁם. עֲנִיּוּתָם, שֶׁלֹּא עָסְקוּ בַּתּוֹרָה, הִיא מְחִתָּתָם:",3,0],[10,16,"פְּעֻלַּת צַדִּיק לְחַיִּים. כְּמַשְׁמָעוֹ. וּמִדְרַשׁ אַגָּדָה (דברים רבה ב:כ): שְׁלֹמֹה עָשָׂה פְּעֻלַּת הַמִּקְדָּשׁ לְחַיֵּיהֶם שֶׁל יִשְׂרָאֵל, לְכַפָּרָתָן:",1,0],[10,16,"וּתְּבוּאַת רָשָׁע. תְּבוּאָתוֹ (  הֲבָאָתוֹ) שֶׁל מְנַשֶּׁה (דברי הימים ב לג:ז), שֶׁהִכְנִיס בּוֹ הַסֶּמֶל, הִיא הָיְתָה לְחַטָּאת:",2,0],[10,17,"אֹרַח לְחַיִּים. הַשּׁוֹמֵר מוּסָר הִיא הַדֶּרֶךְ לְחַיִּים:",1,0],[10,17,"וְעוֹזֵב תּוֹכַחַת מַתְעֶה. אֶת עַצְמוֹ וְאֶת אֲחֵרִים:",2,0],[10,18,"מְכַסֶּה שִׂנְאָה שִׂפְתֵי שָׁקֶר. הֶחָנֵף שְׂפָתָיו שֶׁקֶר, וּמְכַסֶּה שִׂנְאָה בְּלִבּוֹ:",1,0],[10,18,"וּמוֹצִיא דִבָּה הוּא כְסִיל. לַעַז, שֶׁיִּהְיוּ אֲנָשִׁים דּוֹבְבִין בּוֹ עַל חֲבֵירוֹ:",2,0],[10,19,"בְּרֹב דְּבָרִים לֹא יֶחְדַּל פָּשַׁע. הַמַּרְבֶּה דְבָרִים מֵבִיא חֵטְא:",1,0],[10,19,"וְחוֹשֵׂךְ שְׂפָתָיו. הוּא הַמַּשְׂכִּיל:",2,0],[10,20,"כֶּסֶף נִבְחָר לְשׁוֹן צַדִּיק. שֶׁיּוֹדֵעַ לְהוֹכִיחַ:",1,0],[10,20,"לֵב רְשָׁעִים כִּמְעָט. שֶׁאֵינוֹ שׁוֹמֵעַ לְתוֹכַחַת צַדִּיק. וּמִדְרַשׁ רַבִּי תַּנְחוּמָא אוֹמֵר (תנחומא, כי תשא ו): עַל עִדּוֹ הַנָּבִיא נֶאֱמַר, שֶׁקָּרָא עַל הַמִּזְבֵּחַ בְּבֵית אֵל; וְיָרָבְעָם, אַף עַל פִּי שֶׁיָּבְשָׁה יָדוֹ, לֹא קִבֵּל תּוֹכֵחָה, שֶׁנֶּאֱמַר ״חַל נָא אֶת פְּנֵי ה׳ אֱלֹהֶיךָ וְגוֹ׳״ (מלכים א יג:ו) וְלֹא ׳אֱלֹהַי׳; וְאוֹמֵר ״וַתָּשָׁב יָדוֹ כְּבָרִאשֹׁנָה״ (מלכים א יג:ו) – עוֹמֵד וּמַקְטִיר לַעֲבוֹדַת גִּלּוּלִים, וְאַף בַּסּוֹף כֵּן:",2,0],[10,21,"שִׂפְתֵי צַדִּיק יִרְעוּ רַבִּים וְגוֹ׳. שֶׁרַבִּים אוֹכְלִים בִּזְכוּתוֹ וּבִתְפִלָּתוֹ:",1,0],[10,22,"בִּרְכַּת ה׳ הִיא תַעֲשִׁיר, וְלֹא יוֹסִיף עֶצֶב עִמָּהּ. אֵין צָרִיךְ לְהִתְיַגֵּעַ לְהַעֲשִׁיר בּוֹ, דַּי בַּבְּרָכָה מַה שֶּׁהוּא מְבָרְכוֹ:",1,0],[10,23,"כְּשְׂחוֹק לִכְסִיל עֲשׂוֹת זִמָּה. עֲצַת חַטָּאִים:",1,0],[10,23,"וְחָכְמָה כִּשְׂחוֹק לְאִישׁ תְּבוּנָה. כְּלוֹמַר: קַלָּה הִיא בְּעֵינָיו לַעֲשׂוֹת:",2,0],[10,24,"מְגוֹרַת רָשָׁע. מַה שֶּׁהוּא יָרֵא יָבֹא לוֹ. דּוֹר הַפְּלַגָּה יָרְאוּ וְאָמְרוּ ״פֶּן נָפוּץ״ (בראשית יא:ד), וְסוֹפָן כְּתִיב ״וַיָּפֶץ ה׳ אֹתָם מִשָּׁם״ (בראשית יא:ח):",1,0],[10,24,"וְתַאֲוַת צַדִּיקִים יִתֵּן. מִי שֶׁבְּיָדוֹ לִתְּנָהּ (לָתֵת):",2,0],[10,25,"כַּעֲבוֹר סוּפָה וְאֵין רָשָׁע. פִּתְאוֹם בָּא עֶבְרַת רוּחַ סְעָרָה, נִכְרַת הָרָשָׁע מִמְּקוֹמוֹ:",1,0],[10,28,"תּוֹחֶלֶת צַדִּיקִים שִׂמְחָה. סוֹפָהּ מִתְקַיֶּמֶת וּשְׂמֵחִים:",1,0],[10,28,"וְתִקְוַת רְשָׁעִים תֹּאבֵד. כִּי לֹא תָבֹא:",2,0],[10,29,"מָעוֹז לַתֹּם דֶּרֶךְ ה׳ וּמְחִתָּה. הִיא לְפוֹעֲלֵי אָוֶן שֶׁאֵינָן הוֹלְכִין בָּהּ, וְהִיא נִפְרַעַת מֵהֶם:",1,0],[10,30,"צַדִּיק לְעוֹלָם בַּל יִמּוֹט. כְּשֶׁהוּא מָט אֵין מוֹטָתוֹ מוֹטַת עוֹלָם, כִּי יִפּוֹל וְקָם (משלי כד:טז):",1,0],[10,31,"פִּי צַדִּיק יָנוּב חָכְמָה. יְדַבֵּר, לְשׁוֹן ״נִיב שְׂפָתָיִם״ (ישעיהו נז:יט):",1,0],[10,32,"שִׂפְתֵי צַדִּיק יֵדְעוּן רָצוֹן. יוֹדְעִים לְרַצּוֹת וּלְפַיֵּס אֶת בּוֹרְאָם, וְיוֹדְעִים לְרַצּוֹת אֶת הַבְּרִיּוֹת וּלְהַטִּיל שָׁלוֹם בֵּינֵיהֶם:",1,0],[11,2,"בָּא זָדוֹן וַיָּבֹא קָלוֹן וְאֶת צְנוּעִים חָכְמָה. תָּבוֹא חָכְמָה:",1,0],[11,3,"תֻּמַּת יְשָׁרִים תַּנְחֵם. תַּנְהֲלֵם:",1,0],[11,3,"וְסֶלֶף בּוֹגְדִים יְשָׁדֵּם. יְשָׁדְדֵם:",2,0],[11,6,"צִדְקַת יְשָׁרִים תַּצִּילֵם וּבְהַוַּת בֹּגְדִים יִלָּכֵדוּ. בַּהַוּוֹת שֶׁהֵם עוֹשִׂים הֵם נִלְכָּדִים. וְהַמִּקְרָא מְסֹרָס הוּא, כְּלוֹמַר: וּבוֹגְדִים בְּהַוַּת יִלָּכֵדוּ:",1,0],[11,7,"בְּמוֹת אָדָם רָשָׁע תֹּאבַד תִּקְוָה. תִּקְוַת כָּל הַבּוֹטְחִים בּוֹ:",1,0],[11,7,"וְתוֹחֶלֶת אוֹנִים אָבָדָה. תּוֹחֶלֶת בָּנָיו, שֶׁהֵם אוֹנוֹ, אָבְדָה, כִּי בִּזְכוּתוֹ לֹא תָבוֹא לָהֶם טוֹבָה. אֲבָל בְּמוֹת צַדִּיקִים יֵשׁ לִבְנֵיהֶם מִבְטָח בְּצִדְקָתָם:",2,0],[11,8,"צַדִּיק מִצָּרָה נֶחֱלָץ. בְּמוֹת רָשָׁע, וְלַמִּקְרָא הָעֶלְיוֹן (משלי יא:ז) זֶה מְחֻבָּר:",1,0],[11,9,"בְּפֶה חָנֵף. חָנֵף הַמֵּסִית חֲבֵרוֹ בְּדֶרֶךְ רַע, מַשְׁחִיתוֹ בְּפִיו:",1,0],[11,9,"וּבְדַעַת צַדִּיקִים יֵחָלֵצוּ. וְהַצַּדִּיק נֶחֱלָץ מִמֶּנּוּ בְּדַעַת הַתּוֹרָה, שֶׁהִזְהִירָה עָלָיו ״לֹא תֹאבֶה לוֹ וְגוֹ׳״ (דברים יג:ט):",2,0],[11,11,"תָּרוּם קָרֶת. תִּתְקַיֵּם תִּקְרַת הַבַּיִת בְּגָבְהָהּ מִלִּפּוֹל. בְּעוֹד שֶׁהָיוּ מַלְכֵי יְהוּדָה יְשָׁרִים, הֶעֱמִידָה תְּפִלָּתָם אֶת בֵּית הַמִּקְדָּשׁ:",1,0],[11,12,"וְאִישׁ תְּבוּנוֹת יַחֲרִישׁ. כְּשֶׁמְּבַזֵּהוּ הֶחָסֵר לֵב; כְּמוֹ שָׁאוּל, דִּכְתִיב ״וַיִּבְזֻהוּ וְלֹא הֵבִיאוּ לוֹ מִנְחָה וַיְהִי כְּמַחֲרִישׁ״ (שמואל א י:כז):",1,0],[11,14,"בְּאֵין תַּחְבֻּלוֹת. כְּשֶׁהַצָּרָה בָּאָה עַל יִשְׂרָאֵל, וְאֵינָן נוֹתְנִין לֵב לְהָבִין לְהִתְעַנּוֹת וְלַעֲשׂוֹת תְּשׁוּבָה, יִפָּל עָם:",1,0],[11,15,"רַע יֵרוֹעַ. הָרָשָׁע יִתְרוֹצֵץ, אֲשֶׁר עָרַב לִבּוֹ לַעֲבוֹדַת גִּלּוּלִים:",1,0],[11,15,"וְשׂוֹנֵא תוֹקְעִים. תּוֹקְעִים כַּף לַעֲשׂוֹת רַע וְלָלֶכֶת בַּעֲצָתָם, וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ (יבמות קט:) בְּעַרְבוּת מָמוֹן:",2,0],[11,16,"תִּתְמֹךְ כָּבוֹד. כְּנֶסֶת יִשְׂרָאֵל תְּקָרֵב תָּמִיד לִכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא וְתוֹרָתוֹ:",1,0],[11,16,"וְעָרִיצִים יִתְמְכוּ עֹשֶׁר. בְּנֵי אֱדוֹם מִתְקָרְבִים אֵצֶל גְּנֵיבוֹת מָמוֹן וְגָזֵל:",2,0],[11,17,"גּוֹמֵל נַפְשׁוֹ. גּוֹמֵל טוֹבָה לִקְרוֹבָיו. אִישׁ חָסֶד אִישׁ שֶׁהוּא חָסִיד:",1,0],[11,17,"וְעֹכֵר שְׁאֵרוֹ אַכְזָרִי. וְהָאַכְזָרִי הוּא עוֹכֵר אֶת קְרוֹבָיו:",2,0],[11,18,"רָשָׁע עֹשֶׂה פְעֻלַּת שָׁקֶר. פְּעֻלָּתוֹ שֶׁל רָשָׁע מְשַׁקֶּרֶת לוֹ, כְּסָבוּר שֶׁתִּתְקַיֵּם בּוֹ הַצְלָחָתוֹ, וְהַכֹּל אָבַד:",1,0],[11,18,"וְזוֹרֵעַ צְדָקָה שֶׂכֶר אֱמֶת. וְהַזּוֹרֵעַ צְדָקָה הִיא פְּעֻלָּה שֶׁל אֱמֶת, כִּי בְּוַדַּאי בָּטוּחַ הוּא שֶׁיְּקַבֵּל פָּעֳלוֹ בַּסּוֹף:",2,0],[11,18,"שֶׂכֶר. קְרוֹנִיאָ״ל בְּלַעַ״ז, כְּאָדָם הַסּוֹכֵר אַמַּת הַמַּיִם כְּדֵי לִלְקוֹט דָּגִים, וּבָטוּחַ שֶׁיִּמְצָא שָׁם דָּגִים הַרְבֵּה. וְדוֹמֶה לוֹ ״כָּל עֹשֵׂי שֶׂכֶר אַגְמֵי נָפֶשׁ״ (ישעיהו יט:י):",3,0],[11,19,"כֵּן צְדָקָה לְחַיִּים. אֲמִתּוֹ שֶׁל צְדָקָה סוֹפָהּ לְחַיִּים, כְּמוֹ ״כֵּן בְּנוֹת צְלָפְחָד דֹּבְרוֹת״ (במדבר כז:ז):",1,0],[11,21,"יָד לְיָד. כְּלוֹמַר: מִיַּד הַקָּדוֹשׁ בָּרוּךְ הוּא לְיָדוֹ תָּבוֹא לוֹ שְׂכַר פְּעֻלָּתוֹ, וְלֹא יִנָּקֶה מִן הָרָעָה אֲשֶׁר עָשָׂה (סוטה ד:):",1,0],[11,22,"נֶזֶם זָהָב בְּאַף חֲזִיר. שֶׁמְּלַכְלֵךְ אוֹתָהּ בָּאַשְׁפּוֹת, כֵּן תַּלְמִיד חָכָם הַסָּר מִן הַדֶּרֶךְ הַטּוֹבָה:",1,0],[11,22,"וְסָרַת טָעַם. פּוֹרֵשׁ מִן הַתּוֹרָה:",2,0],[11,23,"תִּקְוַת רְשָׁעִים עֶבְרָה. בְּטוּחִים וּמְקַוִּים לְגֵיהִנֹּם:",1,0],[11,24,"יֵשׁ מְפַזֵּר. מְמוֹנוֹ, כְּגוֹן לִצְדָקָה, וְנוֹסָף עוֹד:",1,0],[11,24,"וְחוֹשֵׂךְ. עַצְמוֹ מִיֹּשֶׁר, אַךְ לְמַחְסוֹר יִהְיֶה לוֹ:",2,0],[11,25,"נֶפֶשׁ בְּרָכָה. שֶׁהוּא וַתְרָן בְּמָמוֹנוֹ. וְכָל לְשׁוֹן בְּרָכָה – פִּישׁוֹן בְּלַעַ״ז:",1,0],[11,25,"וּמַרְוֶה. שֶׁמַּשְׂבִּיעַ אֶת הָעֲנִיִּים:",2,0],[11,25,"גַּם הוּא יוֹרֶא. יִשְׂבַּע טוֹב:",3,0],[11,26,"מוֹנֵעַ בָּר. מְלַמֵּד תּוֹרָה:",1,0],[11,27,"שׁוֹחֵר טוֹב. הֶחָפֵץ לְהַדְרִיךְ אֶת הַבְּרִיּוֹת בְּדֶרֶךְ טוֹבָה, וּמוֹכִיחַ וּמְיַסֵּר אוֹתָם:",1,0],[11,27,"יְבַקֵּשׁ רָצוֹן. הוּא חָפֵץ שֶׁיִּהְיֶה הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָּם, וּמִתְפַּיֵּס עִמָּם. רָצוֹן, אפיימינ״ט בְּלַעַ״ז:",2,0],[11,29,"עוֹכֵר בֵּיתוֹ יִנְחַל רוּחַ. אָדָם עָצֵל שֶׁיִּנְחַל רוּחַ תָּמִיד, וְאֵינוֹ יָגֵעַ בַּתּוֹרָה וְלֹא בִמְלָאכָה, סוֹף עוֹכֵר אֶת בְּנֵי בֵיתוֹ, שֶׁאֵין לָהֶם מַה לֶּאֱכֹל:",1,0],[11,30,"פְּרִי צַדִּיק. גְּמוּל פֵּירוֹת מַעֲשֵׂה הַצַּדִּיקִים עֵץ חַיִּים הֵם לָעוֹלָם:",1,0],[11,30,"וְלֹקֵחַ נְפָשׁוֹת חָכָם. מִי שֶׁהוּא חָכָם, קוֹנֶה לוֹ נְפָשׁוֹת. שֶׁמְּלַמְּדָם דֶּרֶךְ טוֹב, וַהֲרֵי הֵם לוֹ כְּאִלּוּ קְנָאָם, כְּעִנְיָן שֶׁנֶּאֱמַר ״וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן״ (בראשית יב:ה):",2,0],[11,31,"הֵן צַדִּיק בָּאָרֶץ יְשֻׁלָּם. לָמָּה יִבְטַח הָרָשָׁע בְּשָׁעָה שֶׁמַּצְלַחַת לוֹ? הֲלֹא הוּא רוֹאֶה שֶׁהַצַּדִּיק מִשְׁתַּלֵּם שְׂכַר הָעֲבֵירָה שֶׁבְּיָדוֹ בְּעוֹדוֹ עַל הָאָרֶץ בַּחַיִּים:",1,0],[11,31,"וְאַף כִּי רָשָׁע וְחוֹטֵא. וְכָל שֶׁכֵּן שֶׁסּוֹפוֹ שֶׁל רָשָׁע לְהִשְׁתַּלֵּם לוֹ, אוֹ בְּחַיָּיו אוֹ בְּמוֹתוֹ:",2,0],[12,2,"טוֹב יָפִיק. מוֹצִיא מִן הַקָּדוֹשׁ בָּרוּךְ הוּא נַחַת רוּחַ, לְהָבִיא טוֹבָה לָעוֹלָם:",1,0],[12,2,"וְאִישׁ מְזִמּוֹת יַרְשִׁיעַ. בַּעַל עֲלִילוֹת יַרְשִׁיעַ – מְחַיֵּב אֶת הַבְּרִיּוֹת לְהָבִיא רָעָה, וְכֵן הוּא אוֹמֵר ״וְחוֹטֵא אֶחָד יְאַבֵּד טוֹבָה הַרְבֵּה״ (קהלת ט:יח):",2,0],[12,3,"לֹא יִכּוֹן אָדָם בְּרֶשַׁע. לֹא יִתְבַּסֵּס:",1,0],[12,4,"וּכְרָקָב. תּוֹלַעַת הַנִּכְנָס תּוֹךְ הָעֲצָמוֹת וְטוֹחֵן אוֹתָם, כֵּן אִשָּׁה מְבִישָׁה וְרָעָה, שֶׁמַּעֲשֶׂיהָ בּוֹשִׁים:",1,0],[12,6,"דִּבְרֵי רְשָׁעִים אֱרָב דָּם. יוֹעֲצִים לִרְצוֹחַ בְּיָדָם אוֹ עַל יְדֵי עֵדוּת שֶׁקֶר:",1,0],[12,6,"וּפִי יְשָׁרִים. כְּשֶׁשּׁוֹמְעִים אֶת עֲצָתָם, יַצִּילוּם לַנִּרְדָּפִים, שֶׁמְּגַלִּים אֶת עֲצָתָם; אוֹ אִם עֵדִים הֵם, מְזִמִּין אוֹתָם:",2,0],[12,7,"הָפוֹךְ רְשָׁעִים. כְּמוֹ ״לַהֲפֹךְ״, כְּמַהְפֵּכַת רֶגַע (איכה ד:ו) נֶהְפָּכִים:",1,0],[12,7,"וְאֵינָם. כָּלִים, כְּגוֹן סְדוֹם (בראשית יט:כד-כה):",2,0],[12,7,"וּבֵית צַדִּיקִים יַעֲמֹד. יִתְקַיֵּם:",3,0],[12,8,"לְפִי שִׂכְלוֹ יְהֻלַּל אִישׁ. אִם חָכָם מְעַט אוֹ הַרְבֵּה, הַכֹּל לְפִי שִׂכְלוֹ יִטֹּל שְׂכָרוֹ:",1,0],[12,8,"וְנַעֲוֵה לֵב. שֶׁהֵנִיעַ לִבּוֹ לְגַמְרֵי מִן הַתּוֹרָה, הוּא יִהְיֶה לָבוּז:",2,0],[12,8,"נַעֲוֵה. כְּמוֹ ״נַעֲוֵיתִי מִשְּׁמֹעַ״ (ישעיה כא:ג), וְכֵן ״בֶּן נַעֲוַת הַמַּרְדּוּת״ (שמואל א כ:ל). וְיֵשׁ לוֹמַר נַעֲוֵה – מִי שֶׁלִּבּוֹ נָעוּעַ, מִגִּזְרַת ״נָע וָנָד״ (בראשית ד:יב). כַּאֲשֶׁר יֹאמַר ״זַעֲוָה״ (דברים כח:כה) מִגִּזְרַת ״זָע״ (אסתר ה:ט):",3,0],[12,9,"טוֹב נִקְלֶה. בְּעֵינָיו, וְנַעֲשָׂה עֶבֶד לְעַצְמוֹ:",1,0],[12,9,"מִמִּתְכַּבֵּד. בְּעֵינָיו, וְאוֹמֵר: גְּנַאי הוּא לִי לַעֲמֹל בִּמְלָאכָה, שֶׁאֲנִי מִבְּנֵי אָדָם גְּדוֹלִים; וְסוֹפוֹ לִהְיוֹת חֲסַר לָחֶם:",2,0],[12,10,"יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ. מַה בְּהֶמְתּוֹ וּבְנֵי בֵיתוֹ צְרִיכִים:",1,0],[12,11,"עוֹבֵד אַדְמָתוֹ יִשְׂבַּע לָחֶם. כְּמַשְׁמָעוֹ, וּלְפִי מְשָׁלוֹ: שֶׁחוֹזֵר עַל תַּלְמוּדוֹ תָּמִיד, שֶׁלֹּא יִשְׁתַּכַּח:",1,0],[12,12,"חָמַד רָשָׁע. לִהְיוֹת נִזּוֹן וּמִתְפַּרְנֵס מִמְּצוֹד רְשָׁעִים, שֶׁצָּדִין אֶת הַבְּרִיּוֹת בִּגְזֵלוֹת וְחָמָס:",1,0],[12,12,"וְשֹׁרֶשׁ צַדִּיקִים יִתֵּן. מַה שֶּׁהוּא רָאוּי לִיתֵּן, וְהוּא הַפְּרִי:",2,0],[12,13,"בְּפֶשַׁע שְׂפָתַיִם. בְּפֶשַׁע שִׂפְתֵי דּוֹר הַמַּבּוּל, שֶׁאָמְרוּ: ״מַה שַׁדַּי כִּי נַעַבְדֶנּוּ״ (איוב כא:טו), בָּא לָהֶם מוֹקֵשׁ רָע, וְנֹחַ הַצַּדִּיק יָצָא מֵהַצָּרָה (תנחומא, נח טז):",1,0],[12,14,"מִפְּרִי פִי אִישׁ. מִשְּׂכַר פִּיהֶם שֶׁל עוֹסְקֵי תוֹרָה, אוֹכְלִים טוֹב בָּעוֹלָם הַזֶּה, וְהַקֶּרֶן קַיֶּמֶת לָהֶם לָעוֹלָם הַבָּא:",1,0],[12,16,"אֱוִיל בַּיּוֹם יִוָּדַע כַּעְסוֹ. בְּיוֹם שֶׁהוּא כּוֹעֵס, בּוֹ בַּיּוֹם הוֹדִיעַ כַּעְסוֹ, שֶׁהוּא מִתְגָּרֶה וּמְחָרֵף חֲבֵירוֹ בָּרַבִּים, וְאֵין מַעְצָר לְרוּחוֹ. אֲבָל הֶעָרוּם כֹּסֶה קָלוֹן וְאֵינוֹ מְמַהֵר לָרִיב. וּמִדְרַשׁ אַגָּדָה: בְּיוֹם שֶׁנִּבְרָא אָדָם הָרִאשׁוֹן נוֹדַע סוּרְחָנוֹ (עבודה זרה ח.), וְהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא עָרוּם, לֹא רָצָה לְשַׁחֵת בְּרִיּוֹתָיו, כִּסָּה קְלוֹנוֹ (חגיגה יב.) וְדָחָה לִגְזֵרָתוֹ מִיּוֹם שֶׁל אָדָם לְיוֹם שֶׁלּוֹ, שֶׁהוּא אֶלֶף שָׁנָה (תהלים צ:ד; במדבר רבה יד:יב):",1,0],[12,17,"יָפִיחַ אֱמוּנָה יַגִּיד צֶדֶק. מִי שֶׁמְּדַבֵּר אֱמוּנָה מַגִּיד בְּדִין עֵדוּת צֶדֶק לְזַכּוֹת הַזַּכַּאי:",1,0],[12,18,"יֵשׁ בּוֹטֶה. מְדַבֵּר, כְּמוֹ ״לְבַטֵּא בִשְׂפָתַיִם״ (ויקרא ה:ד):",1,0],[12,18,"כְּמַדְקְרוֹת חָרֶב. שֶׁמְּסַכְסֵךְ אֶת הַבְּרִיּוֹת וְגוֹרֵם לָהֶם לַהֲרֹג:",2,0],[12,18,"וּלְשׁוֹן חֲכָמִים. הַמֵּבִיא שָׁלוֹם בֵּין אָדָם לַחֲבֵירוֹ:",3,0],[12,18,"מַרְפֵּא. לַמִּבְטָא הַהוּא:",4,0],[12,19,"שְׂפַת אֱמֶת תִּכּוֹן לָעַד. תִּתְבַּסֵּס וּתְקַיֵּם:",1,0],[12,19,"וְעַד אַרְגִּיעָה. לִמְעַט רֶגַע הוּא כָּלֶה וְהוֹלֵךְ, שֶׁהַשֶּׁקֶר אֵין לוֹ רַגְלַיִם:",2,0],[12,20,"מִרְמָה בְּלֶב חֹרְשֵׁי רָע. וּמִתּוֹךְ שֶׁהֵם טְרוּדִים בְּמַחֲשָׁבוֹת שֶׁל תַּרְמִית, אֵין לָהֶם שִׂמְחָה, וּלְיוֹעֲצֵי שָׁלוֹם שִׂמְחָה:",1,0],[12,21,"לֹא יְאֻנֶּה לַצַּדִּיק. לֹא יֶאֱרַע, לֹא תִזְדַּמֵּן לוֹ עֲבֵרָה בְּלִי דַעַת:",1,0],[12,23,"אָדָם עָרוּם כּוֹסֶה דָּעַת. אֲפִלּוּ בְּחָכְמָתוֹ הוּא צָנוּעַ, וְכָל שֶׁכֵּן לְדִבְרֵי שְׁטוּת הוּא מְכַסֶּה. אֲבָל וְלֵב כְּסִילִים יִקְרָא אִוֶּלֶת. מַכְרִיז אִוֶּלֶת בְּקוֹל רָם:",1,0],[12,24,"יַד חָרֻצִים. יְשָׁרִים:",1,0],[12,24,"תִּמְשׁוֹל. תַּעֲשִׁיר:",2,0],[12,25,"דְּאָגָה בְלֶב אִישׁ יַשְׁחֶנָּה. יְשִׂיחֶנָּה מִדַּעְתּוֹ:",1,0],[12,25,"וְדָבָר טוֹב יְשַׂמְּחֶנָּה. יַעֲסֹק בַּתּוֹרָה, וְהִיא תְּשַׂמַּח אֶת הַדְּאָגָה שֶׁבְּלִבּוֹ וְתַצִּילֶנּוּ מִמֶּנָּה. וּלְדִבְרֵי הָאוֹמֵר: יְשִׂיחֶנָּה לַאֲחֵרִים, כָּךְ סוֹפוֹ שֶׁל מִקְרָא: וְדָבָר טוֹב. שֶׁיְּנַחֲמֶנּוּ חֲבֵרוֹ, יְשַׂמַּח אֶת הַדְּאָגָה:",2,0],[12,26,"יָתֵר מֵרֵעֵהוּ צַדִּיק. הַצַּדִּיק מְוַתֵּר מִדּוֹתָיו וְעוֹבֵר עֲלֵיהֶם יָתֵר, לְרֵיי״שׁ בְּלַעַ״ז:",1,0],[12,26,"וְדֶרֶךְ רְשָׁעִים. שֶׁהִיא לְמוּדָה לְהָרַע, הִיא תַּתְעֵם:",2,0],[12,27,"לֹא יַחֲרֹךְ. מְחֻבָּר לַמִּקְרָא שֶׁלְּפָנָיו, כְּלוֹמַר: דֶּרֶךְ רָשָׁע תַּתְעֵהוּ, וְלֹא יַחֲרֹךְ אֶת צֵידוֹ שֶׁל רְמִיָּה שֶׁלּוֹ:",1,0],[12,27,"לֹא יַחֲרֹךְ. לֹא יַצְלִיחַ בְּתַרְמִיתוֹ. וּלְפִי שֶׁדִּבֵּר בִּלְשׁוֹן צַיִד, נוֹפֵל בּוֹ לְשׁוֹן חֲרִיכָה, שֶׁהַצַּיָּד הַמַּצְלִיחַ צָד אֶת הָעוֹפוֹת וְחוֹרְכָן בָּאֵשׁ:",2,0],[12,27,"וְהוֹן אָדָם יָקָר חָרוּץ. מִקְרָא מְסֹרָס הוּא וְהוֹן אָדָם שֶׁהוּא חָרוּץ יָקָר הוּא, מָמוֹן אָדָם כָּשֵׁר יָקָר הוּא:",3,0],[12,27,"חָרוּץ. עוֹשֶׂה אֱמֶת, כְּמוֹ ״יַד חֲרוּצִים תַּעֲשִׁיר״ (משלי י:ד):",4,0],[12,28,"בְּאֹרַח צְדָקָה חַיִּים וְדֶרֶךְ נְתִיבָה. שֶׁל צְדָקָה:",1,0],[12,28,"אַל מָוֶת. לֹא יָמוּת:",2,0],[13,1,"בֵּן חָכָם מוּסַר אָב. מִקְרָא קָצָר הוּא: בֵּן חָכָם שׁוֹאֵל וְאוֹהֵב מוּסַר אָב. וְיֵשׁ אוֹמְרִים: בִּשְׁבִיל מוּסַר הָאָב הוּא חָכָם:",1,0],[13,1,"וְלֵץ. לֹא שָׁמַע גְּעָרָה שֶׁאֵינוֹ מְקַבֵּל תּוֹכָחוֹת:",2,0],[13,2,"מִפְּרִי פִי אִישׁ יֹאכַל טוֹב. מִשְּׂכַר תּוֹרָתוֹ יֹאכַל טוֹב בָּעוֹלָם הַזֶּה, וְהַקֶּרֶן קַיֶּמֶת לָעוֹלָם הַבָּא:",1,0],[13,2,"וְנֶפֶשׁ בֹּגְדִים חָמָס. וְחֵפֶץ בּוֹגְדִים חָמָס, כְּמוֹ ״אִם יֵשׁ אֶת נַפְשְׁכֶם״ (בראשית כג:ח), ״אַל תִּתְּנֵנִי בְּנֶפֶשׁ צָרָי״ (תהלים כז:יב):",2,0],[13,3,"נוֹצֵר פִּיו שׁוֹמֵר נַפְשׁוֹ פֹּשֵׂק שְׂפָתָיו. פּוֹתֵחַ שְׂפָתָיו לְדַבֵּר תָּמִיד כָּל רוּחוֹ, מִן ״וַתְּפַשְּׂקִי אֶת רַגְלַיִךְ״ (יחזקאל טז:כה) לְשׁוֹן רָחָב:",1,0],[13,4,"מִתְאַוָּה וָאַיִן נַפְשׁוֹ עָצֵל. מִתְאַוָּה נַפְשׁוֹ לְכָל טוֹב וָאַיִן:",1,0],[13,4,"וְנֶפֶשׁ חָרֻצִים תְּדֻשָּׁן: יְשָׁרִים הָאוֹכְלִים יְגִיעַ כַּפֵּיהֶם. זֶהוּ מַשְׁמָעוֹ לְפִי פְּשׁוּטוֹ. וּלְפִי מְשָׁלוֹ: לֶעָתִיד יִרְאֶה בִּכְבוֹד תַּלְמִידֵי חֲכָמִים וְיִתְאַוֶּה, וְלֹא יַשִּׂיג לוֹ:",2,0],[13,5,"דְּבַר שֶׁקֶר יִשְׂנָא צַדִּיק. הַצַּדִּיק שׂוֹנֵא דְּבַר שֶׁקֶר, אֲבָל הָרָשָׁע מְקַבְּלוֹ:",1,0],[13,5,"יַבְאִישׁ וְיַחְפִּיר. אֶת הַבְּרִיּוֹת בְּכָךְ:",2,0],[13,6,"וְרִשְׁעָה תְּסַלֵּף חַטָּאת. כְּמוֹ חוֹטֵא, וְעַל שֶׁהוּא רָשָׁע גָּמוּר קוֹרְאֵהוּ חַטָּאת. וּמַשְׁמָעוּתָהּ: אֶת הַחוֹטֵא תְּסַלֵּף רִשְׁעָתוֹ, תְּקַלְקֵל אוֹתוֹ וְתַשְׁפִּילֵהוּ. כָּל סִלּוּף – קִלְקוּל וְכִשָּׁלוֹן הוּא, כְּמוֹ ״אִוֶּלֶת אָדָם תְּסַלֵּף דַּרְכּוֹ״ (משלי יט:ג), וְתָבוֹא עָלָיו רָעָה:",1,0],[13,7,"יֵשׁ מִתְעַשֵּׁר וְאֵין כֹּל. מַרְאֶה עַצְמוֹ עָשִׁיר. דָּבָר אַחֵר: יֵשׁ אָדָם שֶׁהוּא מִתְעַשֵּׁר בְּסוֹפוֹ, וְאֵין לוֹ כְּלוּם בִּתְחִלָּתוֹ, וְיֵשׁ שֶׁהוּא בָּא לִידֵי עֲנִיּוּת מִמָּמוֹן גָּדוֹל. דָּבָר אַחֵר: מִתְעַשֵּׁר בְּגֶזֶל עֲנִיִּים, וְסוֹף אֵין לוֹ כְּלוּם, וְיֵשׁ מִתְרוֹשֵׁשׁ עַל יְדֵי שֶׁפִּזֵּר וְנָתַן לָאֶבְיוֹנִים, וְהוֹן רָב מוּכָן לוֹ:",1,0],[13,8,"כֹּפֶר נֶפֶשׁ אִישׁ עָשְׁרוֹ. עָשְׁרוֹ שֶׁל אָדָם הוּא כֹּפֶר נַפְשׁוֹ, שֶׁעָשָׂה מִמֶּנּוּ צְדָקָה:",1,0],[13,8,"וְרָשׁ לֹא שָׁמַע גְּעָרָה. וּבִלְבַד שֶׁלֹּא יַשְׁמִיעַ גְּעָרָה לָרָשׁ שֶׁנּוֹתֵן לוֹ וְאֵינוֹ מַכְלִימוֹ. דָּבָר אַחֵר: כֹּפֶר נֶפֶשׁ אִישׁ עָשְׁרוֹ, תּוֹרָתוֹ:",2,0],[13,8,"וְרָשׁ. בְּדִבְרֵי תוֹרָה לֹא שָׁמַע גְּעָרָה. אֵינוֹ יוֹדֵעַ לָסוּר מִן הָרָעָה, לְפִי שֶׁלֹּא נִזְהָר. וּמִדְרַשׁ אַגָּדָה: עַל ״מַחֲצִית הַשֶּׁקֶל״ מְדַבֵּר, שֶׁהִטִּיל הַכָּתוּב עַל כָּל יִשְׂרָאֵל, וְהִשְׁוָה בּוֹ דַּל וְעָשִׁיר (שמות ל:טו); שֶׁאֵין הָרָשׁ שׁוֹמֵעַ גְּעָרָה וּכְלִמָּה מִן הֶעָשִׁיר, לֵאמֹר לוֹ: חֶלְקִי גָּדוֹל מֵחֶלְקְךָ בְּקָרְבְּנוֹת צִבּוּר:",3,0],[13,9,"יִדְעָךְ. לְשׁוֹן קְפִיצָה, שֶׁהַשַּׁלְהֶבֶת קוֹפֶצֶת וְנִכְרֶתֶת:",1,0],[13,10,"רַק בְּזָדוֹן יִתֵּן מַצָּה. מַחֲלֹקֶת:",1,0],[13,10,"וְאֶת נוֹעָצִים. וְעִם הַמִּתְיַעֲצִים תָּלִין חָכְמָה:",2,0],[13,11,"הוֹן מֵהֶבֶל יִמְעָט. עוֹשֶׂה גִּרְסָתוֹ חֲבִילוֹת חֲבִילוֹת יִמְעָט, שֶׁיִּשְׁתַּכַּח מִמֶּנּוּ מְעַט מְעַט (עבודה זרה יט.):",1,0],[13,12,"תּוֹחֶלֶת מְמֻשָּׁכָה. מַבְטִיחַ עַצְמוֹ עַל חֲבֵירוֹ וְאֵינוֹ עוֹשֶׂה:",1,0],[13,12,"מַחֲלָה לֵב. מְבִיאָה חוֹלִי לַלֵּב, וְאֵין מַחֲלָה זֶה שֵׁם דָּבָר כְּמוֹ ״וַהֲסִרֹתִי מַחֲלָה מִקִּרְבֶּךָ״ (שמות כג:כה) אֶלָּא כְּמוֹ ״מַעֲלֵה גֵרָה״ (ויקרא יא:ה):",2,0],[13,12,"וְעֵץ חַיִּים תַּאֲוָה בָאָה. מְסֹרָס הוּא, כְּלוֹמַר: תַּאֲוָה בָאָה הֲרֵי הוּא כְּעֵץ חַיִּים. תּוֹחֶלֶת שֶׁהוֹחִיל הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל וְצִפָּה שֶׁיָּשׁוּבוּ, וְהֵם לֹא שָׁבוּ, סוֹף בָּאָה לָהֶם לְמַחֲלַת לֵב; וּכְשֶׁתַּאֲוָתוֹ בָאָה, שֶׁהֵם עוֹשִׂין רְצוֹנוֹ, עֵץ חַיִּים הִיא לָהֶם:",3,0],[13,13,"בָּז לְדָבָר יֵחָבֶל לוֹ. הַבּוֹזֶה אֶחָד מִדִּבְרֵי תוֹרָה, סוֹף מִתְמַשְׁכֵּן עָלָיו:",1,0],[13,13,"וִירֵא מִצְוָה הוּא יְשֻׁלָּם. יְקַבֵּל שָׂכָר. וּמִדְרַשׁ תְּהִלִּים דּוֹרֵשׁ בָּז לְדָבָר יֵחָבֶל לוֹ עַל דָּוִד שֶׁאָמַר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, מָה הֲנָאָה בַּשּׁוֹטִים שֶׁבָּרָאתָ? אָמַר לוֹ: חַיֶּיךָ, סוֹף שֶׁתִּצְטָרֵךְ לְשִׁטּוּת; כְּשֶׁבָּא לִפְנֵי אָכִישׁ לְהִשְׁתַּגֵּעַ ״וַיּוֹרֶד רִירוֹ עַל זְקָנוֹ וְגוֹמֵר״ (שמואל א כא:יד):",2,0],[13,14,"תּוֹרַת חָכָם מְקוֹר חַיִּים. שֶׁהִיא מְלַמְּדַתּוֹ לָסוּר מִמֹּקְשֵׁי מָוֶת:",1,0],[13,15,"וְדֶרֶךְ בּוֹגְדִים אֵיתָן. קָשֶׁה לוֹ וְלַאֲחֵרִים:",1,0],[13,16,"כָּל עָרוּם יַעֲשֶׂה בְדָעַת. מַעֲשֵׂהוּ, כְּגוֹן דָּוִד: ״יְבַקְשׁוּ לַאדֹנִי הַמֶּלֶךְ נַעֲרָה בְתוּלָה וְגוֹמֵר״ (מלכים א א:ב):",1,0],[13,16,"וּכְסִיל יִפְרֹשׂ אִוֶּלֶת. זֶה אֲחַשְׁוֵרוֹשׁ, ״וְיַפְקֵד הַמֶּלֶךְ״ (אסתר ב:ג). יוֹדְעִים הָיוּ שֶׁלֹּא יִשָּׂא לְכֻלָּם, וּמִי שֶׁהָיָה לוֹ בַת הִטְמִינָהּ (מגילה יב:):",2,0],[13,17,"מַלְאָךְ רָשָׁע יִפֹּל בְּרָע. כְּגוֹן בִּלְעָם, שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא ״לֵךְ עִם הָאֲנָשִׁים״ (במדבר כב:כ, לה), וְהִרְשִׁיעַ לְהַשִּׂיא לְבָלָק עֵצָה רָעָה; לְכָךְ נָפַל בַּחֶרֶב (במדבר לא:ח):",1,0],[13,17,"וְצִיר אֱמוּנִים מַרְפֵּא. זֶה מֹשֶׁה רַבֵּינוּ:",2,0],[13,18,"רֵישׁ וְקָלוֹן. דַּלּוּת וְקָלוֹן בָּאִים עַל פּוֹרֵעַ מוּסָר:",1,0],[13,19,"תֶּעֱרַב לְנָפֶשׁ. כְּשֶׁבָּאָה תַּאֲוָתוֹ לוֹ לָאָדָם, הִיא עֲרֵבָה לְנַפְשׁוֹ; וּלְכָךְ תּוֹעֲבַת כְּסִיל לָסוּר מֵרָע, לְפִי שֶׁעָרֵב לָהֶם לְמַלֵּא תַּאֲוָתָם:",1,0],[13,19,"נִהְיָה. הֹוֶה. דָּבָר אַחֵר: תַּאֲוָה נִהְיָה הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְאַוֶּה שֶׁיַּעֲשׂוּ יִשְׂרָאֵל רְצוֹנוֹ, וּבִהְיוֹת תַּאֲוָתוֹ בָּאָה, עֲרֵבָה לוֹ. וְתוֹעֲבַת רְשָׁעִים – שֶׁיָּסוּרוּ מֵרָעָתָם, לְמַלֹּאות תַּאֲוָתָם:",2,0],[13,20,"הוֹלֵךְ אֶת חֲכָמִים. יֶחְכָּם, וְרֹעֶה כְסִילִים הַמְחַבֵּר לוֹ כְּסִילִים לִהְיוֹת לוֹ רֵעִים:",1,0],[13,20,"יֵרוֹעַ. יְרוּצַּץ:",2,0],[13,21,"חַטָּאִים תְּרַדֵּף רָעָה. אָדָם רָשָׁע, רִשְׁעָתוֹ רוֹדַפְתּוֹ עַד הִשָּׁמְדוֹ:",1,0],[13,22,"טוֹב יַנְחִיל. אֶת זְכוּתוֹ וְאֶת מָמוֹנוֹ לִבְנֵי בָנָיו, אֲבָל חוֹטֵא אֵינוֹ מַנְחִיל לְבָנָיו, כִּי צָפוּן חֵילוֹ וּמָמוֹנוֹ לַצַּדִּיק, כְּמוֹ שֶׁכָּתוּב ״וַתָּשֶׂם אֶסְתֵּר אֶת מָרְדֳּכַי עַל בֵּית הָמָן״ (אסתר ח:ב):",1,0],[13,23,"רָב אֹכֶל נִיר רָאשִׁים. רָאִיתִי בַּמָּסֹרֶת הַגְּדוֹלָה: רָב אֹכֶל. שְׁלֹשִׁים וּשְׁלֹשָׁה ׳רָב׳ – קְמָצִין, וְזֶהוּ חֲטַף קָמַץ, וּמְחֻבָּר עִם אֹכֶל בְּמַקֵּף; וְ׳אֹכֶל׳ רָאִיתִי שָׁם: נָקוּד פַּתַּח (ר״ל סגול שהוא פתח קטן) וְטַעֲמוֹ לְעֵילָא, כְּמוֹ ״אֶת כָּל אֹכֶל הַשָּׁנִים הַטּוֹבוֹת״ (בראשית מא:לה). וּלְפִי נְקֻדָּתוֹ, זֶה פִּתְרוֹנוֹ: הַרְבֵּה תְּבוּאָה בָּאָה לָעוֹלָם עַל יְדֵי נִיר אֲנָשִׁים דַּלִּים, כְּלוֹמַר: הַרְבֵּה תּוֹרָה יוֹצְאָה עַל יְדֵי תַּלְמִידִים, שֶׁרַבּוֹתֵיהֶם לְמֵדִין מֵהֶם מִתּוֹךְ פִּלְפּוּלָם שֶׁמְּפַלְפְּלִים בַּהֲלָכָה:",1,0],[13,23,"וְיֵשׁ נִסְפֶּה. וְיֵשׁ הַרְבֵּה מֵהֶם שֶׁהֵם כָּלִים מִן הָעוֹלָם בִּשְׁבִיל לֹא מִשְׁפָּט שֶׁאֵינָן נוֹהֲגִין כַּשּׁוּרָה, וּלְעִנְיַן הַתְּבוּאָה יֵשׁ תְּבוּאָה לוֹקָה בִּשְׁבִיל בְּעָלֶיהָ שֶׁאֵינוֹ מוֹצִיא מַעַשְׂרוֹתֶיהָ וּמַתְּנוֹת עֲנִיִּים כַּמִּשְׁפָּט, וְרַבּוֹתֵינוּ פֵּרְשׁוּ בְּמַסֶּכֶת חֲגִיגָה (חגיגה ד:-ה.), וְיֵשׁ נִסְפֶּה עַל שְׁלוּחוֹ שֶׁל מַלְאַךְ הַמָּוֶת שֶׁמְּחַלֵּף שֵׁם בְּשֵׁם וּמֵמִית אֶת שֶׁלֹּא הִגִּיעַ זְמַנּוֹ אֲבָל אִם כֵּן הוּא אֵין עִנְיַן סוֹף הַפָּסוּק לְרֹאשׁוֹ:",2,0],[13,24,"חוֹשֵׂךְ שִׁבְטוֹ. סוֹפוֹ שֶׁשּׂוֹנֵא אֶת בְּנוֹ, שֶׁרוֹאֵהוּ בְּסוֹפוֹ יוֹצֵא לְתַרְבּוּת רָעָה:",1,0],[13,24,"שִׁחֲרוֹ מוּסָר. תָּמִיד לַבְּקָרִים מְיַסְּרֵהוּ:",2,0],[13,25,"לְשֹׂבַע נַפְשׁוֹ. דּוֹמֶה שֶׁיְּהֵא שָׂבֵעַ (סא״א ונכתב תחתיו):",1,0],[13,25,"תֶּחְסָר. אֵינוֹ דּוֹמֶה שֶׁיְּהֵא שָׂבֵעַ:",2,0],[14,1,"חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ. חָכְמוֹת נָקוּד פַּתָּח, שֶׁאֵינוֹ שֵׁם דָּבָר, אֶלָּא הַחֲכָמוֹת שֶׁבַּנָּשִׁים בּוֹנוֹת אֶת בָּתֵּיהֶם – שֶׁמִּתְקַיְּמוֹת עַל יְדֵיהֶן; כְּמוֹ אִשְׁתּוֹ שֶׁל אוֹן בֶּן פֶּלֶת, כְּמוֹ שֶׁמְּפֹרָשׁ בְּפֶרֶק ׳חֵלֶק׳ (סנהדרין קט:-קי.):",1,0],[14,1,"וְאִוֶּלֶת. וְאִשָּׁה שׁוֹטָה:",2,0],[14,1,"בְּיָדֶיהָ תֶּהֶרְסֶנּוּ. תַּהֲרֹס בֵּיתָהּ; זוֹ אִשְׁתּוֹ שֶׁל קֹרַח (במדבר טז:א):",3,0],[14,2,"הוֹלֵךְ בְּיָשְׁרוֹ יְרֵא. מִי שֶׁהוּא יְרֵא ה׳, וּמִי שֶׁהוּא נְלוֹז דְּרָכִים, כְּלוֹמַר: עוֹקֵם דְּרָכָיו:",1,0],[14,2,"בוזהו. לְהַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[14,3,"בְּפִי אֱוִיל חֹטֶר גַּאֲוָה. מַקֵּל שֶׁל גַּאֲוָה, כְּגוֹן פַּרְעֹה, שֶׁאָמַר ״מִי ה׳ אֲשֶׁר אֶשְׁמַע בְּקוֹלוֹ״ (שמות ה:ב):",1,0],[14,3,"תִּשְׁמוּרֵם. כְּמוֹ ״תִּשְׁמְרֵם״ (משלי כב:יח) – תִּשְׁמֹר אֶת הַחֲכָמִים:",2,0],[14,4,"בְּאֵין אֲלָפִים אֵבוּס בָּר. בְּאֵין שְׁוָורִים הָאֵבוּס רֵיקָם, שֶׁאֲפִלּוּ תֶּבֶן אֵין מָצוּי בַּבַּיִת:",1,0],[14,4,"בָּר. נָקִי וְרֵיקָם, כְּלוֹמַר: בְּמָקוֹם שֶׁאֵין תַּלְמִידֵי חֲכָמִים אֵין הוֹרָאָה נִמְצֵאת כַּהֲלָכָה:",2,0],[14,5,"וְיָפִיחַ כְּזָבִים. וְתָמִיד מְדַבֵּר כָּזָב עֵד שָׁקֶר:",1,0],[14,6,"בִּקֶּשׁ לֵץ חָכְמָה. כְּשֶׁהוּא צָרִיךְ אֶל הַחָכְמָה אֵינוֹ מוֹצְאָהּ בְּלִבּוֹ:",1,0],[14,7,"לֵךְ מִנֶּגֶד לְאִישׁ כְּסִיל. מֵהִתְחַבֵּר תָּמִיד אֶצְלוֹ:",1,0],[14,7,"וּבַל יָדַעְתָּ. סוֹפְךָ שֶׁלֹּא יָדַעְתָּ חָכְמָה:",2,0],[14,8,"חָכְמַת עָרוּם. מִי שֶׁהוּא חָכָם הָבִין דַּרְכּוֹ לְפַלֵּס אָרְחוֹתָיו:",1,0],[14,8,"וְאִוֶּלֶת כְּסִילִים. הִיא הַמִּרְמָה שֶׁבְּלִבָּם, סוֹפָהּ שֶׁמְּבִיאָתָם לִידֵי טִפְּשׁוּת:",2,0],[14,9,"אֱוִילִים יָלִיץ אָשָׁם. שֶׁהֵם חוֹטְאִים, שֶׁצְּרִיכִין לָתֵת מָמוֹן לְמִי שֶׁחָטְאוּ לוֹ, וְיָלִיץ בַּעֲדָם אֲשָׁמָם, שֶׁהֵם מְבִיאִים מְמוֹנָם לוֹ; כְּמוֹ הַפְּלִשְׁתִּים שֶׁנֶּאֱמַר ״קְחוּ לָכֶם חֲמִשָּׁה טְחוֹרֵי זָהָב וַחֲמִשָּׁה עַכְבְּרֵי זָהָב וְגוֹמֵר וּנְתַתֶּם לֵאלֹהֵי יִשְׂרָאֵל כָּבוֹד אוּלַי יָקֵל אֶת יָדוֹ מֵעֲלֵיכֶם״ (שמואל א ו:ד-ה):",1,0],[14,9,"אָשָׁם. אַמֶנְדָ״א בְּלַעַ״ז:",2,0],[14,9,"וּבֵין יְשָׁרִים רָצוֹן. אַפֵּיְימִינְ״ט בְּלַעַ״ז, הַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה לָהֶם:",3,0],[14,10,"לֵב יוֹדֵעַ מָרַּת נַפְשׁוֹ. טָרְחוֹ וִיגִיעוֹ שֶׁעָמַל בַּתּוֹרָה, לְפִיכָךְ בְּשִׂמְחָתוֹ לֹא יִתְעָרַב זָר כְּשֶׁיְּקַבֵּל שְׂכָרוֹ לֶעָתִיד. דָּבָר אַחֵר: לֵב יוֹדֵעַ מָרַּת נַפְשׁוֹ יִשְׂרָאֵל שֶׁהֵם מָרֵי נֶפֶשׁ בַּגָּלוּת וְהָיוּ נֶהֱרָגִים עַל קְדֻשַּׁת הַשֵּׁם וּבְשִׂמְחָתוֹ לֹא יִתְעָרַב זָר לֶעָתִיד. בֵּית רְשָׁעִים. בֵּית אֲרַם יִשָּׁמֵד.",1,0],[14,12,"יֵשׁ דֶּרֶךְ יָשָׁר לִפְנֵי אִישׁ. עוֹבֵר עֲבֵירָה וְאוֹמֵר אֵין בָּהּ עֲבֵירָה. דָּבָר אַחֵר: יֵשׁ דֶּרֶךְ יָשָׁר לִפְנֵי אִישׁ. דֶּרֶךְ עָצֵל יְשָׁרָה הָיְתָה בְּעֵינֵי עֵשָׂו שֶׁהָיָה אִישׁ שָׂדֶה (בראשית כה:כז), וְאַחֲרִיתָהּ וְגוֹ׳:",1,0],[14,13,"גַּם בִּשְׂחוֹק. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׂחֵק עִמָּהֶם בָּעוֹלָם הַזֶּה, יִכְאַב לִבָּם לֶעָתִיד לָבֹא. וְכֵן הוּא אוֹמֵר ״וְאַתֶּם תִּצְעֲקוּ מִכְּאֵב לֵב״ (ישעיהו סה:יד):",1,0],[14,14,"מִדְּרָכָיו יִשְׂבַּע סוּג לֵב. עֵשָׂו:",1,0],[14,14,"וּמֵעָלָיו אִישׁ טוֹב. יַעֲקֹב:",2,0],[14,15,"פֶּתִי יַאֲמִין. לְדִבְרֵיהֶם וְנִסָּת אַחֲרֵיהֶם. דָּבָר אַחֵר: בִּשְׂחוֹק יִכְאַב לֵב, ״שְׂחוֹק לִכְסִיל עֲשׂוֹת זִמָּה״ (משלי י:כג), וְסוֹפוֹ יִכְאַב לֵב. סוּג לֵב – רָשָׁע, כְּמוֹ ״כֶּסֶף סִיגִים״ (משלי כו:כג). סוּג הוּא שֵׁם הַפְּסֹלֶת, סוּג הוּא הַכֶּסֶף הַמְעֻרְבָּב בַּפְּסֹלֶת:",1,0],[14,15,"וּמֵעָלָיו אִישׁ טוֹב. וּמִמַּעַל לוֹ לָרָשָׁע, יִהְיֶה הַצַּדִּיק:",2,0],[14,15,"פֶּתִי יַאֲמִין. לְאַנְשֵׁי רָכִיל:",3,0],[14,15,"וְעָרוּם יָבִין לַאֲשׁוּרוֹ. לִפְסִיעוֹתָיו, כְּלוֹמַר: יְצַפֶּה מִלָּרִיב, וְיַמְתִּין עַד יִוָּדַע לוֹ אֶל נָכוֹן (שמואל א כו:ד):",4,0],[14,16,"חָכָם יָרֵא. מִן הַפּוּרְעָנוּת:",1,0],[14,16,"וְסָר מֵרָע. מִן הָרָעָה:",2,0],[14,16,"וּכְסִיל מִתְעַבֵּר. מִתְחַזֵּק לַעֲבֹד בְּחָזְקָה:",3,0],[14,16,"וּבוֹטֵחַ. וּמַחֲלִיק וְנוֹפֵל בָּאָרֶץ, כְּמוֹ ״בְּאֶרֶץ שָׁלוֹם אַתָּה בוֹטֵחַ״ (ירמיה יב:ה), וְתִרְגֵּם יוֹנָתָן: ״אַתְּ מִתְבַּטַּח וְנָפוֹל״ – מַחֲלִיק. וְיֵשׁ מְפָרְשִׁים: בִּטָּחוֹן מַמָּשׁ, בְּהֵיכָלוֹ; בּוֹטֵחַ לוֹמַר: לֹא תְבוֹאֵנִי רָעָה:",4,0],[14,17,"קְצַר אַפַּיִם. הַמְּמַהֵר לִנְקֹם כַּעֲסוֹ:",1,0],[14,17,"וְאִישׁ מְזִמּוֹת. מַחֲשָׁבוֹת עֵצָה רָעָה:",2,0],[14,18,"יַכְתִּירוּ דָעַת. יַעֲשׂוּהוּ כֶּתֶר לְרֹאשָׁם, וְסוֹף:",1,0],[14,19,"שָׁחוּ רָעִים לִפְנֵי טוֹבִים. לֶעָתִיד:",1,0],[14,20,"גַּם לְרֵעֵהוּ יִשָּׂנֵא רָשׁ. אֲפִלּוּ לְשׁוֹשְׁבִינָיו וְאוֹהֲבָיו. גַּם לְשׁוֹן אֲפִלּוּ:",1,0],[14,20,"יִשָּׂנֵא רָשׁ. עַם הָאָרֶץ שֶׁאֵינוֹ יוֹדֵעַ לִנְהוֹג כַּשּׁוּרָה:",2,0],[14,23,"בְּכָל־עֶצֶב. בְּכָל יְגִיעַ מְלָאכָה יִהְיֶה רֶוַח, אֲבָל דִּבְרֵי הֶבֶל אַךְ לְמַחְסוֹר:",1,0],[14,24,"עֲטֶרֶת חֲכָמִים עָשְׁרָם. שֶׁהֵם עֲשִׁירִים בַּתּוֹרָה:",1,0],[14,24,"וְאִוֶּלֶת כְּסִילִים אִוֶּלֶת. קַלְקַלְתָּן שֶׁל כְּסִילִים הִיא הָאִוֶּלֶת, שֶׁנִּתְעַצֵּל מִן הַחָכְמָה:",2,0],[14,26,"בְּיִרְאַת ה׳ מִבְטַח עֹז. נֶאֱמַר בְּאַבְרָהָם ״כִּי עַתָּה יָדַעְתִּי כִּי יְרֵא אֱלֹהִים אַתָּה״ (בראשית כב:יב), וְהִבְטִיחוֹ ״כִּי בָרֵךְ אֲבָרֶכְךָ וְגוֹ׳״ (בראשית כב:יז):",1,0],[14,26,"וּלְבָנָיו יִהְיֶה הוּא:",2,0],[14,26,"מַחְסֶה. שֶׁיֵּחָסוּ וְיִתְחַבֵּא בְּצֵל זְכוּתוֹ:",3,0],[14,28,"בְּרָב עָם. שֶׁהַצִּבּוּר זַכָּאִים – הַדְרַת הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא:",1,0],[14,28,"וּבְאֶפֶס לְאֹם. כְּשֶׁאֵינָם דְּבֵקִים בּוֹ:",2,0],[14,28,"מְחִתַּת רָזוֹן. חֶסְרוֹן רַזְנוּתוֹ הוּא, כִּבְיָכוֹל נוֹתֵן מִכְּבוֹדוֹ לֵאלֹהֵי נֵכָר וּמַשְׁלִיט אֶת הָאֻמּוֹת עַל בָּנָיו:",3,0],[14,29,"מֵרִים אִוֶּלֶת. מַפְרִישָׁהּ לְחֶלְקוֹ:",1,0],[14,30,"חַיֵּי בְשָׂרִים לֵב מַרְפֵּא. לֵב בָּשָׂר, שֶׁהוּא רוֹפֵא אֶת הָרָעָה וְעוֹבֵר עַל מִדּוֹתָיו, הוּא חַיֵּי בְּרִיּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֵן בָּשָׂר וָדָם:",1,0],[14,30,"וּרְקַב עֲצָמוֹת קִנְאָה. אָדָם בַּעַל חֵמָה, רִקָּבוֹן עֲצָמוֹת הוּא לַכֹּל:",2,0],[14,32,"וְחֹסֶה בְמוֹתוֹ צַדִּיק. כְּשֶׁיָּמוּת, הוּא בָּטוּחַ שֶׁיָּבֹא לְגַן עֵדֶן:",1,0],[14,33,"בְּלֵב נָבוֹן תָּנוּחַ חָכְמָה. תִּשְׁכֹּן וְתִשְׁקֹט בְּנַחַת, לְשׁוֹן מְנוּחָה וּמַרְגּוֹעַ:",1,0],[14,33,"וּבְקֶרֶב כְּסִילִים תִּוָּדֵעַ. מְעַט חָכְמָה שֶׁבְּלִבּוֹ מַכְרִיזָה; אִיסְתְּרָא בְּלָגִינָא קִישׁ קִישׁ קָרְיָא (בבא מציעא פה:):",2,0],[14,34,"צְדָקָה תְרוֹמֵם גּוֹי. יִשְׂרָאֵל:",1,0],[14,34,"וְחֶסֶד לְאֻמִּים חַטָּאת. הֵם עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁגּוֹזְלִים מִזֶּה וְנוֹתְנִים לָזֶה:",2,0],[14,35,"וְעֶבְרָתוֹ תִּהְיֶה לְעֶבֶד מֵבִישׁ (בבא בתרא י:):",1,0],[15,4,"וְסֶלֶף בָּהּ שֶׁבֶר בְּרוּחַ. כְּשֶׁיְּסַלֵּף בַּלָּשׁוֹן, סוֹפָהּ לְהָבִיא עָלָיו שֶׁבֶר הַבָּא בְּרוּחַ קָדִים, הַמּוּכָנָה לְהִפָּרַע מִן הָרְשָׁעִים, כְּמוֹ שֶׁאָמַר ״בְּרוּחַ קָדִים עַזָּה״ (שמות יד:כא), ״בְּרוּחַ קָדִים אֲפִיצֵם״ (ירמיה יח:יז), ״בְּרוּחַ קָדִים תְּשַׁבֵּר אֳנִיּוֹת תַּרְשִׁישׁ״ (תהלים מח:ח):",1,0],[15,6,"בֵּית צַדִּיק חֹסֶן רָב. בֵּית הַמִּקְדָּשׁ שֶׁבָּנָה דָּוִד הַצַּדִּיק חֹסֶן רַב וּמִגְדַּל עֹז לְיִשְׂרָאֵל:",1,0],[15,6,"וּבִתְבוּאַת רָשָׁע נֶעְכָּרֶת. וּבַהֲבָאַת הַצֶּלֶם שֶׁהֵבִיא מְנַשֶּׁה (דברי הימים ב לג:ז) בָּהּ נֶעְכְּרָה (דברים רבה ב:כ):",2,0],[15,7,"שִׂפְתֵי חֲכָמִים יְזָרוּ דָעַת. יַכְתִּירוּ דַעַת, כְּמוֹ ״זֵר זָהָב״ (שמות כה:יא):",1,0],[15,7,"לֹא כֵן. אֵינוֹ אֱמֶת:",2,0],[15,8,"זֶבַח רְשָׁעִים. תּוֹעֵבָה בָּלָק וּבִלְעָם (במדבר כב-כד):",1,0],[15,8,"וּתְפִלַּת יְשָׁרִים. זֶה מֹשֶׁה :",2,0],[15,10,"מוּסָר רָע לְעוֹזֵב אֹרַח. יִסּוּרִים קָשִׁים מוּכָנִים לְעוֹבֵר אֹרַח שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[15,11,"שְׁאוֹל וַאֲבַדּוֹן נֶגֶד ה׳. גָּלוּי לְפָנָיו כָּל אֲשֶׁר בְּתוֹכָהּ:",1,0],[15,11,"אַף כִּי. קַל וָחֹמֶר הוּא:",2,0],[15,13,"לֵב שָׂמֵחַ יֵיטִיב פָּנִים. אִם תְּשַׂמַּח לִבּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלֶכְתְּךָ בִּדְרָכָיו, וְיֵיטִיב לְךָ פָּנָיו לַעֲשׂוֹת כָּל רְצוֹנְךָ. וְאִם תְּעַצְּבֵהוּ, יַרְאֶה לְךָ רוּחַ נְכֵאָה, כְּמָה דְּאַתְּ אָמַר (בראשית ו:ו-ז) ״וַיִּתְעַצֵּב אֶל לִבּוֹ וַיֹּאמֶר ה׳ אֶמְחֶה אֶת הָאָדָם וְגוֹמֵר״. רוּחַ נְכֵאָה טלנ״ט, רוּחַ שֶׁל זַעַף:",1,0],[15,15,"כָּל יְמֵי עָנִי רָעִים. וַאֲפִלּוּ שַׁבָּתוֹת וְיָמִים טוֹבִים, דְּאָמַר שְׁמוּאֵל (סנהדרין ק:): שִׁנּוּי וֶסֶת תְּחִלַּת חֳלִי מֵעַיִם:",1,0],[15,15,"וְטוֹב לֵב. מִי שֶׁלִּבּוֹ טוֹב בְּעָשְׁרוֹ:",2,0],[15,15,"מִשְׁתֶּה תָמִיד. כָּל שְׁנוֹתָיו דּוֹמוֹת לוֹ יְמֵי מִשְׁתֶּה, לְלַמֶּדְךָ שֶׁיְּהֵא אָדָם שָׂמֵחַ בְּחֶלְקוֹ (אבות ד:א). וְרַבּוֹתֵינוּ דָּרְשׁוּ מַה שֶּׁדָּרְשׁוּ בְּחֵלֶק (סנהדרין ק:-קא.):",3,0],[15,16,"טוֹב מְעַט בְּיִרְאַת ה׳ מֵאוֹצָר רָב וּמְהוּמָה בוֹ. קוֹל בְּנֵי אָדָם צוֹעֲקִים, שֶׁנַּעֲשָׂה הָאוֹצָר מִגֶּזֶל וְחָמָס. כְּמוֹ ״וּרְאוּ מְהוּמוֹת רַבּוֹת בְּתוֹכָהּ וַעֲשׁוּקִים בְּקִרְבָּהּ״ (עמוס ג:ט):",1,0],[15,17,"מִשּׁוֹר אָבוּס. שֶׁאוֹבְסִין לוֹ הַמַּאֲכָל בְּפִיו עַל כָּרְחוֹ כְּדֵי לְפַטְּמוֹ, וְכֵן ״בַּרְבֻּרִים אֲבוּסִים״ (מלכים א ד:כג). וְיֵשׁ לְמוֹשְׁלוֹ כְּנֶגֶד קֹמֶץ מְעַט שֶׁל עָנִי שֶׁחָבִיב מִשּׁוֹר חַטָּאת שֶׁל רָשָׁע. דָּבָר אַחֵר: טוֹב אֲרֻחַת יָרָק לָתֵת לֶעָנִי, וְאַהֲבָה שָׁם לְהַרְאוֹת לוֹ פָּנִים יָפוֹת מִשּׁוֹר אָבוּס לְהַאֲכִילוֹ בָּשָׂר שָׁמֵן וְיַרְאֵנוּ פָּנִים זוֹעֲפוֹת:",1,0],[15,18,"אִישׁ חֵמָה יְגָרֶה מָדוֹן. אָדָם שֶׁאֵין מַעֲצוֹר לְרוּחוֹ לְהַאֲרִיךְ חֲמָתוֹ, יְגָרֶה מָדוֹן:",1,0],[15,18,"וְאֶרֶךְ אַפַּיִם. שֶׁאֵינוֹ מְמַהֵר לְהִנָּקֵם וְלָרִיב:",2,0],[15,18,"יַשְׁקִיט רִיב. שֶׁהוּא כָּלֶה וְשָׁקַט מֵעָלָיו (  מֵאֵלָיו):",3,0],[15,19,"דֶּרֶךְ עָצֵל כִּמְשׂוּכַת חָדֶק. דּוֹמֶה בְּעֵינָיו כְּאִלּוּ הַדְּרָכִים גְּדוּרִים לְפָנָיו בְּגֶדֶר חֲדָקִים:",1,0],[15,19,"מְשׂוּכַת. גָּדֵר, כְּמוֹ ״הָסֵר מְשׂוּכָתוֹ״ (ישעיה ה:ה). חָדֶק – קוֹצִים:",2,0],[15,19,"וְאֹרַח יְשָׁרִים סְלוּלָה. כְּבוּשָׁה וּמוּפְנָה. וּמִדְרַשׁ אַגָּדָה (תנחומא, כי תשא א): דַּרְכּוֹ שֶׁל עֵשָׂו כְּקוֹץ זֶה הַנִּסְבָּךְ בְּגִזַּת צֶמֶר, אִם תִּטְּלֵהוּ מִכָּאן, הוּא מִתְעָרֶה בְּכָאן; כָּךְ אֵין אָדָם יָכוֹל לָצֵאת יְדֵי עֲלִילוֹתָיו בְּלֹא מָמוֹן:",3,0],[15,20,"בֵּן חָכָם יְשַׂמַּח אָב וּכְסִיל אָדָם בּוֹזֶה אִמּוֹ. גּוֹרֵם לְאִמּוֹ שֶׁמְּבַזִּים אוֹתָהּ:",1,0],[15,21,"אִוֶּלֶת. שִׂמְחָה הִיא לַחֲסַר לֵב:",1,0],[15,22,"הָפֵר מַחֲשָׁבוֹת בְּאֵין סוֹד. בְּלֹא עֵצָה לֹא תָקוּם מַחֲשָׁבָה:",1,0],[15,23,"שִׂמְחָה לָאִישׁ בְּמַעֲנֵה פִיו. כְּמַשְׁמָעוֹ: עַל יְדֵי מַעֲנֶה רַךְ וְדִבּוּר נַחַת, הַבְּרִיּוֹת אוֹהֲבִים אוֹתוֹ. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ עַל בַּעֲלֵי גִּירְסָא (סנהדרין קא.): אִם מוֹצְאִים בְּפִיהֶם מַעֲנֶה, אָז תִּתְקַיֵּם בָּם וְיִשְׂמְחוּ:",1,0],[15,23,"וְדָבָר בְּעִתּוֹ מַה טּוֹב. שׁוֹאֲלִים בְּהִלְכוֹת הַפֶּסַח וּבְהִלְכוֹת הֶחָג בִּזְמַנּוֹ (פסחים ו.):",2,0],[15,24,"אֹרַח חַיִּים לְמַעְלָה לְמַשְׂכִּיל. כְּמוֹ ״שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ״ (ישעיהו ו:ב), כְּלוֹמַר: לִפְנֵי הֶחָכָם קְשׁוּטָה וּמוּכָנָה אֹרַח חַיִּים:",1,0],[15,27,"עוֹכֵר בֵּיתוֹ. שֶׁהוּא בּוֹצֵעַ בָּצַע:",1,0],[15,27,"וְשׂוֹנֵא מַתָּנוֹת יִחְיֶה. מֵאַחַר שֶׁהוּא שׂוֹנֵא מַתָּנוֹת, כָּל שֶׁכֵּן שֶׁשּׂוֹנֵא אֶת הַגָּזֵל:",2,0],[15,28,"לֵב צַדִּיק יֶהְגֶּה לַעֲנוֹת. יַחְשֹׁב וְיָבִין מַה יַּעֲנֶה, קֹדֶם שֶׁיָּשִׁיב דָּבָר:",1,0],[15,30,"מְאוֹר עֵינַיִם. בַּתּוֹרָה:",1,0],[15,30,"יְשַׂמַּח לֵב. שֶׁשּׁוֹאֲלִין מִמֶּנּוּ דָּבָר וְיוֹדֵעַ מַה לְּהָשִׁיב. וּלְפִי פְּשׁוּטוֹ כְּמַשְׁמָעוֹ: דָּבָר שֶׁהוּא תַּאֲוָה לְמַרְאוֹת עֵינַיִם, יְשַׂמַּח הַלֵּב וּמְצַחְצֵחַ תּוּגַת הַלֵּב, כְּגוֹן גַּן יָרָק וּנְהָרוֹת הַמּוֹשְׁכִים:",2,0],[15,33,"וְלִפְנֵי כָבוֹד עֲנָוָה. הָעֲנָוָה גּוֹרֶמֶת שֶׁהַכָּבוֹד בָּא:",1,0],[16,1,"לְאָדָם מַעַרְכֵי לֵב. הוּא סוֹדֵר עֲצָתוֹ וּדְבָרָיו בְּלִבּוֹ:",1,0],[16,1,"וּמֵה׳ מַעֲנֵה לָשׁוֹן. כְּשֶׁבָּא לְהָשִׁיב, הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׂכִּילוֹ בִּדְבָרָיו, אוֹ אִם זָכָה מְזַמֵּן לוֹ מַעֲנֶה טוֹב:",2,0],[16,2,"וְתֹכֵן רוּחוֹת ה׳. וּמוֹנֶה הַלְּבָבוֹת, מִי הַטּוֹב וּמִי הָרָע:",1,0],[16,3,"גֹּל אֶל ה׳ מַעֲשֶׂיךָ. גַּלְגֵּל וְהַשְׁלֵךְ עָלָיו צְרָכֶיךָ וְיִכֹּנוּ מַחְשְׁבֹתֶיךָ. דָּבָר אַחֵר: גֹּל אֶל ה׳ מַעֲשֶׂיךָ, הִתְפַּלֵּל לְפָנָיו עַל כָּל צְרָכֶיךָ:",1,0],[16,3,"וְיִכֹּנוּ. יִתְבַּסְּסוּ וְיִתְקַיְּמוּ:",2,0],[16,4,"כֹּל פָּעַל ה׳ לְמַעֲנֵהוּ. הַכֹּל עָשָׂה בִּשְׁבִיל קִלּוּסוֹ, כְּמוֹ ״עֱנוּ לַה׳ בְּתוֹדָה״ (תהלים קמז:ז). דָּבָר אַחֵר: לְהָעִיד עָלָיו, כְּלוֹמַר: פָּעֳלוֹ מֵעִיד עָלָיו עַל גְּבוּרוֹתָיו. שְׁנֵיהֶם בְּהַגָּדַת תְּהִלִּים:",1,0],[16,4,"וְגַם רָשָׁע. עָשָׂה לְהַנִּיחוֹ לְיוֹם רָעָה, וְכָל זֶה לְקִלּוּסוֹ:",2,0],[16,5,"יָד לְיָד לֹא יִנָּקֶה. מִיָּד לְיָד בָּא לוֹ גְּמוּל גֹּבַהּ לִבּוֹ:",1,0],[16,6,"וּבְיִרְאַת ה׳ סוּר מֵרָע. עַל יְדֵי יִרְאַת ה׳ סוּר מֵרָע:",1,0],[16,7,"בִּרְצוֹת ה׳ דַּרְכֵי אִישׁ גַּם אוֹיְבָיו יַשְׁלִם אִתּוֹ. יֵרָצֶה לוֹ שֶׁיִּהְיוּ שְׁלֵמִים עִמּוֹ:",1,0],[16,9,"לֵב אָדָם יְחַשֵּׁב דַּרְכּוֹ. לָלֶכֶת דֶּרֶךְ יָשָׁר:",1,0],[16,9,"וַה׳ יָכִין צַעֲדוֹ. כְּמוֹ שֶׁשָּׁנִינוּ (שבת קד.): הַבָּא לִטָּהֵר מְסַיְּעִין לוֹ:",2,0],[16,10,"קֶסֶם עַל שִׂפְתֵי מֶלֶךְ. עַל שִׂפְתֵי חָכָם הַיּוֹשֵׁב בְּדִין:",1,0],[16,11,"פֶּלֶס וּמֹאזְנֵי מִשְׁפָּט וְגוֹ׳. לְשַׁלֵּם לָאָדָם כְּפָעֳלוֹ, מִשְׁפָּט יוּשְׁטִיצָ״ה בְּלַעַ״ז, פֵּרָעוֹן עֲוֹנוֹת הָאָדָם בְּפֶלֶס וּמֹאזְנַיִם:",1,0],[16,11,"מַעֲשֵׂהוּ כָּל אַבְנֵי כִיס. כַּאֲשֶׁר יֵשׁ בְּאַבְנֵי כִיס מִשְׁקָלוֹת גְּדוֹלוֹת וּקְטַנּוֹת, הַכֹּל לְפִי פָּעֳלוֹ שֶׁל אָדָם:",2,0],[16,12,"תּוֹעֲבַת מְלָכִים עֲשׂוֹת רֶשַׁע. דָּבָר תָּעוּב הוּא לַדַּיָּנִין וְאֵין הָגוּן לָהֶם לַעֲשׂוֹת רֶשַׁע:",1,0],[16,14,"חֲמַת מֶלֶךְ. הוּא כְּמַלְאֲכֵי מָוֶת, כִּשְׁלוּחֵי מִיתָתָם:",1,0],[16,14,"וְאִישׁ חָכָם יְכַפְּרֶנָּה. יְפַיְּסֶנָּה:",2,0],[16,15,"בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים. מִי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַסְבִּיר לוֹ פָּנִים, חַיִּים הוּא לוֹ, לְכָךְ צָרִיךְ אָדָם לְיַשֵּׁר דַּרְכּוֹ לְפָנָיו:",1,0],[16,15,"וּרְצוֹנוֹ כְּעָב מַלְקוֹשׁ. מִי שֶׁהוּא מְרֻצֶּה לוֹ, רְצוֹנוֹ טוֹב לוֹ כְּעָב הַמֵּבִיא אֶת הַמָּטָר:",2,0],[16,19,"טוֹב שְׁפַל רוּחַ. טוֹב לְהִתְחַבֵּר אֶת עֲנָוִים וְלִהְיוֹת אִתָּם שְׁפַל רוּחַ, מִהֱיוֹת מְחַלֵּק שָׁלָל אֶת גֵּאִים:",1,0],[16,20,"מַשְׂכִּיל עַל דָּבָר יִמְצָא טוֹב. הַנּוֹתֵן לֵב לְהִתְבּוֹנֵן עַל דְּבָרָיו לְפַלֵּס אֶת דְּרָכָיו יִמְצָא טוֹב:",1,0],[16,20,"וּבוֹטֵחַ בַּה׳ אַשְׁרָיו. כְּשֶׁהוּא מְפַלֵּס דְּרָכָיו וְרוֹאֶה בָּהּ מִצְוָה שֶׁיֵּשׁ בָּהּ סַכָּנָה אוֹ חֶסְרוֹן כִּיס, וּבוֹטֵחַ בְּהַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹשֶׂה הַטּוֹב:",2,0],[16,20,"אַשְׁרָיו. הֵן אֲשׁוּרָיו שֶׁלּוֹ:",3,0],[16,21,"לַחֲכַם לֵב יִקָּרֵא נָבוֹן. שֶׁלָּמַד חָכְמָה מֵרַבּוֹ:",1,0],[16,21,"יִקָּרֵא נָבוֹן. סוֹפוֹ שֶׁיִּהְיֶה נָבוֹן בִּדְבָרִים, מְפֻלְפָּל בְּחָכְמָתוֹ, וְיִקְרְאוּ אוֹתוֹ נָבוֹן:",2,0],[16,21,"וּמֶתֶק שְׂפָתַיִם יוֹסִיף לֶקַח. כְּשֶׁאָדָם מַטְעִים דְּבָרָיו לְתַלְמִיד וּמַמְתִּיק דְּבָרָיו בִּטְעָמִים, יוֹסִיף לֶקַח:",3,0],[16,22,"מְקוֹר חַיִּים שֵׂכֶל. לִבְעָלָיו וְכֵן פִּתְרוֹן הַמִּקְרָא: שֵׂכֶל הַבְּעָלִים מְקוֹר חַיִּים הוּא לוֹ:",1,0],[16,22,"וּמוּסַר אֱוִילִים אִוֶּלֶת. יִסּוּרֵי אֱוִילִים עַל יְדֵי אִוֶּלֶת בָּאִים לָהֶם, וְכֵן מַשְׁמָעוֹ: הָאִוֶּלֶת יִסּוּרִין הוּא לָאֱוִילִים:",2,0],[16,23,"לֵב חָכָם יַשְׂכִּיל פִּיהוּ. לִבּוֹ מְלַמֵּד אֶת פִּיו לְדַבֵּר צָחוֹת. (וְעַל שְׂפָתָיו יוֹסִיף לִבּוֹ לֶקַח):",1,0],[16,24,"צוּף דְּבַשׁ. מְתוֹק דְּבַשׁ, בְּרִישְׁקָ״ה בְּלַעַ״ז:",1,0],[16,24,"אִמְרֵי נֹעַם. דִּבְרֵי תוֹרָה:",2,0],[16,25,"יֵשׁ דֶּרֶךְ. שֶׁהוּא יָשָׁר לִפְנֵי אִישׁ:",1,0],[16,26,"עָמְלָה לוֹ. לְצָרְכּוֹ הוּא עָמֵל:",1,0],[16,26,"כִּי אָכַף עָלָיו פִּיהוּ. כְּשֶׁפִּיהוּ כּוֹפֵהוּ וְתוֹבֵעַ לוֹ מַאֲכָל, אָז עֲמָלוֹ עוֹמֶדֶת לוֹ, שֶׁאָכַל מַה שֶּׁעָמַל כְּבָר:",2,0],[16,27,"כּוֹרֶה רָעָה. בְּלִבּוֹ חוֹרֵשׁ הָרָע:",1,0],[16,27,"וְעַל. שְׂפָתָיו כְּאֵשׁ צָרָבֶת הָרָעָה כְּאֵשׁ שׂוֹרֶפֶת עַל שְׂפָתָיו, עַד שֶׁמּוֹצִיאָהּ בְּפִיו וְגוֹמְרָהּ:",2,0],[16,27,"כְּאֵשׁ צָרָבֶת. שׂוֹרֶפֶת, כְּמוֹ ״וְנִצְרְבוּ בָהּ כָּל פָּנִים״ (יחזקאל כא:ג):",3,0],[16,28,"וְנִרְגָּן מַפְרִיד אַלּוּף. וְעַל יְדֵי רִיגּוּנוֹ וְתַרְעוֹמְתּוֹ מַפְרִיד מִמֶּנּוּ אַלּוּפוֹ שֶׁל עוֹלָם (בראשית רבה כ:ב):",1,0],[16,30,"עוֹצֶה עֵינָיו. לְשׁוֹן קְרִיצָה, וְכֵן ״אִיעֲצָה עָלֶיךָ עֵינִי״ (תהילים לב:ח):",1,0],[16,30,"כִּלָּה רָעָה. כְּמוֹ ״כִּי כָלְתָה אֵלָיו הָרָעָה וְגוֹמֵר״ (אסתר ז:ז), וְגוֹרֵם לָבֹא רָעָה לָעוֹלָם:",2,0],[16,31,"בְּדֶרֶךְ צְדָקָה תִּמָּצֵא. עַל יְדֵי הַצְּדָקָה מַאֲרִיכִין יְמֵיהֶם:",1,0],[16,32,"וּמוֹשֵׁל בְּרוּחוֹ. כּוֹבֵשׁ אֶת יִצְרוֹ (אבות ד:א):",1,0],[16,33,"בַּחֵיק יוּטַל אֶת הַגּוֹרָל. בֵּינוֹ לְבֵין עַצְמוֹ אָדָם מֵטִיל גּוֹרָל:",1,0],[16,33,"וּמֵה׳ כָּל מִשְׁפָּטוֹ. לִבְרוֹר לְכָל אֶחָד וְאֶחָד חֶלְקוֹ:",2,0],[17,1,"טוֹב פַּת חֲרֵבָה וְשַׁלְוָה בָהּ. טוֹב הָיָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲרִיב בֵּיתוֹ וְעִירוֹ, וְהָיָה בְשַׁלְוָה מֵעֲבֵירוֹתֵיהֶן שֶׁל יִשְׂרָאֵל:",1,0],[17,1,"מִבַּיִת מָלֵא זִבְחֵי רִיב. שֶׁהָיוּ מַקְרִיבִין זִבְחֵי רִיב בְּבֵיתוֹ:",2,0],[17,2,"עֶבֶד מַשְׂכִּיל וְגוֹ׳. עַל שֶׁהִשְׂכִּיל נְבוּכַדְנֶצַּר לִפְסֹעַ שָׁלֹשׁ פְּסִיעוֹת לִכְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, עָלָה לִגְדֻלָּה וּמָשַׁל בְּיִשְׂרָאֵל, שֶׁהוֹבִישׁוּ מַעֲשֵׂיהֶם וְחָלַק נַחֲלָתָם לְעֵינֵיהֶם. דָּבָר אַחֵר: גֵּר צֶדֶק טוֹב מֵאֶזְרָח רָשָׁע, וְלֶעָתִיד לָבוֹא יְחַלֵּק שָׁלָל וְנַחֲלָה בְּתוֹךְ בְּנֵי יִשְׂרָאֵל, שֶׁנֶּאֱמַר ״וְהָיָה בַשֵּׁבֶט אֲשֶׁר גָּר הַגֵּר וְגוֹ׳״ (יחזקאל מז:כג):",1,0],[17,3,"מַצְרֵף לַכֶּסֶף. כְּלִי שֶׁצּוֹרְפִין בּוֹ כֶּסֶף וְעוֹשִׂין אוֹתוֹ מֵאֵפֶר מִקְלֶה עַל גַּבֵּי חֶרֶס, קָרוּי מַצְרֵף:",1,0],[17,3,"וְכוּר לַזָּהָב. כְּלִי שֶׁצּוֹרְפִין בּוֹ אֶת הַזָּהָב, כְּלִי שֶׁזּוֹקְקִין בּוֹ אֶת הַזָּהָב, כְּמוֹ קְדֵרָה שְׁבוּרָה, קְרוּיָה כּוּר:",2,0],[17,3,"מַצְרֵף לַכֶּסֶף וְכוּר לַזָּהָב. הַמַּצְרֵף עָשׂוּי לִצְרֹף כֶּסֶף לִמְלַאכְתּוֹ וְכֵן הַכּוּר לְזַקֵּק הַזָּהָב, אֲבָל הַלְּבָבוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹקְקָן וּבוֹחֲנָן וְיוֹדֵעַ מַחְשְׁבוֹתָן:",3,0],[17,4,"מֵרַע. רָשָׁע:",1,0],[17,4,"מַקְשִׁיב עַל שְׂפַת אָוֶן שֶׁקֶר. מְקַבֵּל לָשׁוֹן הָרָע וְעֵדֵי שֶׁקֶר:",2,0],[17,4,"מֵזִין. מַאֲזִין, מִי שֶׁהוּא מְשַׁקֵּר מַאֲזִין עַל לְשׁוֹן הַוֺּת:",3,0],[17,6,"עֲטֶרֶת זְקֵנִים. כְּשֶׁרוֹאִים בְּנֵי בְנֵיהֶם הוֹלְכִין בְּדֶרֶךְ טוֹבָה:",1,0],[17,6,"וְתִפְאֶרֶת בָּנִים אֲבוֹתָם. כְּשֶׁאֲבוֹתֵיהֶם צַדִּיקִים, הִיא תִּפְאֶרֶת הַבָּנִים:",2,0],[17,7,"שְׂפַת יֶתֶר. דִּבְרֵי גַּאֲוָה:",1,0],[17,7,"אַף כִּי לְנָדִיב. וְכָל שֶׁכֵּן שֶׁלֹּא נָאֶה שְׂפַת שֶׁקֶר לְנָדִיב:",2,0],[17,8,"אֶבֶן חֵן. כְּשֶׁהָאָדָם בָּא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְפַיְּסוֹ בִּדְבָרִים וְשָׁב לוֹ, אֶבֶן חֵן וּמַרְגָּלִיּוֹת הִיא בְּעֵינָיו:",1,0],[17,8,"אֶל כָּל אֲשֶׁר יִפְנֶה יַשְׂכִּיל. בְּכָל מַה שֶּׁיְּבַקֵּשׁ מִמֶּנּוּ מַצְלִיחוֹ:",2,0],[17,9,"מְכַסֶּה פֶּשַׁע מְבַקֵּשׁ אַהֲבָה. אִם יֶחֱטָא אִישׁ לְאִישׁ, וְזֶה מְכַסֶּה עָלָיו וְאֵינֶנּוּ מַזְכִּיר לוֹ חַטָּאתוֹ וְאֵינוֹ מַרְאֶה לוֹ פָּנִים זוֹעֲמוֹת, גּוֹרֵם לוֹ שֶׁיֹּאהַב אוֹתוֹ:",1,0],[17,9,"וְשׁוֹנֶה בְדָבָר. שֶׁנּוֹטֵר אֵיבָה וּמַזְכִּירוֹ: כָּךְ וְכָךְ עָשִׂיתָ לִי! מִיָּד:",2,0],[17,9,"מַפְרִיד אַלּוּף. אָז מַפְרִיד מִמֶּנּוּ אַלּוּפוֹ שֶׁל עוֹלָם שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִזְהִירוֹ ״לֹא תִקֹּם וְלֹא תִטֹּר״ (ויקרא יט:יח):",3,0],[17,10,"תֵּחַת גְּעָרָה בְמֵבִין. תַּחַת זוֹ טַעֲמוֹ לְמַעְלָה בַּתָּי״ו, מַה שֶּׁאֵין כֵּן בְּכָל הַמִּקְרָא, לְכָךְ אֲנִי אוֹמֵר שֶׁהִיא שֵׁם דָּבָר כְּמוֹ ״חִתַּת״ (בראשית לה:ה), וְכֵן פֵּרוּשׁוֹ: הַכְנָעַת גְּעָרָה נִכֶּרֶת בְּמֵבִין יוֹתֵר מִמֵּאָה מַכּוֹת שֶׁמַּכִּין אֶת הַכְּסִיל:",1,0],[17,11,"אַךְ מְרִי יְבַקֶּשׁ רָע. כְּלוֹמַר: מִי שֶׁכָּל דְּבָרָיו מְרִי וְסַרְבָנוּת הוּא יְבַקֵּשׁ רָע תָּמִיד:",1,0],[17,12,"פָּגוֹשׁ דֹּב שַׁכּוּל בְּאִישׁ. טוֹב לָאָדָם שֶׁיִּפְגַּע בּוֹ דֹּב מְשַׁכֵּל, וְאַל יִפְגַּע בּוֹ אֶחָד מִן הַכְּסִילִים הַמְּסִיתִים אוֹתוֹ לָסוּר מֵה׳ וּמִתּוֹרָתוֹ:",1,0],[17,14,"פּוֹטֵר מַיִם רֵאשִׁית מָדוֹן. הַמַּתְחִיל בִּמְרִיבָה הוּא כְּפוֹתֵחַ חוֹר בְּגִדְרֵי אַגְפֵי אַמַּת הַמַּיִם וְהַמַּיִם יוֹצְאִין בּוֹ, וְהַחוֹר הוֹלֵךְ וּמַרְחִיב. כֵּן הַמָּדוֹן הוֹלֵךְ וְגָדֵל תָּמִיד:",1,0],[17,14,"וְלִפְנֵי הִתְגַּלַּע. קוֹדֶם שֶׁתִּתְגַּלַּע חֶרְפָּתְךָ נְטוֹשׁ אֶת הָרִיב (סנהדרין ו:):",2,0],[17,16,"לָמָּה זֶּה מְחִיר בְּיַד כְּסִיל לִקְנוֹת חָכְמָה. לִלְמֹד תּוֹרָה:",1,0],[17,16,"וְלֶב אָיִן. וְאֵין בְּלִבּוֹ לְקַיְּמָהּ, וְאֵינוֹ לוֹמֵד תּוֹרָה אֶלָּא לִקְנוֹת שֵׁם:",2,0],[17,17,"בְּכָל עֵת אוֹהֵב הָרֵעַ. לְעוֹלָם הֱוֵי אוֹהֵב רֵעִים, לִקְנוֹת אוֹהֲבִים:",1,0],[17,17,"וְאָח לְצָרָה יִוָּלֵד. לְעֵת הַצָּרָה יִוָּלֵד לְךָ הָרֵעַ כְּאָח, לַעֲזֹר לְךָ וּלְהִשְׁתַּתֵּף בְּצָרָתְךָ:",2,0],[17,18,"אָדָם חֲסַר לֵב תּוֹקֵעַ כָּף. עֲרֵבוּת מָמוֹן. דָּבָר אַחֵר: תּוֹקֵעַ כַּף לָרְשָׁעִים כְּדֵי לָלֶכֶת בְּדַרְכֵיהֶם, וַהֲרֵי כְּבָר עֹרֵב עֲרֻבָּה לִפְנֵי רֵעֵהוּ. כְּבָר עָרַב לְהַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר מִצְווֹתָיו:",1,0],[17,19,"אוֹהֵב פֶּשַׁע. לִפְשׁוֹעַ בַּחֲבֵירוֹ:",1,0],[17,19,"אוֹהֵב מַצָּה. לְהִתְקוֹטֵט וְלָרִיב:",2,0],[17,19,"מַגְבִּיהַּ פִּתְחוֹ. מְדַבֵּר בְּגַאֲוָה, כְּמוֹ ״שְׁמֹר פִּתְחֵי פִיךָ״ (מיכה ז:ה):",3,0],[17,22,"לֵב שָׂמֵחַ יֵיטִיב גֵּהָה. כְּשֶׁהָאָדָם שָׂמֵחַ בְּחֶלְקוֹ, פָּנָיו מְאִירִין:",1,0],[17,23,"שֹׁחַד מֵחֵיק רָשָׁע יִקָּח. הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל דִּבְרֵי הַכְנָעָה וּפִיּוּס מֵחֵיק הָרְשָׁעִים, כְּלוֹמַר: בַּסֵּתֶר בֵּינוֹ לְבֵינָם:",1,0],[17,23,"לְהַטּוֹת אָרְחוֹת מִשְׁפָּט. לַהֲפֹךְ דִּינוֹ מֵרָעָה לְטוֹבָה:",2,0],[17,24,"אֶת פְּנֵי מֵבִין חָכְמָה. הַחָכְמָה לִפְנֵי מֵבִין הוּא:",1,0],[17,24,"וְעֵינֵי כְסִיל בִּקְצֵה אָרֶץ. לוֹמַר: אֵין הַחָכְמָה מְצוּיָה לְפָנַי כִּי רְחוֹקָה הִיא מִמֶּנִּי, אֵיךְ אוּכַל לִשְׁנוֹת סֵדֶר נְזִיקִין שֶׁהוּא שְׁלֹשִׁים פְּרָקִים, מַסֶּכֶת כֵּלִים – שְׁלֹשִׁים פְּרָקִים, מַסֶּכֶת שַׁבָּת – עֶשְׂרִים וְאַרְבָּעָה פְּרָקִים. אֲבָל לֶחָכָם הוּא דָּבָר קַל: הַיּוֹם שׁוֹנֶה שְׁנֵי פְרָקִים וּמָחָר שְׁנַיִם, וְאוֹמֵר: כָּךְ עָשׂוּ אוֹתָן שֶׁהָיוּ לְפָנַי מֵעוֹלָם:",2,0],[17,25,"כַּעַס לְאָבִיו בֵּן כְּסִיל. כְּגוֹן יָרָבְעָם כַּעַס הוּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא (מלכים א יב:כו-לג):",1,0],[17,25,"וּמֶמֶר לְיוֹלַדְתּוֹ. לִכְנֶסֶת יִשְׂרָאֵל, שֶׁהֶחֱטִיא אוֹתָם:",2,0],[17,26,"גַּם עֲנוֹשׁ לַצַּדִּיק לֹא טוֹב. לֹא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִמְחוֹת שֵׁם יִשְׂרָאֵל מֵעַל הָאָרֶץ, כִּי לֹא טוֹב בְּעֵינָיו לַעֲנוֹשׁ כֻּלָּם:",1,0],[17,26,"לְהַכּוֹת נְדִיבִים עַל יֹשֶׁר. לְהַכּוֹת הַטּוֹבִים שֶׁבָּהֶם שֶׁהָיוּ נְדִיבִים עֲלֵי יֹשֶׁר, שֶׁנֶּאֱמַר: ״וְהִשְׁאַרְתִּי בְיִשְׂרָאֵל שִׁבְעַת אֲלָפִים כָּל הַבִּרְכַּיִם אֲשֶׁר לֹא כָרְעוּ לַבַּעַל״ (מלכים א יט:יח):",2,0],[17,26,"נְדִיבִים עַל יֹשֶׁר. דֻּגְמַת הָאָמוּר בְּמָקוֹם אַחֵר ״וְנָדִיב נְדִיבוֹת יָעָץ וְהוּא עַל נְדִיבוֹת יָקוּם״ (ישעיהו לב:ח), נִמְצָא ״נָדִיב״ עַל ״נְדִיבוֹת״:",3,0],[17,27,"חוֹשֵׂךְ אֲמָרָיו. מִי שֶׁהוּא יוֹדֵעַ דַּעַת אֵינוֹ מַרְבֶּה בִּדְבָרִים:",1,0],[17,27,"יְקַר רוּחַ. מוֹנֵעַ דְּבָרִים אִישׁ תְּבוּנָה:",2,0],[18,1,"לְתַאֲוָה יְבַקֵּשׁ נִפְרָד. מִי שֶׁהוּא נִפְרָד מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא לִשְׁמֹר מִצְווֹתָיו, לְתַאֲוַת לִבּוֹ וְיִצְרוֹ הָרַע הוּא רוֹדֵף, וְסוֹף בְּכָל תּוּשִׁיָּה יִתְגַּלָּע. בֵּין חֲכָמִים תִּגָּלֶה חֶרְפָּתוֹ. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ (נזיר כג:) בְּלוֹט שֶׁנִּפְרַד מֵאַבְרָהָם עַל תַּאֲוַת לִבּוֹ, שֶׁנֶּאֱמַר ״וַיִּבְחַר לוֹ לוֹט אֵת כָּל כִּכַּר הַיַּרְדֵּן״ (בראשית יג:יא). כָּל הַמִּקְרָא הַזֶּה עַל שֵׁם נִיאוּף נֶאֱמַר, וְסוֹפוֹ נִתְגַּלָּה קְלוֹנוֹ בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת: ״לֹא יָבֹא עַמּוֹנִי וּמוֹאָבִי״ (דברים כג:ד):",1,0],[18,2,"כִּי אִם בְּהִתְגַּלּוֹת לִבּוֹ. כִּי אִם בְּגִלּוּי לִבּוֹ, הוּא חָפֵץ לְגַלּוֹת מַה שֶּׁבְּלִבּוֹ:",1,0],[18,3,"וְעִם קָלוֹן. תָּבוֹא חֶרְפָּה – מִי שֶׁבּוֹחֵר בְּקָלוֹן וְנִאוּף, חֶרְפָּה הִיא לוֹ:",1,0],[18,4,"דִּבְרֵי פִי אִישׁ. כָּל אִישׁ שֶׁבַּמִּקְרָא לְשׁוֹן גִּבּוֹר גָּדוֹל בִּגְבוּרָה הוּא:",1,0],[18,4,"מְקוֹר חָכְמָה. כְּנַחַל נוֹבֵעַ וּכְמַיִם עֲמֻקִּים:",2,0],[18,5,"שְׂאֵת פְּנֵי רָשָׁע לֹא טוֹב. כַּאֲשֶׁר פֵּרְשׁוּ רַבּוֹתֵינוּ (יומא פז.): לֹא טוֹב לָהֶם לָרְשָׁעִים שֶׁנּוֹשְׂאִים לָהֶם פָּנִים בָּעוֹלָם הַזֶּה וְנִפְרָעִין מֵהֶן לָעוֹלָם הַבָּא:",1,0],[18,5,"טוֹב וְגוֹ׳. טוֹב לָהֶם לַצַּדִּיקִים שֶׁמַּכְרִיעִין לָהֶם כַּף מֹאזְנַיִם לְחַיְּבָם בָּעוֹלָם הַזֶּה וְנִפְרָעִין מֵהֶן בְּחַיֵּיהֶן לָעוֹלָם הַבָּא. וּלְפִי פְּשׁוּטוֹ – כְּמַשְׁמָעוֹ:",2,0],[18,6,"שִׂפְתֵי כְסִיל יָבֹאוּ בְרִיב. כָּל דְּבָרָיו בָּאִים בִּלְשׁוֹן תִּגְרָה:",1,0],[18,6,"וּפִיו לְמַהֲלֻמוֹת יִקְרָא. קוֹרֵא לְיִסּוּרִין לַהֲבִיאָם עָלָיו:",2,0],[18,8,"דִּבְרֵי נִרְגָּן כְּמִתְלַהֲמִים. מַהֲלוּמוֹת:",1,0],[18,9,"גַּם מִתְרַפֶּה בִמְלַאכְתּוֹ. פּוֹרֵשׁ מִן הַתּוֹרָה וְהוּא תַּלְמִיד חָכָם:",1,0],[18,9,"לְבַעַל מַשְׁחִית. לַשָּׂטָן:",2,0],[18,10,"מִגְדַּל עֹז שֵׁם ה׳ בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. וְהוּא מִתְחַזֵּק:",1,0],[18,11,"וּכְחוֹמָה נִשְׂגָּבָה. עָשְׁרוֹ לוֹ בְּחַדְרֵי מַשְׂכִּיתוֹ. מִפְּנֵי שֶׁהַבַּיִת נִרְצָף בְּרִצְפַּת אֲבָנִים הַסּוֹכְכִים עַל הָאָרֶץ, קָרוּי אֶבֶן מַשְׂכִּית:",1,0],[18,14,"רוּחַ אִישׁ. רוּחַ גֶּבֶר שֶׁהוּא אִישׁ גִּבּוֹר וְאֵינוֹ נוֹתֵן דְּאָגָה בְּלִבּוֹ וּמְקַבֵּל כָּל הַבָּא עָלָיו בְּשִׂמְחָה וּבְחִבָּה:",1,0],[18,14,"יְכַלְכֵּל מַחֲלֵהוּ. אֵין כֹּחוֹ סָר מֵעָלָיו:",2,0],[18,16,"מַתָּן אָדָם יַרְחִיב. כִּפְשׁוּטוֹ, וּמִדְרָשׁוֹ (במדבר רבה יג:יז): בְּנוֹתְנֵי צְדָקָה מְדַבֵּר, שֶׁמַּרְחִיב לוֹ חֶלְקוֹ לֶעָתִיד לָבוֹא, וְגַם בְּחַיָּיו לִפְנֵי גְדוֹלִים יַנְחֶנּוּ, וְאוֹמְרִים עָלָיו שֶׁהוּא חָשׁוּב:",1,0],[18,18,"וּבֵין עֲצוּמִים יַפְרִיד. אֵלּוּ בַּעֲלֵי דִינִין, כְּמוֹ ״הַגִּישׁוּ עֲצוּמוֹתֵיהֶם״ (ישעיה מא:כא). וּבַמִּשְׁנָה (סנהדרין לא:): שְׁנַיִם שֶׁנִּתְעַצְּמוּ בַדִּין. עַל שֵׁם שֶׁמְּרִיבוֹתָם עֲצוּמוֹת קְרוּיִים עֲצוּמִים, אוֹ לְשׁוֹן ׳חוֹזֶק׳ אוֹ לְשׁוֹן ׳אוֹטֶם׳, כְּמוֹ ״עֹצֵם עֵינָיו״ (ישעיה לג:טו):",1,0],[18,19,"אָח נִפְשָׁע מִקִּרְיַת עֹז. יֵשׁ אָח נִפְשָׁע מֵאָחִיו וּמְאַבֵּד בְּמִרְדּוֹ קִרְיַת עֹז, כְּגוֹן לוֹט בְּאַבְרָהָם (בראשית יג), עֵשָׂו בְּיַעֲקֹב (בראשית כז:מא-מג):",1,0],[18,19,"וּמִדְיָנִים כִּבְרִיחַ אַרְמוֹן. וּמְרִיבָה שֶׁבֵּינֵיהֶם מַפְרִידָתָם לְעוֹלָם כִּבְרִיחַ זֶה שֶׁנּוֹעֲלִים בּוֹ שַׁעֲרֵי אַרְמוֹן, שֶׁלֹּא יִכָּנְסוּ בּוֹ (נזיר כג,א-ב):",2,0],[18,21,"וְאֹהֲבֶיהָ יֹאכַל פִּרְיָהּ. אוֹהֵב אֶת לְשׁוֹנוֹ וּמַרְגִּיל לַתּוֹרָה אוֹכֵל שְׂכָרָהּ בָּעוֹלָם הַזֶּה (תנחומא, מצרע ב):",1,0],[18,22,"מָצָא אִשָּׁה מָצָא טוֹב. מָצָא תּוֹרָה, וּכְמַשְׁמָעוֹ: אִשָּׁה טוֹבָה:",1,0],[18,22,"וַיָּפֶק רָצוֹן. וְיוֹצִיא; זֶה פְּשׁוּטוֹ. דָּבָר אַחֵר: אָדָם שֶׁמָּצָא אִשָּׁה וּמָצָא טוֹב וַיָּפֶק רְצוֹנוֹ, אוֹתוֹ הָאִישׁ מוֹצִיא רָצוֹן מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי יוֹסֵף קָרָא:",2,0],[18,23,"תַּחֲנוּנִים יְדַבֶּר רָשׁ. דֶּרֶךְ זֶה בְּכָךְ וְדֶרֶךְ זֶה בְּכָךְ; לִמֶּדְךָ דֶּרֶךְ אֶרֶץ, שֶׁאַף עַל פִּי שֶׁעָשִׁיר יַעֲנֶה עַזּוֹת, הָרָשׁ יְדַבֵּר תַּחֲנוּנִים. וְכֵן הָעִנְיָן הָרַב לַתַּלְמִיד:",1,0],[18,24,"אִישׁ רֵעִים לְהִתְרֹעֵעַ. אָדָם שֶׁקּוֹנֶה לוֹ רֵעִים עוֹד יָבוֹא יוֹם שֶׁיִּצְטָרֵךְ לָהֶם וִיקָרְבֵהוּ. וְאִם תֹּאמַר: מַה בְּכָךְ – יֵשׁ אוֹהֵב דָּבֵק מֵאָח, שֶׁיְּקָרְבֵהוּ יוֹתֵר מִקְּרוֹבָיו וְאֶחָיו:",1,0],[19,2,"גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב. אֵין טוֹב לָאָדָם שֶׁהוּא בְּלֹא תּוֹרָה:",1,0],[19,2,"וְאָץ בְּרַגְלַיִם חוֹטֵא. הַחוֹטֵא רוֹפֵס וְדָשׁ הָעֲווֹנוֹת בַּעֲקֵבָיו, וְאוֹמֵר: קַל הוּא זֶה, אֶעֱבוֹר עָלָיו. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (עירובין ק:): גַּם בְּלֹא דַעַת, בְּכוֹפֶה אֶת אִשְׁתּוֹ לְתַשְׁמִישׁ הַמִּטָּה בְּעַל כָּרְחָהּ:",2,0],[19,2,"וְאָץ בְּרַגְלַיִם חוֹטֵא. זֶה הַבּוֹעֵל וְשׁוֹנֶה. דָּבָר אַחֵר: זֶה הַמְהַלֵּךְ עַל גַּבֵּי עֲשָׂבִים בְּשַׁבָּת (שבת צה.):",3,0],[19,3,"אִוֶּלֶת אָדָם תְּסַלֵּף דַּרְכּוֹ. בַּעֲוֹנוֹ בָּא לוֹ הָרָע, כִּי בְּאִוַּלְתּוֹ תְּסַלֵּף דַּרְכּוֹ וְעָבַר עֲבֵירוֹת וְנִפְרָעִין מִמֶּנּוּ, וּבְבוֹא לוֹ הַצָּרָה זוֹעֵף לִבּוֹ עַל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְמַהֵר אַחַר מִדַּת הַדִּין, כְּגוֹן אֲחֵי יוֹסֵף שֶׁאָמְרוּ ״מַה זֹּאת עָשָׂה אֱלֹהִים לָנוּ״ (בראשית מב:כח):",1,0],[19,4,"הוֹן יוֹסִיף רֵעִים רַבִּים. אוֹהֲבִים רַבִּים. וְיֵשׁ לְפוֹתְרוֹ בְּמִי שֶׁלָּמַד תּוֹרָה:",1,0],[19,6,"רַבִּים יְחַלּוּ פְנֵי נָדִיב וְכָל הָרֵעַ. הַכֹּל נַעֲשִׂים רֵעִים לְאִישׁ מַתָּן. יֵשׁ לְפוֹתְרוֹ בְּנוֹתְנֵי צְדָקָה וְיֵשׁ לְפוֹתְרוֹ בְּמַרְבִּיצֵי תוֹרָה:",1,0],[19,7,"כָּל אֲחֵי רָשׁ. קְרוֹבָיו:",1,0],[19,7,"אַף כִּי מֵרֵעֵהוּ רָחֲקוּ. וְכָל שֶׁכֵּן מֵרֵעָיו וְשׁוֹשְׁבִינָיו וְאוֹהֲבָיו:",2,0],[19,7,"מְרַדֵּף אֲמָרִים. לֹא הֵמָּה אוֹמֵר: פְּלוֹנִי וּפְלוֹנִי קְרוֹבַי, וּפְלוֹנִי וּפְלוֹנִי מֵרֵעַי, וְהַכֹּל דִּבְרֵי הֶבֶל. וְיֵשׁ לְפוֹתְרוֹ בְּמִי שֶׁהוּא רָשׁ בַּתּוֹרָה וּבְמַעֲשִׂים טוֹבִים:",3,0],[19,7,"מְרַדֵּף אֲמָרִים לֹא הֵמָּה. מְחַזֵּר לְהוֹרוֹת הֲלָכָה וְלָאו בְּיָדוֹ, וְהַמִּדְרָשׁ פּוֹתְרוֹ בְּיוֹסֵף שֶׁהָיָה מוֹצִיא עַל אֶחָיו דִּבָּה, וְאָמַר לְאָבִיו שֶׁהֵן חֲשׁוּדִין עַל אֵבֶר מִן הַחַי, לְכָךְ שְׂנֵאוּהוּ וְנִקְרָא רָשׁ לְפִי שֶׁהָיָה מוֹצִיא דִּבַּת שֶׁקֶר עֲלֵיהֶם. וּמְחַזֵּר אַחַר אֲמָרִים לֹא הֵמָּה. לוֹ קְרִינָן וּמְרַדֵּף אֲמָרִים לַהֲנָאָתוֹ, וּלְעִנְיַן יוֹסֵף לוֹ הֵמָּה, כִּי עָלָיו חָזְרוּ דִּבָּתוֹ הוּא הָיָה אוֹמֵר שֶׁהָיוּ אוֹכְלִים אֵבֶר מִן הַחַי וְהַכָּתוּב מֵעִיד עֲלֵיהֶם אֲפִלּוּ בִּשְׁעַת הַקַּלְקָלָה הָיוּ שׁוֹחֲטִין שְׂעִיר עִזִּים שֶׁנֶּאֱמַר ״וַיִּשְׁחֲטוּ שְׂעִיר עִזִּים״ (בראשית לז:לא). הוּא אָמַר שֶׁהָיוּ מְזַלְזְלִין בִּבְנֵי הַשְּׁפָחוֹת לְכָךְ ״לְעֶבֶד נִמְכַּר יוֹסֵף״ (תהלים קה:יז), הוּא אָמַר שֶׁהָיוּ נוֹתְנִים עֵינֵיהֶם בִּבְנוֹת הָאָרֶץ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא חַיֶּיךָ שֶׁאֲנִי מְגָרֶה בְּךָ אֶת הַדֹּב לְכָךְ ״וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו וְגוֹ׳״ (בראשית לט:ז) (בראשית רבה פד:ז):",4,0],[19,10,"לֹא נָאוֶה לִכְסִיל תַּעֲנוּג אַף כִּי לְעֶבֶד. קַל וָחֹמֶר הוּא, שֶׁאֵין נָאֶה שֶׁעֶבֶד יִמְשֹׁל בִּנְדִיבִים:",1,0],[19,11,"שֵׂכֶל אָדָם הֶאֱרִיךְ אַפּוֹ. כְּמוֹ לְהַאֲרִיךְ, אִם עָשָׂה כֵּן שֵׂכֶל הוּא לוֹ:",1,0],[19,11,"וְתִפְאַרְתּוֹ. הוּא שֶׁיַּעֲבֹר עַל מִדּוֹתָיו:",2,0],[19,12,"נַהַם כַּכְּפִיר זַעַף מֶלֶךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[19,13,"וְדֶלֶף טוֹרֵד. דֶּלֶף גְּשָׁמִים הַיּוֹרֵד בַּבַּיִת וּמַטְרִיחַ וְטוֹרֵד לְיוֹשְׁבֵי הַבַּיִת, כָּךְ מִדְיְנֵי אִשָּׁה רָעָה:",1,0],[19,15,"עַצְלָה תַּפִּיל תַּרְדֵּמָה. הָעַצְלוּת מְבִיאָה לִידֵי שֵׁינָה, זוֹ הִיא הַמְּלִיצָה. אֲבָל הַמָּשָׁל – עַל הַמִּתְעַצֵּל בְּתַלְמוּדוֹ; סוֹף שֶׁשּׁוֹאֲלִין דְּבַר חָכְמָה מִמֶּנּוּ וְהוּא נִרְדָּם:",1,0],[19,15,"וְנֶפֶשׁ רְמִיָּה תִרְעָב. סוֹף שֶׁיְּהֵא עָנִי; וְכֵן הָרַמַּאי בְּתַלְמוּדוֹ, לַעֲשׂוֹת תּוֹרָתוֹ חֲבִילוֹת, סוֹף שֶׁהוּא יִשְׁכַּח:",2,0],[19,16,"שׁוֹמֵר מִצְוָה שׁוֹמֵר נַפְשׁוֹ בּוֹזֵה דְרָכָיו יָמוּת. שֶׁאֵינוֹ נוֹתֵן לִבּוֹ לְשָׁקְלָן:",1,0],[19,17,"מַלְוֵה ה׳ חוֹנֵן דָּל וּגְמוּלוֹ יְשַׁלֶּם לוֹ. כְּשֶׁיֶּחֱלֶה וְיִטֶּה לָמוּת, צִדְקָתוֹ מְלִיצָה עָלָיו לִפְנֵי מִדַּת הַדִּין, לוֹמַר: הֶעָנִי הָיְתָה נַפְשׁוֹ מְפַרְכֶּסֶת לָצֵאת בָּרָעָב וְזֶה פִּרְנְסָהּ וְהֶחֱזִירָהּ לְגוּפָהּ, אַף אֲנִי אַחֲזִיר לוֹ נַפְשׁוֹ:",1,0],[19,18,"יַסֵּר בִּנְךָ כִּי יֵשׁ תִּקְוָה וְאֶל הֲמִיתוֹ אַל תִּשָּׂא נַפְשֶׁךָ. אַל תַּכֵּהוּ מַכַּת מָוֶת:",1,0],[19,19,"גְּדׇל חֵמָה נֹשֵׂא עֹנֶשׁ וְגוֹ׳. אִם תַּעֲבִיר עַל חֲמָתְךָ וְתַצִּיל אֶת שׂוֹנַאֲךָ אִם רָאִיתָ רָעָה בָּאָה לוֹ, עוֹד תּוֹסִיף יָמִים וְטוֹבָה:",1,0],[19,22,"תַּאֲוַת אָדָם חַסְדּוֹ. עִקָּר שֶׁהַבְּרִיּוֹת מִתְאַוִּים לָאָדָם בַּעֲבוּר חַסְדּוֹ:",1,0],[19,22,"וְטוֹב רָשׁ מֵאִישׁ כָּזָב. וְאִם אִישׁ כָּזָב הוּא וּמַבְטִיחַ וְאֵינוֹ עוֹשֶׂה, טוֹב אִישׁ רָשׁ מִמֶּנּוּ:",2,0],[19,23,"וְשָׂבֵעַ יָלִין. הַיָּרֵא אֶת הַשֵּׁם, שֶׁלֹּא יִפָּקֶד בְּשׁוּם רָעָה:",1,0],[19,24,"טָמַן עָצֵל יָדוֹ בַּצַּלָּחַת. בְּיוֹרָה חַמָּה, שֶׁכְּשֶׁיַּעַבְרוּהָ מִן הָאוּר וּפִנּוּהָ רֵיקָנִית, מְחַמֵּם יָדוֹ בְּתוֹכָהּ. וְדוֹמֶה לוֹ ״בִּשְּׁלוּ בַּסִּירוֹת וּבַדְּוָדִים וּבַצֵּלָחוֹת״ (דברי הימים ב לה:יג). וּמִשּׁוּם רַבֵּינוּ יִצְחָק הַלֵּוִי שָׁמַעְתִּי: בַּצַּלָּחַת. מִלְּשׁוֹן תַּרְגּוּם ״וַיְבַקַּע״ (בראשית כב:ג): ״וְצָלַח״, בִּשְׁעַת הַצִּנָּה וְהַגְּלִיד, עַל שֵׁם שֶׁהַקּוֹר וְהַגְּלִיד מְבַקְּעִין וְצוֹלְחִים הַיָּדַיִם. וַאֲנִי שָׁמַעְתִּי: בַּצַּלָּחַת. קֶרַע הֶחָלוּק, שֶׁקּוֹרִין פאנדאדור״י בְּלַעַ״ז, כְּלוֹמַר: טוֹמְנָהּ בְּחֵיקוֹ (סא״א):",1,0],[19,25,"לֵץ תַּכֶּה וּפֶתִי יַעְרִם. עַל מַכּוֹת פַּרְעֹה וּמִלְחֶמֶת עֲמָלֵק הֶחְכִּים יִתְרוֹ וְנִתְגַּיֵּר (תנחומא, יתרו ג):",1,0],[19,26,"מְשַׁדֶּד אָב יַבְרִיחַ אֵם. מַבְרִיחַ אֵם:",1,0],[19,26,"בֵּן מֵבִישׁ וּמַחְפִּיר. דְּרָכָיו. עַל יְדֵי שֶׁרָאֲתָה שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית מְשַׂחֵק לַעֲבוֹדַת גִּלּוּלִים וְגִלּוּי עֲרָיוֹת, גָּרַם זֶה שֶׁנִּשְׁתַּלְּחָה אִמּוֹ, ״וַיֵּרַע הַדָּבָר מְאֹד בְּעֵינֵי אַבְרָהָם״ (בראשית כא:יא):",2,0],[19,27,"חֲדַל בְּנִי לִשְׁמֹעַ וְגוֹ׳. מִקְרָא קָצָר הוּא וְזֶהוּ פֵּרוּשׁוֹ: חֲדַל בְּנִי לִשְׁגּוֹת מֵאִמְרֵי דָעַת בִּשְׁבִיל לִשְׁמֹעַ מוּסָר:",1,0],[19,27,"חֲדַל לִשְׁגּוֹת כְּמוֹ מִלִּשְׁגּוֹת, וְכֵן ״וְחָדַל לַעֲשׂוֹת הַפֶּסַח״ (במדבר ט:יג), וְכֵן ״כִּי חָדַל לִסְפֹּר״ (בראשית מא:מט):",2,0],[19,28,"עֵד בְּלִיַּעַל יָלִיץ מִשְׁפָּט. יָעִיד לְאָדָם מְלִיצַת מִשְׁפְּטֵי יִסּוּרִין וּמִיתָה:",1,0],[19,28,"וּפִי רְשָׁעִים יְבַלַּע אָוֶן. הָאָוֶן יִבְלָעֵהוּ:",2,0],[19,29,"נָכוֹנוּ לַלֵּצִים. הַקָּדוֹשׁ בָּרוּךְ הוּא זִמֵּן לוֹ שְׁפָטִים שֶׁל צָרַעַת לָזֶה הַלֵּץ הַמְסַפֵּר בְּלָשׁוֹן הָרָע (במדבר רבה יג:ד):",1,0],[20,2,"נַהַם כַּכְּפִיר אֵימַת מֶלֶךְ מִתְעַבְּרוֹ. מְכַעֲסוֹ:",1,0],[20,3,"כָּבוֹד לָאִישׁ שֶׁבֶת מֵרִיב. לָנוּחַ מִמְּרִיבָה:",1,0],[20,3,"וְכָל אֱוִיל. שֶׁאֵינוֹ שָׁבַת מֵרִיב, תִּגָּלֶה קְלוֹנוֹ:",2,0],[20,4,"מֵחֹרֶף עָצֵל לֹא יַחֲרֹשׁ. מִפְּנֵי הַצִּנָּה יוֹשֵׁב הֶעָצֵל וְאֵינוֹ עוֹשֶׂה מְלָאכָה וְאֵינוֹ עוֹסֵק בַּתּוֹרָה:",1,0],[20,5,"מַיִם עֲמֻקִּים עֵצָה בְלֶב אִישׁ. הֲלָכָה בְּלֵב חָכָם סְתוּמָה:",1,0],[20,5,"וְאִישׁ תְּבוּנָה יִדְלֶנָּה. וְתַלְמִיד נָבוֹן בָּא וְדָלָה אוֹתָהּ מִמֵּעָיו:",2,0],[20,6,"רָב אָדָם יִקְרָא אִישׁ חַסְדּוֹ. הַרְבֵּה יֵשׁ בְּנֵי אָדָם הַבּוֹטְחִים אֶל אוֹהֲבֵיהֶם הַמַּבְטִיחִים אוֹתָם חֶסֶד וְקוֹרְאִים לָהֶם בְּעֵת דָּחְקָם:",1,0],[20,6,"אִישׁ חַסְדּוֹ. הַמַּבְטִיחַ לוֹ לַעֲשׂוֹת חֶסֶד:",2,0],[20,6,"וְאִישׁ אֱמוּנִים מִי יִמְצָא. הַמַּבְטִיחַ וְעוֹשֶׂה:",3,0],[20,8,"מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא דִין. כְּפִשׁוּטוֹ, אוֹ יֵשׁ לְפָרְשׁוֹ כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיֵשׁ לְפָרְשׁוֹ כְּנֶגֶד שׁוֹפְטֵי אֱמֶת:",1,0],[20,12,"אֹזֶן שֹׁמַעַת וְעַיִן רֹאָה וְגוֹ׳. כְּלוֹמַר: מַעֲשֵׂה יָדָיו הֵם, וְהוּא חָפֵץ בְּאֹזֶן שׁוֹמַעַת מוּסָר וְעַיִן הָרוֹאָה אֶת הַנּוֹלָד:",1,0],[20,13,"אַל תֶּאֱהַב שֵׁנָה פֶּן תִּוָּרֵשׁ. כִּי תֵעָשֶׂה רָשׁ:",1,0],[20,14,"רַע רַע יֹאמַר הַקּוֹנֶה. הַקּוֹנֶה תּוֹרָה עַל יְדֵי הַדְּחָק וְיִסּוּרֵי רְעָבוֹן, אוֹמֵר: אוֹי לִי עַל רָעָה זֹאת וְהַצָּרָה הַזֹּאת. וּכְשֶׁהוֹלֵךְ לוֹ מָלֵא חָכְמָה אָז יִתְהַלָּל עַל הַצַּעַר שֶׁנִּצְטַעֵר:",1,0],[20,14,"וְאֹזֵל לוֹ. וְהוֹלֵךְ לוֹ:",2,0],[20,17,"עָרֵב לָאִישׁ לֶחֶם שָׁקֶר. נִיאוּף אֵשֶׁת אִישׁ:",1,0],[20,17,"וְאַחַר יִמָּלֵא פִיהוּ חָצָץ. אֲבָנִים דַּקּוֹת, וְכֵן ״וַיַּגְרֵס בֶּחָצָץ״ (איכה ג:טז):",2,0],[20,18,"מַחֲשָׁבוֹת בְּעֵצָה תִכּוֹן וּבְתַחְבֻּלוֹת עֲשֵׂה מִלְחָמָה. אִם בָּאתָ לְהִלָּחֵם כְּנֶגֶד הַשָּׂטָן, בֹּא בְּתַחְבּוּלוֹת תְּשׁוּבָה וּתְפִלָּה וְתַעֲנִית:",1,0],[20,19,"גּוֹלֶה סוֹד הוֹלֵךְ רָכִיל וּלְפֹתֶה שְׂפָתָיו. הַמְדַבֵּר חֲלָקוֹת לְפַתּוֹתְךָ וּלְהַסִּיתְךָ:",1,0],[20,20,"מְקַלֵּל אָבִיו וְאִמּוֹ יִדְעַךְ נֵרוֹ בֶּאֱשׁוּן חֹשֶׁךְ. בְּהַנְשִׁיף וּבְהַשְׁחִיר הַחֹשֶׁךְ, כְּלוֹמַר: בְּבֹא הָרָעָה:",1,0],[20,21,"נַחֲלָה מְבֹהֶלֶת בָּרִאשׁוֹנָה. שֶׁנִּבְהַל לְמַהֵר וְלִטּוֹל תְּחִלָּה, כְּגוֹן בְּנֵי גָד וּבְנֵי רְאוּבֵן שֶׁמִּהֲרוּ לִטּוֹל חֶלְקָם בְּעֵבֶר הַיַּרְדֵּן וְדִבְּרוּ בְּבֶהָלָה, שֶׁנֶּאֱמַר ״גִּדְרֹת צֹאן נִבְנֶה לְמִקְנֵנוּ פֹּה וְעָרִים לְטַפֵּנוּ״ (במדבר לב:טז) – עָשׂוּ אֶת הָעִקָּר טָפֵל, שֶׁהִקְדִּימוּ צֹאנָם לְטַפָּם (תנחומא, מטות ז):",1,0],[20,21,"וְאַחֲרִיתָהּ לֹא תְבֹרָךְ. שֶׁגָּלוּ כַּמָּה שָׁנִים קֹדֶם שְׁאָר הַשְּׁבָטִים, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסֵדֶר עוֹלָם (סדר עולם רבה כב) וּבְמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, מסעי י); ״בִּשְׁנַת שְׁתַּיִם לְאָחָז וַיָּעַר ה׳ אֶת רוּחַ מֶלֶךְ אַשּׁוּר וְגוֹ׳״ (דברי הימים א ה:כו), וּשְׁאָר שְׁבָטִים גָּלוּ בִּשְׁנַת שֵׁשׁ לְחִזְקִיָּהוּ הִיא הַתְּשִׁיעִית לְהוֹשֵׁעַ בֶּן אֵלָה (מלכים ב יז:א-ו):",2,0],[20,25,"מוֹקֵשׁ אָדָם יָלַע קֹדֶשׁ. כְּשֶׁאָדָם נִכְשָׁל וְנוֹקֵשׁ בַּעֲבֵירוֹת, מְקַלְקֵל אֶת קְדֻשָּׁתוֹ; כְּמוֹ ״וְשָׁתוּ וְלָעוּ״ (עובדיה א:טז):",1,0],[20,25,"וְאַחַר נְדָרִים לְבַקֵּר. צָרִיךְ אָדָם לַחֲזֹר אַחַר קָרְבָּנוֹת, לִנְדֹּר וּלְהָבִיא וּלְבַקֵּשׁ עַל נַפְשׁוֹ:",2,0],[20,26,"מְזָרֶה רְשָׁעִים. פַּרְעֹה וְחֵילוֹ (שמות יד:כח):",1,0],[20,26,"מֶלֶךְ חָכָם. הַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[20,26,"וַיָּשֶׁב עֲלֵיהֶם אוֹפָן. גַּלְגַּל מִדָּתָם הֵשִׁיב עֲלֵיהֶם, ״וַיְנַהֲגֵהוּ בִּכְבֵדֻת״ (שמות יד:כה) כְּנֶגֶד ״וְהַכְבֵּד אֶת לִבּוֹ״ (שמות ח:יא):",3,0],[20,27,"נֵר ה׳ נִשְׁמַת אָדָם. הַנְּשָׁמָה שֶׁבְּקִרְבּוֹ מְעִידָה עָלָיו בַּדִּין (פסיקתא רבתי ח):",1,0],[20,29,"תִּפְאֶרֶת בַּחוּרִים כֹּחָם. כְּמוֹ שֶׁתִּפְאֶרֶת בַּחוּרִים כֹּחָם, כֵּן הַדְרַת זְקֵנִים שֵׂיבָה:",1,0],[20,30,"חַבֻּרוֹת פֶּצַע תַּמְרוּק בְּרָע. דָּרְשׁוּ רַבּוֹתֵינוּ (ילקוט שמעוני משלי תתקנט): הַמְמָרֵק עַצְמוֹ לִדְבַר עֲבֵירָה, סוֹף בָּא לִידֵי פְּצָעִים וְחַבּוּרוֹת:",1,0],[20,30,"וּמַכּוֹת חַדְרֵי בָטֶן. זֶה הַהִדְרוֹקָן (בבא מציעא קז:):",2,0],[21,2,"כָּל דֶּרֶךְ אִישׁ יָשָׁר בְּעֵינָיו וְתוֹכֵן. וּמוֹנֶה:",1,0],[21,4,"רוּם עֵינַיִם. גַּסּוּת הָרוּחַ:",1,0],[21,4,"וּרְחַב לֵב. חָפֵץ לְמַלֹּאות תַּאֲוַת לִבּוֹ, הוּא נִיר שֶׁל רְשָׁעִים – חֲרִישׁוּתָם וּמַחְשְׁבוֹתָם הוּא חַטָּאתָם:",2,0],[21,5,"מַחְשְׁבוֹת חָרוּץ. אָדָם יָשָׁר הַמִּתְהַלֵּךְ בֶּאֱמֶת וּבְמִשְׁפָּט חָרוּץ:",1,0],[21,5,"אַךְ לְמוֹתָר. לְהַצְלָחָה וּלְרֶוַח בָּאוֹת:",2,0],[21,5,"וְכָל אָץ. דּוֹחֵק אֶת הַשָּׁעָה:",3,0],[21,6,"פֹּעַל אוֹצָרוֹת. לְהַרְבּוֹת הוֹן. בִּלְשׁוֹן שָׁקֶר:",1,0],[21,6,"הֶבֶל נִדָּף וְגוֹ׳. מוֹקְשֵׁי (  מְבַקְּשֵׁי) מָוֶת הֵם לוֹ:",2,0],[21,7,"יְגוֹרֵם. יָגוּר אוֹתָם:",1,0],[21,8,"הֲפַכְפַּךְ דֶּרֶךְ אִישׁ וָזָר. אִישׁ וְהוּא זָר, סָר מִן הַמִּצְוָה, דַּרְכּוֹ הֲפַכְפַּךְ:",1,0],[21,9,"וּבֵית חָבֶר. שֶׁנִּכְנָס לְבֵית חֲבֵירוֹ לְדַבֵּר עִם אִשְׁתּוֹ. וּמִדְרַשׁ אַגָּדָה (אבות דרבי נתן לד,ו; סנהדרין קג:): נִיבָּא שֶׁסּוֹף הַשְּׁכִינָה לְהִסְתַּלֵּק מֵעַל יִשְׂרָאֵל שֶׁהֵם כְּאֵשֶׁת מִדְיָנִים:",1,0],[21,9,"וּבֵית חָבֶר. בַּיִת שֶׁמְּחַבְּרִים בּוֹ רֵעִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא, כְּגוֹן צֶלֶם שֶׁהֶעֱמִיד מְנַשֶּׁה בְּהֵיכַל ה׳ (מלכים ב כא:ז):",2,0],[21,11,"בַּעֲנׇשׁ לֵץ יֶחְכַּם פֶּתִי. עַל יְדֵי יִסּוּרֵי הַלֵּצִים הַפְּתָאִים מִתְחַכְּמִים וְשָׁבִים בִּתְשׁוּבָה:",1,0],[21,12,"מַשְׂכִּיל צַדִּיק. צַדִּיקוֹ שֶׁל עוֹלָם, הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, נוֹתֵן לֵב לְהַכְרִית בֵּית רָשָׁע, כְּגוֹן זֵכֶר עֲמָלֵק (שמות יז:יד):",1,0],[21,14,"מַתָּן בַּסֵּתֶר. צְדָקָה:",1,0],[21,14,"וְשֹׁחַד בַּחֵק. אַף זוֹ צְדָקָה. יִכְפֶּה אָף, יִכְפֶּה חֵמָה עַזָּה:",2,0],[21,15,"שִׂמְחָה לַצַּדִּיק עֲשׂוֹת מִשְׁפָּט. שִׂמְחָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת דִּין בַּצַּדִּיקִים כְּדֵי לְזַכּוֹתָם לְחַיֵּי הָעוֹלָם הַבָּא, וְשִׂמְחָה לַצַּדִּיק שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵבִיא יִסּוּרִין עֲלֵיהֶם כְּדֵי שֶׁיִּזְכּוּ לָעוֹלָם הַבָּא. כָּךְ נִדְרַשׁ בְּמִדְרַשׁ תְּהִלִּים:",1,0],[21,15,"וּמְחִתָּה. הִיא לְפֹעֲלֵי אָוֶן, לְפִי שֶׁאֵין נוֹתְנִין לֵב לָשׁוּב וְאֵין הַיִּסּוּרִין מוֹעִילִין לָהֶן, וּמִצְטַעֲרִין וְלֹא לְהוֹעִיל:",2,0],[21,16,"אָדָם תּוֹעֶה מִדֶּרֶךְ הַשְׂכֵּל. פּוֹרֵשׁ מִן הַתּוֹרָה:",1,0],[21,16,"בִּקְהַל רְפָאִים. בַּעֲדַת גֵּיהִנֹּם (בבא בתרא עט.):",2,0],[21,17,"אִישׁ מַחְסוֹר. מִי שֶׁאוֹהֵב שִׂמְחַת מִשְׁתֶּה תָּמִיד:",1,0],[21,18,"כֹּפֶר לַצַּדִּיק רָשָׁע וְתַחַת יְשָׁרִים בּוֹגֵד. צַדִּיק נֶחְלָץ וְרָשָׁע בָּא תַּחְתָּיו (ירושלמי ברכות ט:א), כְּגוֹן מָרְדְּכַי וְהָמָן (אסתר ז:ט-י):",1,0],[21,19,"טוֹב שֶׁבֶת בְּאֶרֶץ מִדְבָּר. גַּם זֶה עַל סִלּוּק הַשְּׁכִינָה נֶאֱמַר:",1,0],[21,20,"וּכְסִיל אָדָם. וּכְסִילוּת שֶׁל אָדָם:",1,0],[21,22,"עִיר גִּבּוֹרִים עָלָה חָכָם. זֶה מֹשֶׁה רַבֵּינוּ שֶׁעָלָה לְבֵין הַמַּלְאָכִים גִּבּוֹרֵי כֹחַ (תהלים קג:כ). וַיּוֹרֶד וְגוֹ׳. תּוֹרָה:",1,0],[21,24,"יָהִיר. גַּס רוּחַ, סוֹפוֹ לִהְיוֹת לֵץ שֶׁאֵינוֹ חָשׁ לִשְׁמוֹעַ מוּסָר:",1,0],[21,26,"וְצַדִּיק יִתֵּן. כָּל צָרְכֵי בֵיתוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן לוֹ:",1,0],[21,27,"אַף כִּי בְזִמָּה יְבִיאֶנּוּ. וְכָל שֶׁכֵּן כְּשֶׁהוּא מְבִיאוֹ לְהַרְשִׁיעוֹ, וּבְעֵצָה רָעָה, כְּגוֹן קָרְבְּנוֹת בִּלְעָם וּבָלָק, שֶׁלֹּא הָיוּ מְבִיאִים אֶלָּא לְקַלֵּל אֶת יִשְׂרָאֵל (במדבר כג):",1,0],[21,28,"וְאִישׁ שׁוֹמֵעַ. שֶׁקִּבֵּל מַה שֶּׁכָּתוּב בַּתּוֹרָה ״לֹא תַעֲנֶה בְרֵעֲךָ וְגוֹ׳״ (שמות כ:יג):",1,0],[21,28,"לָנֶצַח. תָּמִיד:",2,0],[21,29,"הֵעֵז אִישׁ רָשָׁע בְּפָנָיו. הָרָשָׁע מַרְאֶה עַזּוּתוֹ בִּשְׁעַת כַּעֲסוֹ:",1,0],[21,29,"בְּפָנָיו. מִלְּשׁוֹן ״אַף״ (משלי כט:כב):",2,0],[21,30,"אֵין חָכְמָה וְגוֹ׳. אֵין כָּל חָכָם וְנָבוֹן חָשׁוּב לְנֶגֶד ה׳, כָּל מָקוֹם שֶׁיֵּשׁ חִלּוּל הַשֵּׁם, אֵין חוֹלְקִין כָּבוֹד לָרַב (ברכות יט:):",1,0],[22,1,"נִבְחָר שֵׁם מֵעֹשֶׁר רָב. שֵׁם טוֹב:",1,0],[22,1,"מִכֶּסֶף וּמִזָּהָב. נִבְחָר חֵן טוֹב:",2,0],[22,2,"עוֹשֵׂה כֻלָּם ה׳. כְּשֶׁעָנִי אוֹמֵר לֶעָשִׁיר: פַּרְנְסֵנִי, וְהוּא עוֹנֶה קָשׁוֹת, עוֹשֵׂה כֻלָּם ה׳. הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אוֹתָם חֲדָשִׁים, לָזֶה עָנִי וְלָזֶה עָשִׁיר (תמורה טז.):",1,0],[22,3,"עָרוּם רָאָה רָעָה. עֹנֶשׁ שֶׁל עֲבֵרָה, וְנִסְתָּר וְלֹא עָבַר עֲבֵרָה:",1,0],[22,4,"עֵקֶב עֲנָוָה. בִּשְׁבִיל הָעֲנָוָה יִרְאַת ה׳ בָּאָה. דָּבָר אַחֵר: עֲנָוָה עִקָּר, וְהַיִּרְאָה טְפֵלָה וְעָקֵב לָהּ, מִדְרָס לְרַגְלֶיהָ (ירושלמי שבת א,ג):",1,0],[22,5,"צִנִּים פַּחִים. כְּמוֹ ״לִצְנִינִם בְּצִדֵּיכֶם״ (במדבר לג:נה), ״וּבָאוּ עָלַיִךְ הֹצֶן״ (יחזקאל כג:כד), לְשׁוֹן גְּדוּדִים וְלִסְטִים:",1,0],[22,5,"צִנִּים פַּחִים. הֵם טְמוּנִים בְּדַרְכֵי הַמְּעַקֵּשׁ דְּרָכָיו, כְּלוֹמַר: יִסּוּרִים מוּכָנִים לוֹ:",2,0],[22,5,"שׁוֹמֵר נַפְשׁוֹ יִרְחַק מֵהֶם. שֶׁמְּיַשֵּׁר מַעֲשָׂיו יִנָּצֵל מֵהֶם:",3,0],[22,6,"חֲנוֹךְ לַנַּעַר. לְפִי מַה שֶּׁתְּלַמֵּד לַנַּעַר וּתְחַנְּכֵהוּ בִּדְבָרִים, אִם לְטוֹב אִם לְרַע, גַּם כִּי יַזְקִין לֹא יָסוּר מִמֶּנָּה:",1,0],[22,7,"עָשִׁיר בְּרָשִׁים יִמְשׁוֹל. עַם הָאָרֶץ צָרִיךְ לְתַלְמִיד חָכָם לְעוֹלָם (שבת קלט.):",1,0],[22,8,"זוֹרֵעַ עַוְלָה. יִקְצָר אָוֶן לְפִי זְרִיעָתוֹ קְצִירָתוֹ, לְפִי פְּעֻלָּתוֹ יִהְיֶה קַבָּלַת מַשְׂכֻּרְתּוֹ:",1,0],[22,8,"וְשֵׁבֶט עֶבְרָתוֹ יִכְלֶה. קְנֵה הַשִּׁבֹּלֶת שֶׁלּוֹ כָּלֶה וְהוֹלֵךְ לוֹ. יֵשׁ אוֹמְרִים (סא״א): שֵׁבֶט חֲמָתוֹ, שֶׁרוֹדֶה בְּנֵי אָדָם, כָּלֶה וְהוֹלֵךְ לוֹ, לְפִי שֶׁמַּפְסִיד אֶת יְכָלְתּוֹ:",2,0],[22,10,"גָּרֵשׁ לֵץ. יֵצֶר הָרָע:",1,0],[22,11,"אוֹהֵב טְהׇר לֵב חֵן שְׂפָתָיו. מִי שֶׁשְּׂפָתָיו חֵן:",1,0],[22,11,"רֵעֵהוּ מֶלֶךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֲבוֹ וּמְחַבְּבוֹ (בראשית רבה מא, ה):",2,0],[22,13,"אָמַר עָצֵל אֲרִי בַחוּץ. אֵיךְ אֵצֵא לִלְמֹד תּוֹרָה?",1,0],[22,14,"שׁוּחָה עֲמֻקָּה פִּי זָרוֹת. פִּי עוֹבְדֵי גִּלּוּלִים:",1,0],[22,14,"זְעוּם ה׳. מִי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׂוֹנְאוֹ, נוֹפֵל וְנִכְשָׁל בָּהּ:",2,0],[22,14,"זְעוּם. נָזוּף מִלְּפָנָיו:",3,0],[22,16,"עוֹשֵׁק דָּל לְהַרְבּוֹת לוֹ. עֹשֶׁר:",1,0],[22,16,"נוֹתֵן לְעָשִׁיר. סוֹף שֶׁנּוֹתֵן מָמוֹנוֹ לְעוֹבְדֵי גִּלּוּלִים הָעֲשִׁירִים, וְאַךְ לְמַחְסוֹר הוּא בָּא:",2,0],[22,17,"הַט אָזְנְךָ וּשְׁמַע דִּבְרֵי חֲכָמִים. לִלְמוֹד תּוֹרָה מֵחָכָם כָּל שֶׁהוּא:",1,0],[22,17,"וְלִבְּךָ תָּשִׁית לְדַעְתִּי. וְאִם רַבְּךָ רָשָׁע, לֹא תִלְמוֹד מִמַּעֲשָׂיו (חגיגה טו:):",2,0],[22,18,"כִּי נָעִים. יְהִי לְךָ לְאַחַר זְמַן אִם תִּשְׁמְרֵם וְתִצְפְּנֵם בְּבִטְנֶךָ, שֶׁלֹּא תִּשְׁכָּחֵם. וְאֵימָתַי יִהְיוּ שְׁמוּרִים בְּלִבְּךָ? בִּזְמַן שֶׁיִּכּוֹנוּ עַל שְׂפָתֶיךָ. כַּאֲשֶׁר תּוֹצִיאֵם בְּפִיךָ (עירובין נד.):",1,0],[22,19,"לִהְיוֹת בַּה׳ מִבְטַחֶךָ הוֹדַעְתִּיךָ. אֲנִי מוֹדִיעֲךָ שֶׁתִּבְטַח בַּה׳ וְתַעֲסֹק בַּתּוֹרָה, וְלֹא תֹאמַר: אֵיךְ אֲבַטֵּל מִמְּלַאכְתִּי וְאֵיךְ אֶתְפַּרְנֵס?",1,0],[22,20,"הֲלֹא כָתַבְתִּי לְךָ שָׁלִשִׁים. תּוֹרָה וּנְבִיאִים וּכְתוּבִים:",1,0],[22,21,"לְהוֹדִיעֲךָ קֹשְׁטְ. שָׁלִישִׁים כָּתַבְתִּי לְךָ כְּדֵי שֶׁתָּבִין מִתּוֹכָם קֹשְׁטְ אִמְרֵי אֱמֶת. לְהָשִׁיב אֲמָרִים אֱמֶת:",1,0],[22,21,"לְשֹׁלְחֶיךָ. לְשׁוֹאֲלְךָ הוֹרָאָה:",2,0],[22,22,"אַל תִּגְזָל דָּל. אַל תִּגְזְלֶנּוּ כִּי תִרְאֶנּוּ דַּל, בַּעֲבוּר שֶׁהוּא דַּל, וְאֵין לוֹ כֹּחַ לַעֲמֹד נֶגְדְּךָ:",1,0],[22,23,"כִּי ה׳ יָרִיב רִיבָם וְקָבַע. וְיִגְזֹל אֶת הַנֶּפֶשׁ:",1,0],[22,23,"קוֹבְעֵיהֶם. גּוֹזְלֵיהֶם. וּבִלְשׁוֹן אֲרַמִּי קְבִיעָה – גְּזֵלָה בְּמַסֶּכֶת רֹאשׁ הַשָּׁנָה (ראש השנה כו,א-ב): אֲתָא הַהוּא גַּבְרָא לְקַמֵּיהּ אָמַר לֵיהּ: קַבְּעַן פְּלַנְיָא וְכוּ׳:",2,0],[22,24,"אַל תִּתְרַע. אַל תִּתְחַבֵּר, לְשׁוֹן רֵעוּת:",1,0],[22,25,"פֶּן תֶּאֱלַף. פֶּן תִּלְמַד:",1,0],[22,26,"אַל תְּהִי בְתוֹקְעֵי כָף בָּעוֹרְבִים מַשָּׁאוֹת. הַלְוָאוֹת, כְּמוֹ ״מַשַּׁאת מְאוּמָה״ (דברים כד:י):",1,0],[22,28,"אַל תַּסֵּג גְּבוּל עוֹלָם. אַל תָּשֵׁג אָחוֹר מִנְהַג אֲבוֹתֶיךָ. וְאָמְרוּ זִכְרוֹנָם לִבְרָכָה (תורת כהנים קדושים פרשתא א פרק ג): הַמַּנִּיחַ כַּלְכָּלָה תַּחַת הַגֶּפֶן בִּשְׁעַת בְּצִירָה כְּדֵי שֶׁיִּפּוֹל בְּתוֹכוֹ הַפֶּרֶט, עַל זֶה נֶאֱמַר אַל תַּסֵּג גְּבוּל וְגוֹ׳. תַּסֵּג כְּמוֹ ״יִסּוֹגוּ אָחוֹר״ (תהלים קכט:ה):",1,0],[23,1,"כִּי תֵשֵׁב לִלְחוֹם. לֶאֱכוֹל:",1,0],[23,1,"בִּין תָּבִין. תֵּן לִבְּךָ לָדַעַת מִי הוּא, אִם עֵינוֹ צָרָה אוֹ יָפָה:",2,0],[23,2,"וְשַׂמְתָּ שַׂכִּין בְּלֹעֶךָ. בִּלְחָיֶיךָ; אִם רָאִיתָ עֵינוֹ צָרָה, אַל תֹּאכַל מִשֶּׁלּוֹ:",1,0],[23,2,"אִם בַּעַל נֶפֶשׁ אָתָּה. אִם רַעַבְתָּן אַתָּה וְתָאֵב לֶאֱכוֹל, טוֹב לִתְחוֹב סַכִּין בֵּין שִׁנֶּיךָ. וְרַבּוֹתֵינוּ דָּרְשׁוּ (חולין ו.) בְּתַלְמִיד הַיּוֹשֵׁב לִפְנֵי רַבּוֹ; אִם יוֹדֵעַ בְּרַבּוֹ שֶׁיַּחֲזִיר לוֹ תְּשׁוּבָה עַל כָּל דָּבָר שֶׁיִּשְׁאָלֵהוּ, יְדַקְדֵּק וְיִשְׁאַל שְׁמוּעָתוֹ, וְאִם לָאו – יִשְׁתּוֹק:",2,0],[23,3,"אַל תִּתְאָו לְמַטְעַמּוֹתָיו. אֶלָּא פְּרוֹשׁ מִמֶּנּוּ וְלֵךְ לִפְנֵי רַב הָגוּן, וְלֹא תְּבַיְּשֵׁהוּ בִּשְׁאֵלוֹת, אַחַר שֶׁלֹּא יֵדַע לְהָשִׁיב:",1,0],[23,4,"אַל תִּיגַע לְהַעֲשִׁיר. לַעֲשׂוֹת גִּירְסָתְךָ חֲבִילוֹת חֲבִילוֹת, כִּי סוֹף שֶׁתִּשְׁכָּחֶנָּה:",1,0],[23,5,"הֲתָעִיף עֵינֶיךָ בּוֹ. כְּרֶגַע, שֶׁתִּכְפּוֹל עֵינֶיךָ לְעָצְמוֹ, וְאֵין אוֹתָהּ גִּירְסָא מְצוּיָה בְּךָ:",1,0],[23,5,"הֲתָעִיף. כְּמוֹ ״וְכָפַלְתָּ״ (שמות כו:ט): ״וְתָעֵיף״ (תרגום אונקלוס):",2,0],[23,7,"כִּי כְּמוֹ שָׁעַר בְּנַפְשׁוֹ. שָׁעַר זֶה נָקוּד חֶצְיוֹ פַּתָּח וְחֶצְיוֹ קָמַץ וְטַעֲמוֹ לְמַטָּה, לְכָךְ הוּא פֹּעַל וְלֹא שֵׁם דָּבָר; שֶׁאִם הָיָה שֵׁם דָּבָר הָיָה קָמַץ וְטַעֲמוֹ לְמַעְלָה כְּכָל שַׁעַר שֶׁבַּמִּקְרָא. וּפִתְרוֹנוֹ: כְּאִלּוּ שָׁפַךְ הָאוֹכֵל הַזֶּה מְרָה בְּנַפְשׁוֹ שֶׁל רַע הָעַיִן כֵּן הוּא שָׁעַר מִן לְשׁוֹן ״הַתְּאֵנִים הַשֹּׁעָרִים״ (ירמיהו כט:יז) הַמָּרִים:",1,0],[23,8,"פִּתְּךָ. שֶׁאֲכַלְתּוֹ בְּבֵיתוֹ, סוֹף שֶׁתְּקִיאֶנָּה מִפְּנֵי הַבּוּשָׁה:",1,0],[23,8,"וְשִׁחַתָּ דְּבָרֶיךָ הַנְּעִימִים. חַנּוֹת שֶׁהֶחֱזַקְתָּ וְדִבַּרְתָּ לוֹ דְּבָרִים רַכִּים, הַכֹּל אִבַּדְתָּ:",2,0],[23,10,"וּבִשְׂדֵי יְתוֹמִים. בְּלֶקֶט שִׁכְחָה וּפֵאָה הָרָאוּי לָהֶם:",1,0],[23,16,"בְּדַבֵּר שְׂפָתֶיךָ מֵישָׁרִים. עַל יְדֵי שֶׁחָכַם לִבֶּךָ:",1,0],[23,17,"אַל יְקַנֵּא לִבְּךָ בַּחַטָּאִים. בְּהַצְלָחָתָם, לִהְיוֹת רָשָׁע כְּמוֹתָם (ברכות ז:):",1,0],[23,18,"כִּי אִם יֵשׁ אַחֲרִית. אִם זֶה מְשַׁמֵּשׁ בִּלְשׁוֹן אֲשֶׁר, כְּלוֹמַר: אֲשֶׁר בַּעֲבוּר זֶה יֵשׁ אַחֲרִית תִּקְוָה אֵלֶיךָ:",1,0],[23,19,"שְׁמַע אַתָּה בְנִי וַחֲכָם וְאַשֵּׁר בַּדֶּרֶךְ לִבֶּךָ. מֵאַחַר שֶׁתִּתְחַכֵּם תּוּכַל לָלֶכֶת בְּדַרְכֵי לִבְּךָ, כִּי לֵב חָכָם לֹא יַשִּׁיאֲךָ לַעֲבֵרָה:",1,0],[23,21,"כִּי סוֹבֵא וְזוֹלֵל יִוָּרֵשׁ. ״יִתְמַסְכֵּן״ (תרגום יונתן):",1,0],[23,21,"וּקְרָעִים תַּלְבִּישׁ נוּמָה. הָעַצְלוּת וְהַתְּנוּמָה תַּלְבִּישׁ אוֹתְךָ בְּגָדִים קְרוּעִים:",2,0],[23,23,"אֱמֶת קְנֵה. וְאִם לֹא תִמְצָא לִלְמֹד בְּחִנָּם לְמֹד בְּשָׂכָר, וְאַל תֹּאמַר: כְּשֵׁם שֶׁלָּמַדְתִּי בְּשָׂכָר, כָּךְ אֲלַמְּדֶנָּה בְּשָׂכָר (בכורות כט.):",1,0],[23,27,"וּבְאֵר צָרָה. אֶשְׁטְרֵיינָ״א בְּלַעַ״ז:",1,0],[23,28,"אַף הִיא כְּחֶתֶף. פִּתְאוֹם:",1,0],[23,28,"וּבוֹגְדִים בְּאָדָם תּוֹסִיף. מְרַבָּה בְּיִשְׂרָאֵל בּוֹגְדִים לַה׳, וְעַל הָאֲפִיקוֹרְסִין מְדַבֵּר:",2,0],[23,29,"לְמִי אוֹי לְמִי אֲבוֹי. לְשׁוֹן צְעָקָה וִילָלָה:",1,0],[23,29,"לְמִי מִדְיָנִים לְמִי שִׂיחַ. לְמִי שֶׁיֵּשׁ לוֹ מִדְיָנִים עִם הַבְּרִיּוֹת וְשִׂיחָה יְתֵרָה, לוֹ אוֹי וַאֲבוֹי, כִּי בְּרֹב דְּבָרִים רֹב פֶּשַׁע (משלי י:יט):",2,0],[23,29,"לְמִי חַכְלִילוּת עֵינָיִם. מֵרוֹב יַיִן מַאֲדִימִים עֵינָיו, וּגְנַאי הוּא (תנחומא, שמיני ה):",3,0],[23,30,"מִמְסָךְ. מִמֶּזֶג, וְהוּא שֵׁם דָּבָר כְּמוֹ ״מִמְכָּר״ (ויקרא כה:יד):",1,0],[23,30,"לַחְקֹר מִמְסָךְ. שֶׁחוֹקְרִין וּבוֹדְקִין הֵיכָן מוֹכְרִין יַיִן טוֹב:",2,0],[23,31,"אַל תֵּרֶא יַיִן כִּי יִתְאַדָּם. אַל תִּתֵּן בּוֹ עֵינֶיךָ:",1,0],[23,31,"כִּי יִתֵּן בַּכּוֹס עֵינוֹ יִתְהַלֵּךְ בְּמֵישָׁרִים. הַמַּרְבֶּה שִׁכְרוּת, כָּל עֲבֵרוֹת דּוֹמוֹת לוֹ לְמִישׁוֹר, כָּל הַדְּרָכִים יְשָׁרִים בְּעֵינָיו:",2,0],[23,31,"בַּכּוֹס. בַּכִּיס כְּתִיב, כְּלוֹמַר: הַשּׁוֹתֶה נוֹתֵן עַיִן בַּכּוֹס וְהַחֶנְוָנִי – בְּכִיסוֹ שֶׁל זֶה (יומא עד:-עה.):",3,0],[23,32,"יַפְרִישׁ. לְשׁוֹן עֲקִיצָה, פויינ״ט בְּלַעַ״ז, ״בְּמַלְמַד הַבָּקָר״ (שופטים ג:לא) תַּרְגּוּם: ״בְּפָרַשׁ תּוֹרֵי״ (תרגום יונתן), וּבַגְּמָרָא (בבא מציעא פ.): דְּנָקִיט פַּרְשָׁא, אגוילו״ן בְּלַעַ״ז. וְיֵשׁ פּוֹתְרִין: מַפְרִישׁוֹ מִן הַחַיִּים:",1,0],[23,33,"עֵינֶיךָ יִרְאוּ זָרוֹת. כְּשֶׁתִּשְׁתַּכֵּר, הַיַּיִן בּוֹעֵר בְּךָ וּמַשִּׂיאֲךָ לְהַבִּיט בְּזוֹנוֹת:",1,0],[23,34,"וְהָיִיתָ. מְשֻׁגָּע (דברים כח:לד):",1,0],[23,34,"כְּשׁוֹכֵב בְּלֶב יָם וּכְשׁוֹכֵב בְּרֹאשׁ חִבֵּל. תֹּרֶן הַסְּפִינָה נוֹחַ לִפּוֹל מִמֶּנּוּ:",2,0],[23,35,"הִכּוּנִי בַל חָלִיתִי וְגוֹ׳. כְּשֶׁיִּקַץ מִיֵּינוֹ אֵינוֹ מַרְגִּישׁ בְּכָל הָרָעוֹת שֶׁעָבְרוּ עָלָיו, וְחוֹזֵר לִשְׁתּוֹת:",1,0],[24,5,"גֶּבֶר חָכָם בְּעוֹז. אִישׁ חָכָם הוּא תָּמִיד בְּעוֹז:",1,0],[24,7,"רָאמוֹת לֶאֱוִיל חָכְמוֹת. מִין אֶבֶן יְקָרָה שֶׁאֵינָהּ מְצוּיָה, כְּמָה דְתֵימָא ״רָאמוֹת וְגָבִישׁ״ (איוב כח:יח). כְּלוֹמַר: כָּל חָכְמָה דּוֹמָה לַכְּסִיל כְּאֶבֶן יְקָרָה וּכְמַרְגָּלִיּוֹת לִקְנוֹת, לוֹמַר: אֵיךְ אֶעֱסֹק בַּתּוֹרָה, מָתַי תַּעֲלֶה בְּיָדִי? אֲבָל הֶחָכָם שׁוֹנֶה הַיּוֹם מְעַט וּלְמָחָר מְעַט (דברים רבה ח:ג):",1,0],[24,8,"מְחַשֵּׁב לְהָרֵעַ. חוֹרֵשׁ תַּחְבּוּלוֹת רֶשַׁע:",1,0],[24,8,"לוֹ בַּעַל מְזִמּוֹת יִקְרָאוּ. גּוֹרֵם לוֹ רַע, שֶׁהַבְּרִיּוֹת קוֹרְאִים לוֹ: בַּעַל מְזִמּוֹת. עֲצַת רְשָׁעִים:",2,0],[24,9,"זִמַּת אִוֶּלֶת. עֲצַת אִוֶּלֶת חַטָּאת לִבְעָלֶיהָ:",1,0],[24,9,"וְתוֹעֲבַת לְאָדָם לֵץ. לֵיצָנוּת הִיא הַמְּתַעֶבֶת אֶת הָאָדָם עַל הַקָּדוֹשׁ בָּרוּךְ הוּא וְעַל הַבְּרִיּוֹת:",2,0],[24,10,"הִתְרַפִּיתָ. מִן הַתּוֹרָה:",1,0],[24,10,"בְּיוֹם צָרָה צַר כֹּחֶכָה. מַלְאֲכֵי הַשָּׁרֵת לֹא יִהְיוּ מְאַמְּצִין כֹּחֲךָ. זֶה מִדְרַשׁ חֲכָמִים (ברכות סג.). וּלְפִי פְּשׁוּטוֹ: הִתְרַפִּיתָ בְּיוֹם צָרַת אֲהוּבְךָ לַעֲמוֹד מִנֶּגֶד:",2,0],[24,10,"צַר כֹּחֶכָה. בְּיוֹם פּוּרְעָנוּתְךָ, דִּכְתִיב ״אִם הַחֲרֵשׁ תַּחֲרִישִׁי וְגוֹ׳״ (אסתר ד:יד):",3,0],[24,11,"הַצֵּל לְקוּחִים וְגוֹ׳. לְהַצִּיל אֶת הַלְּקוּחִים לַמָּוֶת, אֶת הַמָטִים לַהֶרֶג:",1,0],[24,11,"אִם תַּחְשׂוֹךְ. מִלְּהַצִּילָם, עַל זֶה אָמַרְתִּי ״צַר כֹּחֲךָ״ (משלי כד:י):",2,0],[24,12,"כִּי תֹאמַר. שֶׁמָּא תֹּאמַר, וְזֶהוּ כִּי מְשַׁמֵּשׁ בִּלְשׁוֹן דִּלְמָא:",1,0],[24,13,"אֱכָל בְּנִי דְבַשׁ. כְּלוֹמַר: דֶּרֶךְ בְּנֵי אָדָם לֶאֱכֹל דְּבַשׁ כִּי טוֹב הוּא. אַף כֵּן דְּעֵה חָכְמָה לְנַפְשֶׁךָ. וּכְשֵׁם שֶׁאַתָּה רוֹדֵף לֶאֱכֹל דְּבַשׁ, כֵּן תְּהֵא רוֹדֵף לָדַעַת חָכְמָה:",1,0],[24,14,"אִם מָצָאתָ אוֹתָהּ, אָז יֵשׁ אַחֲרִית:",1,0],[24,19,"אַל תִּתְחַר. לִהְיוֹת כְּמוֹתָם, כְּמוֹ ״אֵיךְ תְּתַחֲרֶה״ (ירמיהו יב:ה), ״כִּי אַתָּה מִתְחַרֶה בָאָרֶז״ (ירמיהו כב:טו):",1,0],[24,21,"יְרָא אֶת ה׳ בְּנִי וָמֶלֶךְ. יְרָא אֶת הַמֶּלֶךְ, וּבִלְבַד שֶׁלֹּא יְסִירְךָ מִיִּרְאַת ה׳, וּלְעוֹלָם יִרְאַת ה׳ קוֹדֶמֶת:",1,0],[24,21,"עִם שׁוֹנִים אַל תִּתְעָרָב. הָאוֹמְרִים: שְׁתֵּי רָשֻׁיּוֹת יֵשׁ:",2,0],[24,22,"וּפִיד שְׁנֵיהֶם. שֶׁבֶר עֲבוֹדַת גִּלּוּלִים וְשֶׁבֶר עוֹבְדֶיהָ:",1,0],[24,23,"גַּם אֵלֶּה לַחֲכָמִים. כָּל הַדְּבָרִים שֶׁבָּעִנְיָן שֶׁלְּמַטָּה אֲמוּרִים לַחֲכָמִים הַיּוֹשְׁבִים בְּדִין, שֶׁלֹּא יַכִּירוּ פָנִים בְּמִשְׁפָּט כִּי לֹא טוֹב (תנחומא, משפטים ד):",1,0],[24,26,"שְׂפָתַיִם יִשָּׁק. רְאוּיִים כָּל שְׂפָתַיִם לְנַשְּׁקוֹ:",1,0],[24,27,"הָכֵן בַּחוּץ. זֶה מִקְרָא:",1,0],[24,27,"וְעַתְּדָהּ בַּשָּׂדֶה. זוֹ מִשְׁנָה:",2,0],[24,27,"אַחַר וּבָנִיתָ בֵיתֶךָ. זוֹ גְּמָרָא (סוטה מד.). דָּבָר אַחֵר: כְּמַשְׁמָעוֹ, בַּתְּחִלָּה קַח לְךָ שָׂדוֹת וּכְרָמִים, וְאַחַר כָּךְ וְעַתְּדָהּ, לְשׁוֹן ״עַתּוּדִים״ (בראשית לא:י) – שִׂים לְךָ בְּהֵמוֹת בַּשָּׂדֶה, וְאַחַר וּבָנִיתָ בֵיתֶךָ. תִּקַּח אִשָּׁה:",3,0],[24,28,"וְהַפִּתִּיתָ בִּשְׂפָתֶיךָ. תִּתְפַּתֶּה לְרֵעֲךָ בְּדִבּוּרְךָ:",1,0],[24,30,"אִישׁ עָצֵל. שֶׁאֵינוֹ חוֹזֵר עַל גִּרְסַת תַּלְמוּדוֹ:",1,0],[24,31,"קִמְּשׂוֹנִים. חוֹחִים:",1,0],[24,31,"כָּסּוּ. נִכְסוּ:",2,0],[24,31,"חֲרֻלִּים. גְּדוֹלִים מִקִּמְּשׂוֹנִים, וַהֲרֵי הֵם חַדִּים כְּקוֹצִים:",3,0],[24,31,"וְגֶדֶר אֲבָנָיו נֶהֱרָסָה. כָּךְ מִי שֶׁאֵינוֹ חוֹזֵר עַל תַּלְמוּדוֹ, מִתְּחִלָּה מְשַׁכֵּחַ רָאשֵׁי פְרָקִים, וְסוֹף מְחַלֵּף דִּבְרֵי חֲכָמִים מִזֶּה לָזֶה (אבות דרבי נתן כד,ו), שֶׁאוֹמֵר עַל טָהוֹר טָמֵא וְעַל טָמֵא טָהוֹר, וְהוּא מַחֲרִיב אֶת הָעוֹלָם:",4,0],[24,34,"מִתְהַלֵּךְ רֵישֶׁךָ. הַדְּבָרִים שֶׁאַתָּה רָשׁ מֵהֶם יָבוֹאוּ לְךָ בִּמְרוּצָה:",1,0],[25,1,"גַּם אֵלֶּה מִשְׁלֵי שְׁלֹמֹה אֲשֶׁר הֶעְתִּיקוּ. חָזַר לְדוֹרְשָׁם, כְּשֶׁנִּתְמַנָּה חִזְקִיָּהוּ לְמֶלֶךְ וְהוּא הוֹשִׁיב תַּלְמִידִים בְּכָל עִיר, כְּדְאָמְרִינַן בְּפֶרֶק חֵלֶק (סנהדרין צד:): בָּדְקוּ מִדָּן וְעַד בְּאֵר שֶׁבַע וְלֹא מָצְאוּ עַם הָאָרֶץ:",1,0],[25,1,"הֶעְתִּיקוּ. הֶחֱזִיקוּ:",2,0],[25,2,"כְּבוֹד אֱלֹהִים הַסְתֵּר דָּבָר. כְּגוֹן מַעֲשֵׂה מֶרְכָּבָה (יחזקאל א) וּמַעֲשֵׂה בְרֵאשִׁית (בראשית א):",1,0],[25,2,"וּכְבוֹד מְלָכִים חֲקֹר דָּבָר. כְּשֶׁאַתָּה דּוֹרֵשׁ בִּכְבוֹד מְלָכִים אוֹ בִּכְבוֹד חֲכָמִים שֶׁעָשׂוּ סְיָגִים לַתּוֹרָה וּבַגְּזֵרוֹת שֶׁגָּזְרוּ בָּהֶם, יֵשׁ לְךָ לַחֲקֹר וְלִדְרֹשׁ וְלִשְׁאֹל טַעַם לַדָּבָר. אֲבָל כְּשֶׁתִּדְרֹשׁ בְּמַעֲשֵׂה מֶרְכָּבָה וּבְמַעֲשֵׂה בְרֵאשִׁית וּבַחֻקִּים הַכְּתוּבִים בַּתּוֹרָה, כְּגוֹן חֻקִּים וּדְבָרִים שֶׁהַשָּׂטָן מְקַטְרֵג עֲלֵיהֶם וּמֵשִׁיב עֲלֵיהֶם, בַּאֲכִילַת חֲזִיר וְכִלְאֵי כֶּרֶם וְשַׁעַטְנֵז, אֵין לְךָ לַחֲקֹר רַק לְהַסְתִּיר, וְלוֹמַר: גְּזֵרַת מֶלֶךְ הוּא:",2,0],[25,3,"אֵין חֵקֶר. לְרוּם שָׁמַיִם וּלְעוֹמֶק הָאָרֶץ וּלְלֵב מְלָכִים אֵין חֵקֶר, שֶׁכַּמָּה דִינִים בָּאִים לִפְנֵיהֶם וְכַמָּה מִלְחָמוֹת, וּצְרִיכִים לָתֵת לֵב לְכֻלָּם. וְאִם כָּל הַלְּשׁוֹנוֹת מְדַבְּרִים וְכָל הַיָּדַיִם כּוֹתְבִין, אֵינָן יְכוֹלִין לִכְתּוֹב חֲלָלָהּ שֶׁל רְשׁוּת:",1,0],[25,4,"הָגוֹ סִיגִים מִכָּסֶף. מָשׁוּךְ, כְּמוֹ ״כַּאֲשֶׁר הֹגָה מִן הַמְּסִלָּה״ (שמואל ב כ:יג); כְּשֵׁם שֶׁאֵין הַכְּלִי שֶׁל כֶּסֶף יוֹצֵא לִמְלֶאכֶת צוֹרֵף עַד שֶׁיּוֹצִיאוּ מִמֶּנּוּ סִיגִים שֶׁל נְחֹשֶׁת שֶׁבּוֹ, כָּךְ אֵין צִבּוּר נִפְטָרִין מֵעֹנֶשׁ עַד שֶׁיּוֹצִיאוּ מִתּוֹכָם הָרְשָׁעִים וְיַעֲשׂוּ בָּהֶם דִּין:",1,0],[25,6,"אַל תִּתְהַדַּר לִפְנֵי מֶלֶךְ. לְהֵרָאוֹת כְּבוֹדְךָ וּלְהִתְגָּאוֹת לִפְנֵי מֶלֶךְ אוֹ לַעֲמֹד לִפְנֵי מִי שֶׁגָּדוֹל מִמְּךָ, כִּי טוֹב שֶׁיֹּאמְרוּ לְךָ עֲלֵה הֵנָּה מִשֶּׁתָּבוֹא בְּלֹא רְשׁוּתוֹ וְיֹאמְרוּ לְךָ צֵא:",1,0],[25,7,"אֲשֶׁר רָאוּ עֵינֶיךָ. שֶׁדָּבָר זֶה אֱמֶת:",1,0],[25,8,"פֶּן מַה תַּעֲשֶׂה. פֶּן תָּבֹא לִידֵי לֹא תֵדַע מַה לַּעֲשׂוֹת בְּאַחֲרִיתָהּ:",1,0],[25,9,"רִיבְךָ רִיב אֶת רֵעֶךָ. וְאִם עַל כָּרְחֲךָ אַתָּה צָרִיךְ לָרִיב וּלְהוֹכִיחַ עִם רֵעֶךָ, מִכָּל מָקוֹם, סוֹד אַחֵר אַל תְּגָל. לֹא תַזְכִּיר לוֹ דֹּפִי אֲבוֹתָיו שֶׁמֵּתוּ, שֶׁאֵין הַכֹּל יוֹדְעִין אוֹתוֹ וְאַתָּה מְגַלֵּהוּ (סנהדרין מד:):",1,0],[25,10,"פֶּן יְחַסֶּדְךָ שׁוֹמֵעַ. ״חֶרְפַּת מִצְרַיִם״ (יהושע ה:ט) מְתַרְגְּמִינָן: ״חֲסוּדָא דְּמִצְרָאֵי״, פֶּן יְחַסֶּדְךָ, הַשּׁוֹמֵעַ וְיִקְרָאֲךָ מוֹצִיא דִּבָּה:",1,0],[25,11,"תַּפּוּחֵי זָהָב. כְּעֵין כַּפְתּוֹרִין מְצֻיָּרִין עַל מַשְׂכִּיּוֹת כָּסֶף. מַשְׂכִּיּוֹת כֵּלִים הַמְצֻפִּין בְּכֶסֶף, כְּמוֹ ״וְשַׂכֹּתִי כַפִּי״ (שמות לג:כב):",1,0],[25,11,"דָּבָר דָּבוּר עַל אָפְנָיו. עַל כַּנּוֹ, וְדוּגְמָתוֹ ״נָשָׂאתִי אֵימֶיךָ אָפוּנָה״ (תהלים פח:טז) – מְבֻסֶּסֶת וּמְיֻשֶּׁבֶת בְּקִרְבִּי. וְאֵין זֶה מִגִּזְרַת ׳אוֹפַן וְגַלְגַּל׳ (ישעיהו כח:כז-כח), שֶׁאִלּוּ כֵּן, הָיָה נָקוּד פַּתָּ״ח תַּחַת הַפֵּ״א כְּמוֹ ״הָאוֹפַנִּים״ (מלכים א ז:לב), וְלֹא יִפֹּל בּוֹ נְקֻדַּת חֲטַף קָמַץ:",2,0],[25,12,"נֶזֶם זָהָב וַחֲלִי כָתֶם. עֲדִי קְבוּצַת זָהָב, כְּמוֹ ״וַתַּעַד נִזְמָהּ וְחֶלְיָתָהּ״ (הושע ב:טו), כְּמוֹ ״חֲלָאִים״ (שיר השירים ז:ב):",1,0],[25,12,"כֶּתֶם. לְשׁוֹן תַּכְשִׁיט זָהָב, וְכֵן ״כֶּתֶם פָּז״ (שיר השירים ה:יא):",2,0],[25,13,"כְּצִנַּת שֶׁלֶג. כְּקוֹר יְמֵי שֶׁלֶג שֶׁאָדָם מִתְאַוֶּה לוֹ בִּימֵי קָצִיר, וְלֹא שֶׁלֶג מַמָּשׁ, שֶׁהַשֶּׁלֶג לֹא טוֹב הוּא בִּשְׁעַת קָצִיר:",1,0],[25,14,"נְשִׂיאִים וְרוּחַ וְגוֹ׳. כַּאֲשֶׁר יִהְיֶה תּוֹחֶלֶת שָׁוְא כְּשֶׁהַשָּׁמַיִם מִתְקַשְּׁרִים בֶּעָבִים וְהָרוּחַ מְנַשֶּׁבֶת וְאָדָם מְצַפֶּה שֶׁיָּבֹא גֶשֶׁם וְלֹא בָא, וְהֵם מִצְטַעֲרִים וְכָלוֹת עֵינֵיהֶם, כָּךְ אִישׁ מִתְפָּאֵר לוֹמַר: כָּךְ וְכָךְ צְדָקָה אֶתֵּן לְיַד גַּבַּאי, וְהוּא מְשַׁקֵּר, וְכָלוֹת עֵינֵי עֲנִיִּים לְמַתְּנָתוֹ וְאֵינָהּ בָּאָה:",1,0],[25,15,"בְּאֹרֶךְ אַפַּיִם יְפֻתֶּה קָצִין. בְּעוֹד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַאֲרִיךְ אַפּוֹ וְאֵינוֹ נִפְרָע, יִתְּנוּ לֵב הַחוֹטְאִים לְפַתּוֹתוֹ בִּתְשׁוּבָה וּתְפִלָּה:",1,0],[25,15,"וְלָשׁוֹן רַכָּה. בִּתְפִלָּה וְתַחֲנוּנִים:",2,0],[25,15,"תִּשְׁבָּר גָּרֶם. עֶצֶם קֹשִׁי הַגְּזֵרָה:",3,0],[25,16,"דְּבַשׁ מָצָאתָ וְגוֹ׳:",1,0],[25,17,"הוֹקַר רַגְלְךָ. כְּשֵׁם שֶׁאִם מָצָאתָ דְּבַשׁ וְהוּא מָתוֹק לְחִכְּךָ, אַתָּה צָרִיךְ שֶׁלֹּא תֹּאכַל מִמֶּנּוּ פֶּן תִּשְׂבָּעֶנּוּ וַהֲקֵאֹתוֹ, כָּךְ הוֹקַר רַגְלְךָ מִבֵּית רֵעֶךָ אַע״פּ שֶׁהוּא מְקָרֶבְךָ, מְנַע מִלָּבֹא שָׁם יוֹם יוֹם פֶּן יִשְׂבָּעֲךָ וְיִשְׂנָא אוֹתְךָ. וּלְעִנְיַן מִדְרָשׁוֹ (חגיגה ז.): אַל תְּהִי רָגִיל לַחֲטֹא שׁוֹגֵג וּלְהָבִיא תָּמִיד חַטָּאוֹת וַאֲשָׁמוֹת לְבֵית ה׳ שֶׁנִּקְרָא רֵעַ לְיִשְׂרָאֵל, דִּכְתִיב ״זֶה דוֹדִי וְזֶה רֵעִי״ (שיר השירים ה:טז):",1,0],[25,18,"מֵפִיץ וְחֶרֶב. שֵׁם כְּלֵי מִלְחָמָה:",1,0],[25,19,"שֵׁן רֹעָה. רְצוּצָה:",1,0],[25,19,"מוּעָדֶת. כְּמוֹ ״וְלֹא מָעֲדוּ קַרְסֻלָּי״ (תהלים יח:לז):",2,0],[25,19,"מִבְטָח בּוֹגֵד. מְכַזֵּב בּוֹ בְּיוֹם צָרָתוֹ כְּשֵׁן רְצוּצָה וּמוּעֶדֶת:",3,0],[25,20,"מַעֲדֶה בֶּגֶד בְּיוֹם קָרָה. ״בֶּגֶד עִדִּים״ (ישעיה סד:ה): בֶּגֶד מוּסָר, כְּלִי שֶׁהוּא רָאוּי לַהֲסִירוֹ מֵעָלָיו לְפִי שֶׁהוּא בָּלוּי; כְּדִמְתַרְגְּמִינָן ״וַיָּסַר״ (בראשית ח:יג): ״וְיַעְדֵּי״ (תרגום אונקלוס). וְזֶה פִּתְרוֹנוֹ: בֶּגֶד בָּלוּי הֲרֵי הוּא בְּיוֹם קָרָה כְּחֹמֶץ עַל נָתֶר. נָתֶר. מִין אֲדָמָה רַכָּה, כְּגוֹן אֲדָמָה שֶׁלָּנוּ הַנִּקְרָא קְרִידָ״א, וְהָיוּ חוֹקְקִים אוֹתָהּ וְעוֹשִׂין כֵּלִים; וְאִם יִפֹּל בּוֹ חֹמֶץ, מְמַסְמְסוֹ וְנִשְׁחָת. אַף שָׁר בַּשִּׁרִים עַל לֶב רָע. דּוֹמֶה לִשְׁנֵיהֶם. וּמַה הוּא שָׁר בַּשִּׁירִים? זֶה הַמְּלַמֵּד תּוֹרָה לְתַלְמִיד רָשָׁע אֲשֶׁר אֵין בְּלִבּוֹ לְקַיְּמָהּ (חולין קלג.):",1,0],[25,21,"אִם רָעֵב שֹׂנַאֲךָ. כְּמַשְׁמָעוֹ, וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (סוכה נב,א-ב) עַל יֵצֶר הָרָע: אִם רָעֵב הוּא וְאוֹמֵר לְךָ לְהַשְׂבִּיעוֹ בַּעֲבֵרוֹת, מְשׁוֹךְ אֶת עַצְמְךָ לְבֵית הַמִּדְרָשׁ וְהַאֲכִילֵהוּ מִלַּחְמָהּ שֶׁל תּוֹרָה, וְכֵן הַשְׁקֵהוּ מָיִם. מִימֶיהָ שֶׁל תּוֹרָה:",1,0],[25,22,"כִּי גֶחָלִים. הֵם לוֹ שֶׁאַתָּה חֹתֶה וְשׁוֹאֵב מִן הַמְּדוּרָה לָתֵת עַל רֹאשׁוֹ:",1,0],[25,22,"חוֹתֶה. כָּל שְׁאִיבַת גֶּחָלִים מִתּוֹךְ הַהֶסֵּק קָרֵי חוֹתֶה, כְּדַאֲמַר ״לַחְתּוֹת אֵשׁ מִיָּקוּד״ (ישעיהו ל:יד):",2,0],[25,22,"וַה׳ יְשַׁלֶּם לָךְ. יַשְׁלִימֶנּוּ עִמָּךְ, שֶׁלֹּא יִתְגַּבֵּר עָלֶיךָ:",3,0],[25,23,"רוּחַ צָפוֹן תְּחוֹלֵל גָּשֶׁם. תּוֹלִיד וְתִבְרָא אֶת הַגֶּשֶׁם:",1,0],[25,23,"וּפָנִים נִזְעָמִים תְּחוֹלֵל לְשׁוֹן סָתֶר. לָשׁוֹן הָרָע גּוֹרֵם שֶׁיִּהְיוּ פְּנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נִזְעָמִים. וְכֵן דִּמְיוֹן פִּתְרוֹן הַמִּקְרָא: רוּחַ צָפוֹן עֲשׂוּיָה לְחוֹלֵל גָּשֶׁם, וְלְשׁוֹן סָתֶר עֲשׂוּיָה לְפָנִים נִזְעָמִים:",2,0],[25,24,"טוֹב שֶׁבֶת עַל פִּנַּת גָּג. עַל סִלּוּק הַשְּׁכִינָה נֶאֱמַר (איכה רבה פתיחתא כה):",1,0],[25,24,"מֵאֵשֶׁת מִדְיָנִים. כְּנֶסֶת יִשְׂרָאֵל שֶׁהִרְשִׁיעוּ אֶת מַעֲשֵׂיהֶם וְהִקְנִיטוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[25,24,"וּבֵית חָבֶר. בַּיִת שֶׁחִבְּרוּ בּוֹ גִּלּוּלִים לַשְּׁכִינָה:",3,0],[25,25,"עַל נֶפֶשׁ עֲיֵפָה. עֲשׂוּיָה לְהָשִׁיב נֶפֶשׁ עֲיֵפָה:",1,0],[25,25,"וּשְׁמוּעָה טוֹבָה. אַף הִיא שָׁוָה לָהֶם, וְכֵן יַעֲקֹב: ״וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם״ (בראשית מה:כז):",2,0],[25,26,"מַעְיָן נִרְפָּשׂ. עָכוּר בָּרַגְלַיִם:",1,0],[25,26,"צַדִּיק מָט לִפְנֵי רָשָׁע. כְּשֶׁהַצַּדִּיק מָט לִפְנֵי הָרָשָׁע וְיָרֵא לְהוֹכִיחַ עַל פָּנָיו דַּרְכּוֹ, שָׂנאוּי הַדָּבָר כְּמַעְיָן נִרְפָּשׂ וּמָקוֹר נִשְׁחָת:",2,0],[25,27,"אָכוֹל דְּבַשׁ. לֶאֱכוֹל דְּבַשׁ יוֹתֵר מִדַּאי. רֶמֶז הַדָּבָר לְדוֹרֵשׁ בְּמַעֲשֵׂה מֶרְכָּבָה (יחזקאל א) וּבְמַעֲשֵׂה בְרֵאשִׁית (בראשית א) לְגַלּוֹת לָרַבִּים, וְעַמֵּי הָאָרֶץ מְלַגְלְגִים עַל הַדְּבָרִים, וְשׁוֹאֲלִים מַה לְּמַעְלָה מַה לְּמַטָּה:",1,0],[25,27,"וְחֵקֶר כְּבוֹדָם כָּבוֹד. וְהֵיכָן הַחֵקֶר רָאוּי לִהְיוֹת? בְּדִבְרֵי חֲכָמִים, אֲשֶׁר כְּבוֹדָם כָּבוֹד בִּגְזֵרוֹתֵיהֶם, יֵשׁ לִשְׁאוֹל מָה טַעַם גָּזְרוּ כָּךְ, וְלָמָּה סִיְּגוּ בְּכָל גְּזֵרָה וּגְזֵרָה:",2,0],[26,1,"כַּשֶּׁלֶג בַּקַּיִץ. בְּשָׁעָה שֶׁשּׁוֹטְחִין הַתְּאֵנִים בַּחַמָּה לְיַבְּשָׁן וְלַעֲשׂוֹת קְצִיעוֹת, כְּדַאֲמַר ״הַלֶּחֶם וְהַקַּיִץ לֶאֱכֹל הַנְּעָרִים״ (שמואל ב טז:ב):",1,0],[26,2,"כַּצִּפּוֹר לָנוּד. שֶׁהוּא נָד, וְכַדְּרוֹר שֶׁהוּא חוֹזֵר לְקִנּוֹ:",1,0],[26,2,"כֵּן קִלְלַת חִנָּם לוֹ תָבוֹא. לְמִי שֶׁהוֹצִיאָהּ בְּפִיו:",2,0],[26,2,"דְּרוֹר. הוּא עוֹף הַנִּקְרָא רונדל״ע בְּלַעַ״ז, וְנִקְרָא דְּרוֹר – שֶׁדָּרָה בַּבַּיִת כְּבַשָּׂדֶה:",3,0],[26,3,"שׁוֹט לַסּוּס. הוּא עָשׂוּי, וְאַף שֵׁבֶט נָכוֹן לְגֵו כְּסִילִים. יִסּוּרִין מוּכָנִין לָרָשָׁע (שמות רבה ט:ח):",1,0],[26,4,"אַל תַּעַן כְּסִיל. בְּדִבְרֵי רִיב וּמַצָּה, פֶּן תִּשְׁוֶה לּוֹ:",1,0],[26,5,"עֲנֵה כְסִיל. הַבָּא לַהֲסִיתְךָ לַעֲבוֹדָה זָרָה, הוֹדַע לוֹ אִוַּלְתּוֹ:",1,0],[26,5,"פֶּן יִהְיֶה חָכָם בְּעֵינָיו. וְטַעַם שְׁנֵי פְסוּקִים אֵלּוּ מְפֹרָשׁ בְּתוֹכָם: אַל תַּעַן בְּדָבָר שֶׁתִּשְׁוֶה לוֹ אִם תַּעֲנֵהוּ, עֲנֵה כְסִיל בְּדָבָר שֶׁאִם לֹא תַעֲנֵהוּ יִהְיֶה חָכָם בְּעֵינָיו:",2,0],[26,6,"מְקַצֶּה רַגְלַיִם חָמָס שׁוֹתֶה. מִי שֶׁשּׁוֹלֵחַ דְּבָרִים בְּיַד כְּסִיל הוּא מְקַצֶּה רַגְלֵי שְׁלוּחִים הַרְבֵּה, לַחֲזוֹר וְלִשְׁלֹחַ לְתַקֵּן מַה שֶּׁעִוֵּת הָרִאשׁוֹן, אֲשֶׁר שְׁלָחוֹ בַּתְּחִלָּה; וְשׁוֹתֶה חָמָס. שֶׁחֲבֵרוֹ זוֹעֵף עָלָיו עַל שְׁלִיחוּת הַכְּסִיל:",1,0],[26,7,"דַּלְיוּ שׁוֹקַיִם מִפִּסֵּחַ. גָּבְהוּ, כְּמוֹ ״דָּלּוּ עֵינַי״ (ישעיהו לח:יד); הַשּׁוֹקַיִם שֶׁל כָּל אָדָם נִרְאִין לַפִּסֵּחַ גְּבוֹהִים מִמֶּנּוּ. וְדָבָר זֶה מָשָׁל בְּפִי כְסִיל, הָאוֹמֵר אוֹתוֹ עַל לִמּוּד הַחָכְמָה: אֵיךְ אָנוּ בָּאִים לִלְמֹד הַחָכְמָה? נִפְלָאָה וּגְבוֹהָה הִיא מִמֶּנּוּ! הַמָּשָׁל אוֹמֵר: דַּלְיוּ שׁוֹקַיִם מִפִּסֵּחַ:",1,0],[26,8,"בְּמַרְגֵּמָה. פְרוֹנְדוֹלָ״א בְּלַעַ״ז, שֶׁאֶבֶן שֶׁצּוֹרְרִין בּוֹ לֹא לְהִתְקַיֵּם הִיא שָׁם, שֶׁעוֹמֶדֶת לְהִזָּרֵק. כָּךְ הַנּוֹתֵן לִכְסִיל כָּבוֹד אֵינוֹ שֶׁל קַיָּמָא. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה דָּרְשׁוּ (חולין קלג.) עַל הַמְּלַמֵּד תּוֹרָה לְתַלְמִיד שֶׁאֵינוֹ הָגוּן, שֶׁהוּא כְּזוֹרֵק אֶבֶן לְמַרְקוּלִיס:",1,0],[26,9,"חוֹחַ עָלָה בְיַד שִׁכּוֹר. כְּחוֹחַ שֶׁהוּא נִדְבָּק בְּיַד שִׁכּוֹר, כֵּן הַמָּשָׁל הָאָמוּר לְמַטָּה (משלי כו:י) נִדְבָּק בְּפִי הַכְּסִיל לִהְיוֹת לָהֶם לְחוֹחַ וּלְקוֹץ מַכְאִיב. וּמַהוּ הַמָּשָׁל?",1,0],[26,10,"רַב מְחוֹלֵל כֹּל. הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הַכֹּל וְדָן אֶת הַכֹּל; כַּכְּסִיל כֶּחָכָם, אֵין אָנוּ צְרִיכִין לְשׁוּם חָכְמָה:",1,0],[26,10,"וְשׂוֹכֵר כְּסִיל. לֹא כְּבָשָׂר וָדָם שֶׁלֹּא יִשְׂכֹּר אֶלָּא פּוֹעֲלִים בְּקִיאִים וְלֹא יִשְׂכֹּר אֶלָּא הָעוֹסְקִים בִּמְלַאכְתּוֹ, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא מְחוֹלֵל כֹּל וְשׂוֹכֵר הַכְּסִילִים וְשׂוֹכֵר עוֹבֵר דְּרָכִים הַבַּטְלָנִים מִכָּל מְלָאכָה. וּמִדְרַשׁ אַגָּדָה: וְשׂוֹכֵר כְּסִיל מִלְּשׁוֹן ״וַיִּסָּכְרוּ מַעְיְנוֹת תְּהוֹם״ (בראשית ח:ב), וּלְשׁוֹן ״עֹשֵׂי שֶׂכֶר״ (ישעיהו יט:י): הַקָּדוֹשׁ בָּרוּךְ הוּא סוֹכֵר מַזַּל כְּסִיל הַמְשַׁמֵּשׁ בִּימוֹת הַחַמָּה מִתִּשְׁרֵי וְאֵילָךְ, וּמֵאָז הוּא סוֹכֵר וְסוֹגֵר כָּל עוֹבְרֵי הַיָּם מִלֵּילֵךְ בּוֹ עַד הַפֶּסַח. וּבְדִבְרֵי רַבִּי מֹשֶׁה רָאִיתִי: רַב מְחוֹלֵל כֹּל עָשִׁיר יֵשׁ לוֹ פְּעֻלּוֹת הַרְבֵּה, וְאִם שׂוֹכֵר כְּסִיל בִּמְלַאכְתּוֹ הִנֵּה הוּא כְּשׂוֹכֵר כָּל עוֹבְרֵי דֶרֶךְ שֶׁרוֹאִין בְּקִלְקוּל הַמְּלָאכָה, לְהוֹרוֹת אֵיךְ יִתָּכֵן וְאֵיךְ יֵשׁ לוֹ לִפְעֹל; וְדָבָר רֵיק הוּא, וְאֵינוֹ עִנְיָן כָּאן:",2,0],[26,15,"בַּצַּלָּחַת. בְּיוֹרָה חַמָּה נוֹתֵן יָדוֹ, מִפְּנֵי הַקֹּר:",1,0],[26,16,"מְשִׁיבֵי טָעַם. חֲכָמִים:",1,0],[26,17,"מַחֲזִיק בְּאָזְנֵי כָלֶב. הָעוֹבֵר לְהִתְעַבֵּר עַל רִיב לֹא לוֹ הֲרֵי הוּא כְּאוֹחֵז בְּאָזְנֵי כָּלֶב, הַגּוֹרֵם שֶׁיִּשְּׁכֶנּוּ עַל חִנָּם:",1,0],[26,18,"כְּמִתְלַהְלֵהַּ. כְּמִתְיַגֵּעַ לִירוֹת זִיקִים שֶׁל אֵשׁ, כְּמוֹ ״וּבְזִיקוֹת בְּעַרְתֶּם״ (ישעיה נ:יא), מִלְּשׁוֹן ׳זִיקוּקִים דִּינוּר׳ (ברכות נח:). דָּבָר אַחֵר: זִיקִים. ׳פְרוֹנְזוֹלָ״שׁ׳, מִלְּשׁוֹן ״אַבְנֵי קָלַע״ (זכריה ט:טו), וְכֵן בַּגְּמָרָא (בבא מציעא צד.): זִיקְתָא פְּסִיק לָן; וְיוֹרֶה חִצִּים וָמָוֶת:",1,0],[26,19,"כֵּן אִישׁ רִמָּה. מְפַתֶּה וּמֵסִית אֶת חֲבֵירוֹ מִדַּרְכֵי חַיִּים לְדַרְכֵי מָוֶת, וּכְשֶׁחֲבֵירוֹ מַרְגִּישׁ שֶׁהוּא מַתְעֶה אוֹתוֹ, אוֹמֵר: מְצַחֵק אָנִי (בראשית רבה נג,יא):",1,0],[26,20,"בְּאֶפֶס עֵצִים. כְּלוֹמַר שְׁנֵי דְבָרִים אֵלּוּ שָׁוִין: כְּשֵׁם שֶׁבְּאֶפֶס עֵצִים תִּכְבֶּה אֵשׁ, כָּךְ בְּאֵין נִרְגָּן שֶׁל לָשׁוֹן הָרָע הַמְסַכְסֵךְ בַּעֲלֵי רִיב, יִשְׁתֹּק מָדוֹן:",1,0],[26,21,"פֶּחָם לְגֶחָלִים וְעֵצִים לְאֵשׁ. פֶּחָם שֶׁל אֵשׁ עָשׂוּי לְהַבְעִיר גֶּחָלִים עֲמוּמוֹת וְעֵצִים עֲשׂוּיִן לְהַסִּיק אֵשׁ, וְאִישׁ מָדוֹן לְחַרְחַר רִיב:",1,0],[26,22,"כְּמִתְלַהֲמִים. לְשׁוֹן מִתְלַחֲמִים. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה פֵּרְשׁוּ (ספרי דברים כד) כְּמִתְלַהֲמִים: כְּמֵת לָהֶם. דִּבְרֵי הַמְרַגְּלִים הָיוּ לָהֶם לְמִיתָה:",1,0],[26,22,"חַדְרֵי בָטֶן. הִיא מִיתַת הַדְּרוֹקָן:",2,0],[26,23,"מְצֻפֶּה עַל חָרֶשׂ. כְּסִיגֵי כֶסֶף הַמְּדֻבָּקִים עַל הַחֶרֶשׂ שֶׁצּוֹרְפִין אוֹתוֹ בּוֹ, וְהוּא מַבְהִיק כְּאִלּוּ הוּא כֶּסֶף, וְאֵין בּוֹ תּוֹעֶלֶת, כֵּן שְׂפָתַיִם דֹּלְקִים וְלֶב רָע. הָרוֹדְפִים אַחַר הַבְּרִיּוֹת לַהֲסִיתָם בַּחֲלָקוֹת וּמְדַבְּרִים אֶחָד בַּפֶּה וְאֶחָד בַּלֵּב:",1,0],[26,23,"וְלֵב רָע. נִרְאִין כְּאוֹהֲבִין וְהֵם אוֹיְבִים:",2,0],[26,23,"דּוֹלְקִים. כְּמוֹ ״דָּלַקְתָּ אַחֲרָי״ (בראשית לא:לו):",3,0],[26,24,"יִנָּכֵר שׂוֹנֵא. בְּדִבּוּרוֹ מִתְנַכֵּר הַשּׂוֹנֵא, שֶׁלֹּא יַכִּירוּ שֶׁהוּא שׂוֹנֵא. דִישְׁקְנוֹיִישְׁ״ט בְּלַעַ״ז:",1,0],[26,26,"תִּכַּסֶּה שִׂנְאָה. הָעוֹשֶׂה מַעֲשָׂיו בַּמַּחְשָׁךְ וּמְכַסֶּה בְּמַשָּׁאוֹן, שֶׁהוּא חֹשֶׁךְ (  שׁוֹאַת חֹשֶׁךְ), אֶת הַדָּבָר הַשָּׂנאוּי לְהַקָּדוֹשׁ בָּרוּךְ הוּא, סוֹף שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה רָעָתוֹ בְקָהָל, שֶׁיַּכִּירוּ בּוֹ שֶׁהוּא רָשָׁע (סוטה ט.):",1,0],[26,27,"כּוֹרֶה שַׁחַת. כְּגוֹן בִּלְעָם, שֶׁהִשִּׂיא עֵצָה לְבָלָק עַל יִשְׂרָאֵל וְהִפִּיל מֵהֶם עֶשְׂרִים וְאַרְבָּעָה אֶלֶף (במדבר כה:ט), וּבָא לְמִדְיָן לִתְבּוֹעַ שְׂכָרוֹ וְנֶהֱרַג בְּיַד יִשְׂרָאֵל (במדבר לא:ח):",1,0],[26,27,"וְגוֹלֵל. כְּלוֹמַר: סוֹפוֹ שֶׁל הַמַּעֲמִיד מִכְשׁוֹל, שֶׁיִּכָּשֵׁל בּוֹ:",2,0],[26,27,"וְגוֹלֵל אֶבֶן. מְגַלְּלוֹ מִמָּקוֹם לְמָקוֹם, שֶׁיִּכָּשְׁלוּ בּוֹ בְּנֵי אָדָם. וְאַגָּדָה פּוֹתְרוֹ (תנחומא בובר, וירא כח) בַּאֲבִימֶלֶךְ שֶׁהָרַג שִׁבְעִים אֶחָיו עַל אֶבֶן אַחַת, וְסוֹף מֵת בָּאֶבֶן, שֶׁנֶּאֱמַר ״וַתַּשְׁלֵךְ אִשָּׁה אַחַת פֶּלַח רֶכֶב וַתָּרִץ גֻּלְגָּלְתּוֹ וְגוֹ׳״ (שופטים ט:נג):",3,0],[26,28,"יִשְׂנָא דַכָּיו. מִי שֶׁמְּקַבֵּל לָשׁוֹן הָרָע שׂוֹנֵא אֶת הַנִּדְכָּאִים תַּחְתָּיו, שֶׁכֵּן עַל לָשׁוֹן הָרָע רָדַף שָׁאוּל לְדָוִד וְהָרַג נוֹב (שמואל א כב:יח-יט):",1,0],[26,28,"וּפֶה חָלָק. פֶּה שֶׁל חֲלַקְלַקּוּת:",2,0],[26,28,"יַעֲשֶׂה מִדְחֶה. עוֹשֶׂה דִּיחוּי, שֶׁדּוֹחֶה אֶת מְקַבְּלוֹ מֵעַל הַקָּדוֹשׁ בָּרוּךְ הוּא:",3,0],[27,1,"אַל תִּתְהַלֵּל. אַל תִּתְפָּאֵר עַכְשָׁיו בְּדָבָר שֶׁעָתִיד לִהְיוֹת לְיוֹם מָחָר:",1,0],[27,1,"כִּי לֹא תֵדַע מַה יֵּלֶד יוֹם. שֶׁמָּא הַיּוֹם יִוָּלֵד שׁוּם רָעָה, שֶׁיְּבַטֵּל מַחְשְׁבוֹת מָחָר:",2,0],[27,3,"וְנֵטֶל. מַשָּׂא:",1,0],[27,3,"וְכַעַס אֱוִיל. שֶׁהָאֱוִיל מַכְעִיס לְהַקָּדוֹשׁ בָּרוּךְ הוּא, גּוֹרֵם לְהָבִיא כַּעַס לָעוֹלָם:",2,0],[27,4,"וְשֶׁטֶף אָף וּמִי יַעֲמֹד. לִפְנֵי קִנְאָתוֹ שֶׁל קַנָּא וְנַקָּם:",1,0],[27,6,"וְנַעְתָּרוֹת. לְשׁוֹן גֹּדֶל, כְּמוֹ ״הַעְתַּרְתֶּם עָלַי״ (יחזקאל לה:יג):",1,0],[27,7,"תָּבוּס נֹפֶת. תִּרְמוֹס בְּרֶגֶל, כְּמוֹ ״נָבוּס קָמֵינוּ״ (תהלים מד:ו):",1,0],[27,7,"כָּל־מַר מָתוֹק. כָּל דָּבָר מַר, מָתוֹק לָהּ. וְיֵשׁ לְפוֹתְרוֹ בְּתַלְמוּד תּוֹרָה: הַמַּרְאֶה אֶת עַצְמוֹ כְּשָׂבֵעַ, שֶׁאֵינוֹ מִתְאַוֶּה לְדִבְרֵי תוֹרָה לְתַאֲוַת נֶפֶשׁ, תָּבוּס נֹפֶת. אַף הַטְּעָמִים הַמְיֻשָּׁבִים עַל הַלֵּב אֵינָם חֲשׁוּבִים עָלָיו; וְהַמִּתְאַוֶּה לָהּ, אֲפִלּוּ דְּבָרִים הַבָּאִים לוֹ בִּמְרִירוּת וּבִיגִיעָה הֵם מְתוּקִים לוֹ:",2,0],[27,8,"נוֹדֶדֶת מִן קִנָּהּ. שֶׁהוֹלֶכֶת וּמִטַּלְטֶלֶת, כֵּן הָאִישׁ הַנּוֹדֵד מִמְּקוֹמוֹ. תַּלְמִיד חָכָם הַנּוֹדֵד מִן הַלִּמּוּד, מִלַּחֲזֹר עַל גִּרְסָתוֹ:",1,0],[27,9,"שֶׁמֶן וּקְטֹרֶת. רֵיחַ שֶׁמֶן אֲפַרְסְמוֹן וְרֵיחַ קְטֹרֶת מְשַׂמְּחִין לֵב:",1,0],[27,9,"וּמֶתֶק רֵעֵהוּ מֵעֲצַת נָפֶשׁ. מִי שֶׁחֲבֵרוֹ מְקָרְבוֹ וּמְמַתֵּק לוֹ בִּדְבָרָיו, הוּא טוֹב מִמַּה שֶׁנַּפְשׁוֹ יוֹעַצְתּוֹ. דָּבָר אַחֵר: וּמֶתֶק רֵעֵהוּ הַמַּכְשִׁיר מַעֲשָׂיו, שֶׁהֵן מְתוּקִין לְהַקָּדוֹשׁ בָּרוּךְ הוּא, טוֹב לוֹ מִמַּה שֶׁהוּא מְמַלֵּא תַּאֲוַת לִבּוֹ:",2,0],[27,10,"רֵעֲךָ. וְרֵעַ אָבִיךָ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא רֵעַ לְיִשְׂרָאֵל, וְרֵעַ אָבִיךָ שֶׁחִיבֵּב אֶת אֲבוֹתֶיךָ:",1,0],[27,10,"אַל תַּעֲזֹב. אִם עָזַבְתָּ, יָבֹא עָלֶיךָ פֻּרְעָנוּת:",2,0],[27,10,"וּבֵית אָחִיךָ. אַל תִּבְטַח בִּבְנֵי עֵשָׂו וְיִשְׁמָעֵאל שֶׁיְּקָרְבוּךָ. מָצִינוּ (תנחומא, יתרו ה): כְּשֶׁגָּלוּ יִשְׂרָאֵל לְבָבֶל הָיוּ אוֹמְרִים לְמוֹלִיכֵיהֶם בְּקוֹלָר: בְּבַקָּשָׁה מִכֶּם, הוֹלִיכוּנוּ בְּדֶרֶךְ אַחֵינוּ בְּנֵי עֵשָׂו וְיִשְׁמָעֵאל, וְהָיוּ בְּנֵי יִשְׁמָעֵאל יוֹצְאִים לִקְרָאתָם וּמְקַדְּמִין אוֹתָם בְּמִינֵי מְלוּחִים וְנוֹדוֹת נְפוּחִים:",3,0],[27,10,"מֵאָח רָחוֹק. טוֹב שֶׁיִּשְׁכּוֹן בֵּינֵיכֶם הַקָּרוֹב לְקוֹרְאָיו (תהלים קמה:יח), מִשֶּׁתָּבוֹאוּ אֵצֶל אָח שֶׁנִּתְרַחֵק, לֵאמֹר ״יִקְרְבוּ יְמֵי אֵבֶל אָבִי וְגוֹ׳״ (בראשית כז:מא):",4,0],[27,11,"חֲכַם בְּנִי. הִתְחַכֵּם בְּנִי:",1,0],[27,11,"וְשַׂמַּח לִבִּי. וּתְהֵא לִבִּי שָׂמֵחַ בְּךָ:",2,0],[27,12,"עָרוּם רָאָה רָעָה. רוֹאֶה פֻּרְעָנוּת הַבָּאָה עַל הָאָרֶץ וְנִסְתָּר הֵימֶנָּה, שֶׁמָּשַׁךְ יָדוֹ מִן הָעֲבֵירָה. וּפְתָאיִם לֹא נִסְתְּרוּ אֶלָּא עָבְרוּ בְּדֶרֶךְ רָעָה:",1,0],[27,12,"וְנֶעֱנָשׁוּ. וְנִפְסְדוּ:",2,0],[27,13,"כִּי עָרַב זָר. אָדָם שֶׁנַּעֲשָׂה עָרֵב, גּוֹרֵם שֶׁאָמַר הַדַּיָּן לַמַּלְוֶה: קַח בִּגְדוֹ! (בבא מציעא קטו.):",1,0],[27,14,"מְבָרֵךְ רֵעֵהוּ. יֵשׁ מְשַׁבֵּחַ אֶת חֲבֵירוֹ יוֹם יוֹם, וְהַבְּרָכָה נֶהֱפֶכֶת לִקְלָלָה, שֶׁאוֹמְרִים עָלָיו שֶׁהוּא וַתְרָן בְּמָמוֹנוֹ וְעָשִׁיר, וְהַכֹּל בָּאִין וְשׁוֹאֲלִין מִמֶּנּוּ, וְהַמַּלְכוּת מִתְגָּרֶת בּוֹ לִגְבּוֹת מָמוֹן. כָּךְ נִדְרַשׁ בְּמַסֶּכֶת עֲרָכִין (ערכין טז.). וְעוֹד יֵשׁ בְּמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, בלק כד): כְּנֶגֶד בִּלְעָם שֶׁהָיָה מְבָרֵךְ אֶת יִשְׂרָאֵל בְּקוֹל רָם, שֶׁנֶּאֱמַר ״וַיִּשָּׂא מְשָׁלוֹ וְגוֹ׳״ (במדבר כג:ז), לְשׁוֹן נְשִׂיאוּת קוֹל, וְסוֹפוֹ יָעַץ לְהַחֲטִיאָם:",1,0],[27,15,"דֶּלֶף טוֹרֵד. גֶּשֶׁם הַנּוֹטֵף מִן הַגַּג לְתוֹךְ הַבַּיִת וְטוֹרֵד אֶת בְּנֵי הַבַּיִת:",1,0],[27,15,"בְּיוֹם סַגְרִיר. יוֹם הַגֶּשֶׁם, שֶׁהַכֹּל נִסְגָּרִים בְּבָתֵּיהֶם:",2,0],[27,15,"וְאֵשֶׁת מְדִינִים נִשְׁתָּוָה. שְׁנֵיהֶם שָׁוִין (יבמות סג:):",3,0],[27,16,"צוֹפְנֶיהָ צָפַן רוּחַ. מִי שֶׁסָּבוּר לְשָׁמְרָהּ מִתְּזְנוּתֶיהָ, צְפוּנַת רוּחַ הוּא; כְּשֵׁם שֶׁאִי אֶפְשָׁר לִצְפֹּן הָרוּחַ, כֵּן הִיא, לֹא תִצָּפֵנֶה:",1,0],[27,16,"וְשֶׁמֶן יְמִינוֹ יִקְרָא. קוֹרֵא הוּא הַצָּרַעַת לָבוֹא עָלָיו עַד שֶׁיְּגָרְשֶׁנָּה, כַּמְּצֹרָע הַמִּטַּהֵר בְּשֶׁמֶן בְּבֹהֶן יָדוֹ הַיְמָנִית (ויקרא יד:יז):",2,0],[27,17,"יַחַד פְּנֵי רֵעֵהוּ. יַחַד תַּלְמִידֵי חֲכָמִים מְחַדְּדִין זֶה לָזֶה בַּהֲלָכָה (תענית ז.):",1,0],[27,18,"יֹאכַל פִּרְיָהּ. וְכֵן שׁוֹמֵר אֲדוֹנָיו יְכֻבָּד, וְיֹאכַל פְּרִי מַעֲלָלָיו:",1,0],[27,19,"כַּמַּיִם. הַלָּלוּ הַפָּנִים שֶׁאַתָּה מַרְאֶה לְתוֹכָן, הֵן מַרְאוֹת לְךָ:",1,0],[27,19,"כֵּן לֵב הָאָדָם לָאָדָם. חֲבֵרוֹ, לְפִי מַה שֶּׁאָדָם יוֹדֵעַ שֶׁחֲבֵרוֹ אוֹהֲבוֹ, כֵּן הוּא מַרְאֶה לוֹ פָּנִים:",2,0],[27,20,"שְׁאוֹל וַאֲבַדֹּה. לֹא תִשְׂבַּעְנָה מִלְּקַבֵּל אֶת הָרְשָׁעִים לְתוֹכָם, כְּשֵׁם שֶׁעֵינֵי הָאָדָם רָשָׁע לֹא תִשְׂבַּעְנָה מִלָּשׁוּט אַחַר יֵצֶר הָרָע, מִלְּמַלְּאוֹת תַּאֲוָתוֹ:",1,0],[27,21,"מַצְרֵף. כְּלִי עָשׂוּי לְצָרֵף כֶּסֶף וְהַכּוּר עָשׂוּי לִבְחוֹן זָהָב, וְאִישׁ נִצְרָף וּמִתְחַשֵּׁב לְפִי מַהֲלָלוֹ. עַל יְדֵי שֶׁהַבְּרִיּוֹת מְהַלְּלוֹת אוֹתוֹ בְּמַעֲשָׂיו הַטּוֹבִים, נִבְחָן לָרַבִּים, אִם טוֹב אִם רַע:",1,0],[27,22,"הָרִיפוֹת. חִטִּים הַנִּדּוֹכִים בַּמַּכְתֵּשׁ:",1,0],[27,22,"מַכְתֵּשׁ. אֲסִיתָא (חולין נב.), מוֹרְטִיוֹ״ר בְּלַעַ״ז:",2,0],[27,22,"בַּעֱלִי. הוּא בּוּכְנָא, פּוֹלִי״ן מוֹרְטְר״וֹ בְּלַעַ״ז. עַל שֵׁם שֶׁמַּעֲלִין אוֹתוֹ וּמַכִּין בּוֹ תָּמִיד נִקְרָא עֱלִי:",3,0],[27,23,"פְּנֵי צֹאנֶךָ. אַל יֵקַלּוּ בְּעֵינֶיךָ לְהִתְבּוֹנֵן בָּם תָּמִיד מַה הֵם צְרִיכִים:",1,0],[27,24,"כִּי לֹא לְעוֹלָם חֹסֶן. שֶׁאִם אַתָּה עָשִׁיר בְּכֶסֶף וּבְזָהָב, שֶׁמָּא לֹא יִתְקַיֵּם לְעוֹלָם. לְכָךְ אַל תְּבַזֶּה דְּבָרִים קְטַנִּים שֶׁלְּךָ:",1,0],[27,25,"גָּלָה חָצִיר. כְּשֶׁגָּלָה הֶחָצִיר בִּימֵי נִיסָן וְיִרְאָה הַדֶּשֶׁא וְנֶאֶסְפוּ עֲשָׂבִים לִצְמֹחַ, אָז יֵיטִיב לְךָ, שֶׁיִּהְיוּ גִּזּוֹתֵיהֶם שֶׁל כְּבָשִׂים לִלְבוּשֶׁךָ:",1,0],[27,26,"וּמְחִיר שָׂדֶה. יִשְׁווּ לְךָ הָעַתּוּדִים, כִּי תֹּאכַל הַבָּשָׂר וְתִמְכֹּר הָעוֹרוֹת:",1,0],[27,27,"וְדֵי. פַּרְנָסָתְךָ:",1,0],[27,27,"לְלַחְמְךָ וּלְלֶחֶם בֵּיתֶךָ. תִּסְתַּפֵּק בַּחֲלֵב הָעִזִּים. הֲרֵי מְלִיצָתוֹ. וְהַמָּשָׁל כֵּן הוּא: פְּנֵי צֹאנְךָ – הָרַב הַמִּתְמַנֶּה עַל הַצִּבּוּר, יִשָּׂאֵם בְּחֵיקוֹ וִינַהֲלֵם לְאַט (ישעיהו מ:יא), כִּי לֹא לְעוֹלָם חֹסֶן, וּבָזֹאת יֹאכַל פֵּרוֹת, וְהַקֶּרֶן קַיֶּמֶת:",2,0],[27,27,"גָּלָה חָצִיר. כְּשֶׁיִּתְפַּשְּׁטוּ שְׁמוּעוֹתָיו וְתִגְדַּל הַתּוֹרָה עַל יָדוֹ, אָז יִהְיוּ הַכְּבָשִׂים הָאֵלֶּה לְבוּשׁוֹ, יִהְיוּ הַתַּלְמִידִים לוֹ לְשֵׁם וּלְבוּשׁ הוֹד וְהָדָר:",3,0],[28,1,"נָסוּ וְאֵין רוֹדֵף רָשָׁע. נָסוּ הָרְשָׁעִים כְּשֶׁיָּבֹא אֵידָם וְיִפְּלוּ בְּדָבָר קַל מֵאֵין רוֹדֵף:",1,0],[28,1,"וְצַדִּיקִים. אַמִּיץ לִבָּם (עמוס ב:טז) בְּהַקָּדוֹשׁ בָּרוּךְ הוּא כִּכְפִיר אֲשֶׁר יִבְטַח בִּגְבוּרָתוֹ:",2,0],[28,2,"בְּפֶשַׁע אֶרֶץ רַבִּים שָׂרֶיהָ. שֶׁזֶּהוּ פֻּרְעָנוּת לָאָרֶץ, בִּהְיוֹת שָׂרֶיהָ רַבִּים הָרוֹדְפִים רַק אַחַר בִּצְעָם:",1,0],[28,2,"וּבְאָדָם מֵבִין. וּבִשְׁבִיל אָדָם מֵבִין יִתְאָרֵךְ הַפּוּרְעָנוּת מִלָּבוֹא:",2,0],[28,3,"גֶּבֶר רָשׁ. דַּיָּן עַם הָאָרֶץ:",1,0],[28,3,"עוֹשֵׁק דַּלִּים. בְּדִין עַל שֶׁאֵינוֹ מָתוּן בְּדִין, הֲרֵי הוּא כְּמָטָר הַסּוֹחֵף אֶת הַשָּׂדֶה וְאֵין עוֹשֶׂה פֵּרוֹת:",2,0],[28,3,"סוֹחֵף. שׁוֹטֵף, וּבַמִּשְׁנָה (כתובות ז,ח): ״נִסְתַּחֲפָה שָׂדֵהוּ״, וְכֵן ״נִסְחַף אַבִּירֶיךָ״ (ירמיהו מו:טו) – נִשְׁטְפוּ וּמָעֲדוּ וְכָשְׁלוּ:",3,0],[28,5,"אַנְשֵׁי רָע לֹא יָבִינוּ מִשְׁפָּט. אֵינָם מְשִׂימִים לֵב לְפוּרְעָנִיּוֹת הָעֲתִידוֹת, שֶׁיִּתְבּוֹנְנוּ בָּהּ וְיָשׁוּבוּ מִדַּרְכָּם וְיִנָּצְלוּ:",1,0],[28,5,"וּמְבַקְשֵׁי ה׳ יָבִינוּ כֹל. טוֹבָה וְרָעָה. מִשְׁפָּט. יוֹשְׁטִיצָ״א בְּלַעַ״ז; כָּךְ פֵּרֵשׁ רַבִּי תַּנְחוּמָא (תנחומא, בראשית לז) עַל דּוֹר הַמַּבּוּל:",2,0],[28,6,"טוֹב רָשׁ. אַף עָנִי שֶׁבַּתּוֹרָה:",1,0],[28,6,"וְהוֹלֵךְ בְּתֻמּוֹ. בְּמַעֲשִׂים טוֹבִים:",2,0],[28,7,"וְרוֹעֶה זוֹלְלִים. מְחַבֵּר לוֹ זוֹלְלִים, וְהוּא לְשׁוֹן רֵעִים:",1,0],[28,8,"מַרְבֶּה הוֹנוֹ בְּנֶשֶׁךְ וְתַרְבִּית לְחוֹנֵן דַּלִּים. הָרְשׁוּת שׁוֹמְעִין עָלָיו שֶׁהוּא מִתְעַשֵּׁר בְּלֹא מִשְׁפָּט, וְנוֹטְלִין מָמוֹנוֹ, וּבוֹנִין בּוֹ גְּשָׁרִים וּמְתַקְּנִין בּוֹ הַדְּרָכִים, וְזֶהוּ חֲנִינַת דַּלִּים. כָּךְ דְּרָשׁוֹ רַבִּי תַּנְחוּמָא (תנחומא, משפטים ה):",1,0],[28,10,"בִּשְׁחוּתוֹ. מִלְּשׁוֹן שַׁחַת:",1,0],[28,11,"אִישׁ עָשִׁיר וְדַל מֵבִין. כְּנֶגֶד רַב וְתַלְמִיד הוּא מְדַבֵּר, שֶׁהַתַּלְמִיד חוֹקֵר וְעַל יָדוֹ הָרַב מִתְחַכֵּם:",1,0],[28,12,"יְחֻפַּשׂ אָדָם. יִתְחַפֵּשׂ בְּכָל מִינֵי עֲלִילוֹת:",1,0],[28,13,"וּמוֹדֶה וְעוֹזֵב. מוֹדֶה פְּשָׁעָיו וְעוֹזְבָם מִשּׁוּב בָּם עוֹד:",1,0],[28,14,"מְפַחֵד תָּמִיד. דּוֹאֵג מֵעֹנֶשׁ, וּבְכָךְ מִתְרַחֵק מֵעֲבֵירָה:",1,0],[28,15,"אֲרִי נוֹהֵם. הוּא לָהֶם:",1,0],[28,15,"וְדֹב שׁוֹקֵק. נְהִימָה לַאֲרִי וּשְׁקִיקָה לַדֹּב, שְׁנֵיהֶם לְשׁוֹן צְעָקָה:",2,0],[28,16,"חֲסַר תְּבוּנוֹת. מִתּוֹךְ שֶׁהוּא חֲסַר תְּבוּנָה הוּא רַב מַעֲשַׁקּוֹת, כִּי אֵינוֹ נוֹתֵן לֵב עַל חַיָּיו וּמַרְבֶּה לַעֲשֹׁק; שֶׁהֲרֵי הַשׂוֹנֵא בֶצַע יַאֲרִיךְ יָמִים:",1,0],[28,17,"אָדָם עָשׁוּק בְּדַם נָפֶשׁ. (שֶׁיֵּשׁ עָלָיו עֹשֶׁק דָּם) הוּא הַמַּחֲטִיא אֶת חֲבֵרוֹ וְאָבְדָה נַפְשׁוֹ עַל יָדוֹ:",1,0],[28,17,"עַד בּוֹר יָנוּס. עַד יוֹם מוֹתוֹ יָנוּס לְעֶזְרָה, שֶׁיִּתְכַּפֵּר לוֹ:",2,0],[28,17,"וְאַל יִתְמְכוּ בוֹ. מִשָּׁמַיִם לְהַסְפִּיק בְּיָדוֹ לָשׁוּב, שֶׁלֹּא יְהֵא הוּא בְּגַן עֵדֶן וְתַלְמִידוֹ בְּגֵיהִנֹּם. כָּךְ נִדְרַשׁ בְּמַסֶּכֶת יוֹמָא (יומא פז.):",3,0],[28,18,"יִפּוֹל בְּאֶחָת. בְּרָעָה אַחַת, וְאֵין תְּקוּמָה לְמַפַּלְתּוֹ:",1,0],[28,19,"יִשְׂבַּע רִישׁ. עֲנִיּוּת:",1,0],[28,20,"אִישׁ אֱמוּנוֹת. הַנּוֹתֵן מַעַשְׂרוֹתָיו בֶּאֱמוּנָה, שֶׁאֵין עֵד בַּדָּבָר אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, רוֹאֶה וּמַרְבֶּה לוֹ בְּרָכָה:",1,0],[28,20,"וְאָץ לְהַעֲשִׁיר. דּוֹחֵק הַשָּׁעָה לְהִתְעַשֵּׁר בְּשֶׁל עֲנִיִּים:",2,0],[28,21,"יִפְשַׁע גָּבֶר. הַמַּטֶּה מִשְׁפָּט:",1,0],[28,22,"נִבְהָל לַהוֹן. מְמַהֵר לְהַרְבּוֹת הוֹן וְגוֹזֵל תְּרוּמוֹתָיו וּמַעַשְׂרוֹתָיו (תנחומא, בהר א):",1,0],[28,22,"כִּי חֶסֶר יְבוֹאֶנּוּ. חִסָּרוֹן יָבֹא לוֹ, שֶׁהַמְּאֵרָה מִשְׁתַּלַּחַת בְּמַעֲשֵׂי יָדָיו:",2,0],[28,23,"מוֹכִיחַ אָדָם וְגוֹ׳. עַל עֲבֵירוֹת שֶׁבְּיָדוֹ וּמַפְרִישׁוֹ מֵהֶם:",1,0],[28,23,"אַחֲרַי חֵן. לְאַחַר זְמַן חֵן יִמְצָא בְּעֵינָיו יוֹתֵר מִמַּחֲלִיק לָשׁוֹן. מָצִינוּ בִּבְרֵאשִׁית רַבָּה (בראשית רבה מד:ה): כָּל מָקוֹם שֶׁנֶּאֱמַר ׳אַחֲרֵי׳ אֵינוֹ אֶלָּא מֻפְלָג, ׳אַחַר׳ סָמוּךְ. בְּתַנְחוּמָא (תנחומא, הוספה לפרשת דברים ב) עַל ״אֵלֶּה הַדְּבָרִים״ (דברים א:א): מוֹכִיחַ אָדָם אַחֲרַי, זֶה מֹשֶׁה שֶׁהוֹכִיחַ אֶת יִשְׂרָאֵל אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנִּקְרְאוּ ׳אָדָם׳, שֶׁנֶּאֱמַר ״אָדָם אַתֶּם״ (יחזקאל לד:לא), וְנֶאֱמַר בּוֹ ״כִּי מָצָאתָ חֵן בְּעֵינַי״ (שמות לג:יז); מִמַּחֲלִיק לָשׁוֹן. זֶה בִּלְעָם, הָאוֹמֵר לְיִשְׂרָאֵל דְּבָרִים מְתֻקָּנִים ״מַה טֹּבוּ אֹהָלֶיךָ יַעֲקֹב״ (במדבר כד:ה). מֹשֶׁה מַכְרִיז: ״הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה״ (דברים יא:טז), וּבִלְעָם מַכְרִיז וּמַחֲנִיף: עֲשׂוּ תַּאֲוַתְכֶם וְאֵינוֹ מַקְפִּיד! ״לֹא אִישׁ אֵל וִיכַזֵּב״ (במדבר כג:יט) – בָּאֻמּוֹת, אֲבָל בָּכֶם אוֹמֵר וְלֹא יַעֲשֶׂה (ראה שם). וּשְׁלֹמֹה צָוַח עַל שְׁנֵיהֶם: ״נֶאֱמָנִים פִּצְעֵי אוֹהֵב וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא״ (משלי כז:ו):",2,0],[28,24,"גּוֹזֵל אָבִיו. הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[28,24,"וְאִמּוֹ. כְּנֶסֶת יִשְׂרָאֵל: הַמַּחֲטִיא אֶת הָרַבִּים, שֶׁגּוֹזֵל הַקָּדוֹשׁ בָּרוּךְ הוּא, מַפְרִיד מִמֶּנּוּ בָּנָיו וְגוֹזֵל מֵהֶם טוֹבָה:",2,0],[28,24,"מַשְׁחִית. יָרָבְעָם (סנהדרין קב.):",3,0],[28,25,"רְחַב נֶפֶשׁ. לְהַשִּׂיג כָּל תַּאֲוָתוֹ:",1,0],[28,25,"יְגָרֶה מָדוֹן. מְגָרֶה עָלָיו מִדַּת הַדִּין:",2,0],[28,27,"נוֹתֵן לָרָשׁ. צְדָקָה:",1,0],[28,27,"(אֵין מַחְסוֹר. לְהַרְבּוֹת לוֹ צְדָקָה סא״א). וְכֵן הָרַב שֶׁאֵינוֹ מוֹנֵעַ תּוֹרָה מִפִּי הַתַּלְמִיד:",2,0],[29,1,"מַקְשֶׁה עֹרֶף. מִלִּשְׁמֹעַ:",1,0],[29,1,"פֶּתַע יִשָּׁבֵר. מַהֵר יִשָּׁבֵר:",2,0],[29,3,"וְרוֹעֶה. מְחַבֵּר לוֹ זוֹנוֹת. וְרַבּוֹתֵינוּ אָמְרוּ (עירובין סד.): הָאוֹמֵר שְׁמוּעָה זוֹ נָאָה – אֶשְׁנֶנָּה, וְזוֹ אֵינָהּ נָאָה – לֹא אֶשְׁנֶנָּה. וְסִיּוּעַ בַּמִּקְרָא, שֶׁאֵין ״זוֹנוֹת״ בַּמִּקְרָא מָלֵא אֶלָּא זֶה בִּלְבַד:",1,0],[29,4,"יַעֲמִיד אָרֶץ. אִם שׁוֹפֵט אֱמֶת הוּא, יַעֲמִיד אָרֶץ:",1,0],[29,4,"וְאִישׁ תְּרוּמוֹת. אִישׁ גֵאוּת, שֶׁאֵינוֹ חָשׁ לִהְיוֹת מָתוּן בַּדִּין. וְרַבּוֹתֵינוּ אָמְרוּ (כתובות קה:): אִם הַדַּיָּן דּוֹמֶה לְמִי שֶׁאֵינוֹ צָרִיךְ לִקְנוֹת אוֹהֲבִים וְלִיקַּח שֹׁחַד, הוּא יַעֲמִיד אָרֶץ, וְאִם דּוֹמֶה לְכֹהֵן הַשּׁוֹאֵל תְּרוּמוֹת עַל הַגְּרָנוֹת, הוּא יֶהֶרְסֶנָּה:",2,0],[29,5,"מַחֲלִיק. מְדַבֵּר חֲלָקוֹת:",1,0],[29,6,"בְּפֶשַׁע אִישׁ רָע. יָבֹא מוֹקֵשׁ:",1,0],[29,6,"וְצַדִּיק. שֶׁלֹּא הָלַךְ בִּדְרָכָיו, יָרוּן וְשָׂמֵחַ:",2,0],[29,7,"דִּין דַּלִּים. יִסּוּרֵי דַלִּים וּמַה הֵם צְרִיכִים, וְנוֹתֵן לָהֶם לֵב:",1,0],[29,8,"יָפִיחוּ. יַלְהִיבוּ, כְּלַהֶבֶת אֵשׁ הַנָּפוּחַ בָּרוּחַ:",1,0],[29,9,"אִישׁ חָכָם נִשְׁפָּט. מִתְוַכֵּחַ עִם הָאֱוִיל:",1,0],[29,9,"וְאֵין נָחַת. בֵּין מַרְאֶה לוֹ פָּנִים זְעוּפוֹת בֵּין שֶׁמַּרְאֵהוּ פָּנִים שׂוֹחֲקוֹת, אֵין נַחַת לֹא בָזוֹ וְלֹא בָזוֹ, אֵינוֹ מוֹצֵא קוֹרַת רוּחַ. מָצִינוּ בַאֲמַצְיָה, שֶׁהֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא פָּנִים שׂוֹחֲקוֹת וּמָסַר בְּיָדוֹ אֱדוֹם, וּבְשׁוּבוֹ מֵהַכּוֹת (דברי הימים ב כה:יד) וַיָּבֵא אֶת אֱלֹהֵיהֶם וְלָהֶם הִשְׁתַּחֲוָה. לְאָחָז הֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא פָּנִים זוֹעֲפוֹת וּמְסָרוֹ בְּיַד מַלְכֵי אֲרָם, וַיִּזְבַּח לֵאלֹהֵי דַמֶּשֶׂק כִּי אָמַר אֱלֹהֵי אֲרָם מְעַזְּרִים לָהֶם (דברי הימים ב כח:כג):",2,0],[29,10,"יְבַקְשׁוּ נַפְשׁוֹ. לְשׁוֹן חִבָּה, וְנִרְאֶה שֶׁכֵּן הוּא, כְּמָה שֶׁאָמַר דָּוִד לְאֶבְיָתָר: ״אֲשֶׁר יְבַקֵּשׁ אֶת נַפְשִׁי יְבַקֵּשׁ אֶת נַפְשֶׁךָ״ (שמואל א כב:כג) – מִי שֶׁיִּגְמֹל לִי חֶסֶד יִגְמֹל לְךָ. וְאֵין הַפּוֹתְרִים מוֹדִים לִי:",1,0],[29,11,"בְּאָחוֹר יְשַׁבְּחֶנָּה. כְּשֶׁיּוֹצִיא הַכְּסִיל כָּל רוּחוֹ, בָּא הֶחָכָם וְיַשְׁפִּילֶנּוּ בְּמַעֲנֵה לְשׁוֹנוֹ. וְדוֹמֶה לוֹ ״מַשְׁבִּיחַ שְׁאוֹן יַמִּים״ (תהלים סה:ח); ״בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם״ (תהלים פט:י):",1,0],[29,13,"וְאִישׁ תְּכָכִים. אִישׁ מְזִמּוֹת, בַּעַל תּוֹרָה. וְרַבּוֹתֵינוּ (תמורה טז.; ויקרא רבה לד,ד) פֵּרְשׁוּ: תַּלְמִיד שֶׁאָמַר לָרַב הַשְׁנֵינִי פֶּרֶק אֶחָד, וּמְלַמְּדוֹ:",1,0],[29,15,"וְנַעַר מְשֻׁלָּח. שֶׁשְּׁלָחוֹ אָבִיו לָלֶכֶת בְּדַרְכֵי לִבּוֹ, סוֹפוֹ מֵבִישׁ אִמּוֹ. יִשְׁמָעֵאל, עַל שֶׁהָיָה רָשָׁע, גָּרַם לְשָׂרָה שֶׁאָמְרָה לְאַבְרָהָם ״גָּרֵשׁ אֶת הָאָמָה וְגוֹמֵר״ (בראשית כא:י):",1,0],[29,18,"בְּאֵין חָזוֹן יִפָּרַע עָם. כְּשֶׁגּוֹרְמִין יִשְׂרָאֵל שֶׁהַנְּבוּאָה מִסְתַּלֶּקֶת מֵהֶם, עַל יְדֵי שֶׁהֵם מַלְעִיבִים בַּנְּבִיאִים (דברי הימים ב לו:טז), יִפְרְצוּ בָם פְּרָצוֹת וְיוֹצְאִין לְתַרְבּוּת רָעָה:",1,0],[29,19,"כִּי יָבִין וְאֵין מַעֲנֶה. כֵּיוָן שֶׁרוֹאֵהוּ שֶׁמּוֹכִיחוֹ, שׁוֹתֵק, וְהוּא חוֹזֵר וּמְקַלְקֵל; לְכָךְ צָרִיךְ לְיַסְּרוֹ בְּמַכּוֹת וְעוֹנְשִׁין. וְלֹא דִּבֵּר עַל עֶבֶד מַמָּשׁ, אֶלָּא עַל כָּל הַמַּמְרִים דִּבְרֵי הַשּׁוֹפְטִים:",1,0],[29,20,"אָץ בִּדְבָרָיו. מְמַהֵר וְנִבְהָל לְהָשִׁיב:",1,0],[29,20,"תִּקְוָה לִכְסִיל מִמֶּנּוּ. יֵשׁ לַכְּסִיל תִּקְוָה יוֹתֵר מִמֶּנּוּ:",2,0],[29,21,"מְפַנֵּק מִנֹּעַר עַבְדּוֹ. יֵצֶר הָרָע:",1,0],[29,21,"מָנוֹן. שַׁלִּיט, וְכֵן ״לִפְנֵי שֶׁמֶשׁ יִנּוֹן שְׁמוֹ״ (תהלים עב:יז); וְכֵן כָּל ׳נִין׳ שֶׁבַּמִּקְרָא, שֶׁהַנִּין קָם תַּחַת אָבִיו לִשְׁלוֹט בִּנְכָסָיו:",2,0],[29,22,"אִישׁ אַף יְגָרֶה מָדוֹן. כְּמַשְׁמָעוֹ. מָדוֹן מִדַּת הַדִּין:",1,0],[29,23,"יִתְמֹךְ כָּבוֹד. יִקְרַב אֶל הַכָּבוֹד וְתוֹמֵךְ בּוֹ תָּמִיד:",1,0],[29,24,"אָלָה יִשְׁמַע. שֶׁמַּשְׁבִּיעִין אוֹתוֹ: אִם רָאִיתָ פְּלוֹנִי שֶׁגָּנַב לִי כָּךְ וְכָךְ; וּמִתּוֹךְ שֶׁהוּא חוֹלֵק עִמּוֹ, אֵינוֹ מַגִּיד:",1,0],[29,25,"חֶרְדַּת אָדָם יִתֵּן מוֹקֵשׁ. מְסֹרָס הוּא: מוֹקֵשׁ, עֲבֵרָה, יִתֵּן חֲרָדָה לָאָדָם. דָּבָר אַחֵר: כְּמַשְׁמָעוֹ: מִתּוֹךְ שֶׁאָדָם צַר עַיִן, וְחָרֵד, אִם יַעֲשֶׂה צְדָקָה, יִצְטָרֵךְ אֶל הַבְּרִיּוֹת; חֲרָדָה זוֹ תִּתֵּן לוֹ מוֹקֵשׁ. וְהָרִאשׁוֹן נוֹחַ לִי:",1,0],[29,26,"פְּנֵי מוֹשֵׁל. לָדוּן לְפָנָיו:",1,0],[29,26,"וּמֵה׳ מִשְׁפַּט אִישׁ. אִם יִזְכֶּה אוֹ אִם יִתְחַיֵּב. וּבַמּוֹשְׁלִים דִּבֵּר הַכָּתוּב:",2,0],[29,27,"יְשַׁר דָּרֶךְ. אָדָם שֶׁהוּא יָשָׁר בִּדְרָכָיו:",1,0],[30,1,"אָגוּר בֶּן יָקֶה. דִּבְרֵי שְׁלֹמֹה שֶׁאָגַר אֶת הַבִּינָה וְהֵקִיאָהּ, כָּךְ פֵּרְשׁוּהוּ חֲכָמִים (תנחומא, וארא ה):",1,0],[30,1,"הַמַּשָּׂא. נְבוּאָה זוֹ אָמַר עַל כֵּן:",2,0],[30,1,"נְאֻם הַגֶּבֶר לְאִיתִיאֵל. אָמַר הַגֶּבֶר, זֶה שְׁלֹמֹה, הַמַּשָּׂא הַזֶּה עַל עַצְמוֹ, בִּשְׁבִיל אִיתִיאֵל – עַל שֶׁסָּמַךְ עַל חָכְמָתוֹ לְהַרְבּוֹת זָהָב וְסוּסִים וְנָשִׁים שֶׁהוּזְהַר מִלְּהַרְבּוֹת. וְכֵן אָמַר: אִיתִיאֵל וְאֻכָל, אַרְבֶּה נָשִׁים וְלֹא יָסוּרוּ אֶת לְבָבִי, אַרְבֶּה זָהָב וְלֹא אָסוּר, אַרְבֶּה סוּסִים וְלֹא אָשׁוּב אֶת הָעָם מִצְרַיְמָה (דברים יז:טז-יז):",3,0],[30,1,"לְאִיתִיאֵל וְאֻכָל. בִּשְׁבִיל שֶׁאָמַר: אִתִּי אֵל, וְאוּכַל לַעֲשׂוֹת וְלֹא אֶכָּשֵׁל. לְאִיתִיאֵל, עַל אִיתִיאֵל, כְּמוֹ ״וְאָמַר פַּרְעֹה לִבְנֵי יִשְׂרָאֵל״ (שמות יד:ג) – עַל בְּנֵי יִשְׂרָאֵל:",4,0],[30,2,"כִּי בַעַר אָנֹכִי. עַל שֶׁסָּמַכְתִּי עַל חָכְמָתִי בְּדָבָר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּאַג, שֶׁמָּא יָבוֹא לִידֵי עֲבֵירָה:",1,0],[30,3,"וְלֹא לָמַדְתִּי חָכְמָה. וְלֹא דַעַת קְדוֹשִׁים יָדַעְתִּי, שֶׁגָּרַעְתִּי אוֹ הוֹסַפְתִּי עַל דִּבְרֵי מֹשֶׁה:",1,0],[30,4,"מִי עָלָה שָׁמַיִם. כְּמֹשֶׁה (שמות יט:ג):",1,0],[30,4,"מִי אָסַף רוּחַ. פִּיחַ הַכִּבְשָׁן (שמות ט:י):",2,0],[30,4,"מִי צָרַר מַיִם. ״קָפְאוּ תְהוֹמוֹת, נִצְּבוּ כְמוֹ נֵד״ (שמות טו:ח) בִּתְפִלָּתוֹ שֶׁל מֹשֶׁה:",3,0],[30,4,"מִי הֵקִים. אֶת הַמִּשְׁכָּן, שֶׁבַּהֲקָמָתוֹ נִתְבַּסְּסוּ כָּל אַפְסֵי אָרֶץ. כָּךְ נִדְרַשׁ בַּפְּסִיקְתָּא (פסיקתא רבתי א,ד):",4,0],[30,4,"מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ. אִם תֹּאמַר: כְּבָר הָיָה דֻּגְמָתוֹ, אֱמוֹר: מַה שֵּׁם בְּנוֹ? אֵיזוֹ מִשְׁפָּחָה יָצְאָה מִמֶּנּוּ, וְנֵדַע מִי הוּא?",5,0],[30,4,"כִּי תֵדָע. אִם תֵּדַע מִי הוּא, וְאֵיךְ לֹא יָרֵאתָ לַעֲבֹר עַל דְּבָרָיו?",6,0],[30,5,"כָּל אִמְרַת אֱלוֹהַּ צְרוּפָה. מְזֻקָּקָה, וְלֹא כָתַב דָּבָר שֶׁלֹּא לְצֹרֶךְ, וְהָיָה לִי לִיזָּהֵר:",1,0],[30,6,"פֶּן יוֹכִיחַ בְּךָ וְנִכְזָבְתָּ. יוֹכִיחַ עַל פָּנֶיךָ, שֶׁעַל יְדֵי תוֹסַפְתְּךָ אַתָּה בָּא לִידֵי עֲבֵירָה, וְכָל שֶׁכֵּן אִם תִּגְרַע:",1,0],[30,7,"שְׁתַּיִם שָׁאַלְתִּי מֵאִתָּךְ. עַכְשָׁיו מְדַבֵּר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[30,8,"רֵאשׁ. דַּלּוּת:",1,0],[30,8,"הַטְרִיפֵנִי. לְשׁוֹן מָזוֹן, וְכֵן ״טֶרֶף נָתַן לִירֵאָיו״ (תהלים קיא:ה):",2,0],[30,9,"פֶּן אֶשְׂבַּע. מִתּוֹךְ עֹשֶׁר, וְכִחַשְׁתִּי בַּהַקָּדוֹשׁ בָּרוּךְ הוּא מֵרוֹב גַּאֲוָה. וּמַהוּ הַכְּחָשָׁה?",1,0],[30,9,"וְאָמַרְתִּי מִי ה׳. כְּלוֹמַר: אֵין אֱלֹהִים:",2,0],[30,9,"וְתָפַשְׂתִּי שֵׁם אֱלֹהָי. לְהַרְגִּיל לְהִשָּׁבַע בּוֹ לַשֶּׁקֶר:",3,0],[30,10,"אַל תַּלְשֵׁן עֶבֶד. אַל תִּמְסֹר דִּין עַל אָדָם לִצְעֹק עָלָיו לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וַאֲפִלּוּ הוּא רָשָׁע אֲשֶׁר אָבִיו יְקַלֵּל, וְכָל הַתּוֹעֵבוֹת הָאֲמוּרוֹת כָּאן בּוֹ. וּרְאָיָה לַדָּבָר מֵהוֹשֵׁעַ בֶּן בְּאֵרִי, כִּדְאִיתָא בִּפְסָחִים בְּפֶרֶק ׳הָאִשָּׁה׳ (פסחים פז.), שֶׁהִלְשִׁין אֶת יִשְׂרָאֵל וְאָמַר: הַחֲלִיפֵם בְּאֻמָּה אַחֶרֶת! אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: ״קַח לְךָ אֵשֶׁת זְנוּנִים״ (הושע א:ב):",1,0],[30,13,"דּוֹר מָה רָמוּ עֵינָיו. זֶה גַּסּוּת הָרוּחַ:",1,0],[30,14,"דּוֹר חֲרָבוֹת שִׁנָּיו. הַחִיצוֹנוֹת:",1,0],[30,14,"מְתַלְּעֹתָיו. שִׁנָּיו הַפְּנִימִיּוֹת:",2,0],[30,14,"וּמַאֲכָלוֹת. סַכִּינִים:",3,0],[30,15,"לַעֲלוּקָה. מְנַחֵם פָּתַר לַעֲלוּקָה כְּמַשְׁמָעוֹ, לָמַדְנוּ שֶׁהוּא עֲרָבִי. וְהַפּוֹתְרִים אוֹמְרִים שֶׁהוּא לְשׁוֹן שְׁאוֹל וּמוֹרָד. וְכֵן בְּמִדְרַשׁ תְּהִלִּים לָמַדְנוּ כֵּן, שֶׁפּוֹתֵר שְׁתֵּי בָנוֹת – גַּן עֵדֶן וְגֵיהִנֹּם; זוֹ אוֹמֶרֶת: תְּנוּ לִי צַדִּיקִים, וְזוֹ אוֹמֶרֶת: תְּנוּ לִי רְשָׁעִים:",1,0],[30,15,"אַרְבַּע לֹא אָמְרוּ הוֹן. הַרְבֵּה יֵשׁ לָנוּ:",2,0],[30,16,"וְעֹצֶר רָחַם. תַּשְׁמִישׁ:",1,0],[30,17,"לִיקְּהַת אֵם. לִקְמָטִים הַנִּקְבָּצִים וְנִקְהִין בִּפְנֵי אִמּוֹ, לְשׁוֹן ״יִקְּהַת עַמִּים״ (בראשית מט:י) – קְבוּצַת עַמִּים. וְהַיּוֹ״ד יְסוֹד, כְּמוֹ ״יִפְעַת״ (יחזקאל כח:ז), ״וְיַעֲלַת חֵן״ (משלי ה:יט):",1,0],[30,17,"יִקְּרוּהָ. לְשׁוֹן ״תְּנַקֵּר״ (במדבר טז:יד), ״נִקְרַת הַצּוּר״ (שמות לג:כב), פוריי״ר בְּלַעַ״ז. יָבֹא הָעוֹרֵב שֶׁהוּא אַכְזָרִי עַל בָּנָיו, וְיִקְּרוּהָ, וְלֹא יֹאכְלֶנָּה וְלֹא יֵהָנֶה בָּהּ, וְיָבֹא נֶשֶׁר שֶׁהוּא רַחֲמָנִי עַל בָּנָיו וְיֹאכְלוּהָ וְיֵהָנֶה בָּהּ. הָעוֹרֵב אַכְזָרִי הוּא, כְּמוֹ שֶׁנֶּאֱמַר ״לִבְנֵי עֹרֵב אֲשֶׁר יִקְרָאוּ״ (תהלים קמז:ט), וְהַנֶּשֶׁר רַחֲמָנִי, שֶׁנֶּאֱמַר ״יִשָּׂאֵהוּ עַל אֶבְרָתוֹ״ (דברים לב:יא; ראה תנחומא עקב ב):",2,0],[30,18,"נִפְלְאוּ מִמֶּנִּי. נִכְסוּ מִשֶּׁחָלְפוּ מֵעֵינַי, וְאֵינִי יוֹדֵעַ לְהֵיכָן הָלְכוּ, שֶׁמְּמַהֲרִין לְהִסָּתֵר מִן הָעַיִן:",1,0],[30,20,"וּמָחֲתָה. כּוֹפָה פִּיהָ לְמַטָּה, כְּדִכְתִיב ״כַּאֲשֶׁר יִמְחֶה הַצַּלַּחַת מָחָה וְהָפַךְ עַל פָּנֶיהָ״ (מלכים ב כא:יג):",1,0],[30,20,"אָכְלָה. לָשׁוֹן נְקִיָּה דִּבֵּר הַכָּתוּב (יומא עה.):",2,0],[30,28,"שְׂמָמִית. אַרִינְיָ״א בְּלַעַ״ז:",1,0],[30,28,"בְּיָדַיִם תְּתַפֵּשׂ. בְּיָדָהּ הִיא אוֹחֶזֶת וּמִתְדַּבֶּקֶת בַּכְּתָלִים (בראשית רבה סו,ז):",2,0],[30,29,"מְטִיבֵי צָעַד. הוֹלְכִים וּמַצְלִיחִים בִּגְבוּרָתָם:",1,0],[30,31,"זַרְזִיר מָתְנַיִם אוֹ תָיִשׁ. לֹא יָדַעְתִּי מַהוּ, וּלְפִי הַמַּשְׁמָע הִיא חַיָּה תְּשׁוּשָׁה מָתְנַיִם:",1,0],[30,31,"וּמֶלֶךְ אַלְקוּם. לֹא יָדַעְתִּי מַה הוּא לְפִי פְּשׁוּטוֹ. וּמִדְרַשׁ אַגָּדָה פּוֹתְרִין חָמֵשׁ פָּרָשִׁיּוֹת אֵלּוּ שֶׁל אַרְבַּע דְּבָרִים כְּנֶגֶד אַרְבַּע מַלְכֻיּוֹת, לְפִי שֶׁנִּתְאַמְּצָה מֶמְשַׁלְתָּן עַל יִשְׂרָאֵל בְּעָוֹן שֶׁעָבְרוּ עַל חֲמִשָּׁה חוּמְשֵׁי תּוֹרָה, הִזְכִּירָם חֲמִשָּׁה פְּעָמִים:",2,0],[30,31,"(טז) שְׁאוֹל וְעֹצֶר רָחַם. שְׁאוֹל מַלְכוּת בָּבֶל, שֶׁנֶּאֱמַר בִּנְבוּכַדְנֶצַּר ״הִרְחִיב כַּשְּׁאוֹל נַפְשׁוֹ״ (חבקוק ב:ה). וְעֹצֶר רָחַם זוֹ הִיא מָדַי שֶׁבִּימֵיהֶם עָצְרוּ רַחֲמִים מִיִּשְׂרָאֵל, שֶׁנֶּאֱמַר ״לְהַשְׁמִיד לַהֲרֹג וּלְאַבֵּד״ (אסתר ג:יג):",3,0],[30,31,"אֶרֶץ לֹא שָׂבְעָה מַּיִם. זוֹ יָוָן, שֶׁלֹּא שָׂבְעָה מִלִּגְזֹר גְּזֵרוֹת רָעוֹת עַל יִשְׂרָאֵל:",4,0],[30,31,"וְאֵשׁ לֹא אָמְרָה הוֹן. נֶגֶד עֵשָׂו, שֶׁעָשָׂה בְּחֵמָה בּוֹעֶרֶת עַל יִשְׂרָאֵל, שֶׁאָמְרוּ לְהַשְׁמִיד טַף וְנָשִׁים בְּיוֹם אֶחָד (אסתר ג:יג). וְכֵן:",5,0],[30,31,"(יט) דֶּרֶךְ הַנֶּשֶׁר. זוֹ בָּבֶל, ״הַנֶּשֶׁר הַגָּדוֹל… אֶרֶךְ הָאֵבֶר״ (יחזקאל יז:ג):",6,0],[30,31,"נָחָשׁ. זוֹ מָדַי (דניאל ח:כ):",7,0],[30,31,"דֶּרֶךְ אֳנִיָּה בְלֶב יָם. זוֹ יָוָן, שֶׁהִיא קַלָּה בִּגְזֵרוֹתֶיהָ (משלי ל:יט):",8,0],[30,31,"דֶּרֶךְ גֶּבֶר בְּעַלְמָה. זוֹ פָּרַס שֶׁאָמְרָה: ״לְעוֹלָם אֶהְיֶה גְבֶרֶת״ (ישעיהו מז:ז):",9,0],[30,31,"(כ) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת. זוֹ הָרָעָה גָּרְמָה לָהֶם לִכְנֶסֶת יִשְׂרָאֵל שֶׁנָּאֲפָה בַּעֲבוֹדַת גִּלּוּלִים, וּכְדַאי הוּא הַפּוּרְעָנִיּוֹת לָבוֹא לָהּ:",10,0],[30,31,"וְאָמְרָה לֹא פָעַלְתִּי אָוֶן. כְּדַאֲמַר ״הִנְנִי נִשְׁפָּט אוֹתָךְ עַל אָמְרֵךְ לֹא חָטָאתִי״ (ירמיה ב:לה). [עד כאן לשוֹן רש״י שבמק״ג]:",11,0],[30,31,"(כא) רָגְזָה אֶרֶץ. אֶרֶץ יִשְׂרָאֵל:",12,0],[30,31,"(כב) תַּחַת עֶבֶד. זֶה נְבוּכַדְנֶצַּר שֶׁהָיָה עֶבֶד לִמְרוֹדַךְ בַּלְאֲדָן וְכוֹתֵב אִגְּרוֹתָיו, כְּדִגְרָסִינַן בְּחוּלִין (סנהדרין צו.):",13,0],[30,31,"וְנָבָל כִּי יִשְׂבַּע לָחֶם. זֶה אֲחַשְׁוֵרוֹשׁ שֶׁעָשָׂה מִשְׁתֶּה מֵאָה וּשְׁמוֹנִים יוֹם (אסתר א:ד):",14,0],[30,31,"(כג) שְׂנוּאָה כִּי תִבָּעֵל. כְּנֶגֶד יָוָן:",15,0],[30,31,"וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. זֶה עֵשָׂו, שֶׁהָיָה לוֹ לַעֲבֹד לְיַעֲקֹב וְנֶהְפַּךְ הַדְּבָרִים:",16,0],[30,31,"(כה) הַנְּמָלִים עַם לֹא עָז. זוֹ בָּבֶל, שֶׁנֶּאֱמַר: ״הֵן אֶרֶץ כַּשְׂדִּים זֶה הָעָם לֹא הָיָה״ (ישעיהו כג:יג):",17,0],[30,31,"וַיָּכִינוּ בַקַּיִץ לַחְמָם. נְבוּכַדְנֶצַּר עָשָׂה כָבוֹד אֶחָד לְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּימֵי מְרֹדַךְ בַּלְאֲדָן אֲשֶׁר שָׁלַח סְפָרִים לְחִזְקִיָּהוּ וְכָתַב שָׁם: שְׁלָם לְמַלְכָּא חִזְקִיָּהוּ, שְׁלָם לְקַרְתָּא דִירוּשְׁלֵם, שְׁלָם לֶאֱלָהָא רַבָּא. וּנְבוּכַדְנֶצַּר כּוֹתֵב אִגְּרוֹתָיו הָיָה, וְלֹא הָיָה שָׁם אוֹתוֹ הַיּוֹם; וּכְשֶׁבָּא וְסִפְּרוּ לוֹ מַה שֶּׁעָשׂוּ, אָמַר לָהֶם: אֱלָהָא רַבָּא קְרִיתוּ לֵיהּ וּכְתַבִיתוּ לֵיהּ בְּסוֹף? רָץ אַחַר הַשָּׁלִיחַ וְהֶחֱזִירוֹ. בִּשְׁבִיל אוֹתוֹ מְרוּצָה זָכָה לַמַּלְכוּת; הֲרֵי שֶׁהֵכִין בַּקַּיִץ לַחְמוֹ כְּדֶרֶךְ הַנְּמָלָה (סנהדרין צו.):",18,0],[30,31,"(כו) שְׁפַנִּים עַם לֹא־עָצוּם. זֶה מָדַי וּפָרָס:",19,0],[30,31,"וַיָּשִׂימוּ בַסֶּלַע בֵּיתָם: שֶׁבָּנוּ בֵּית הַמִּקְדָּשׁ:",20,0],[30,31,"(כח) שַׁמָּמִית בְּיָדַיִם תְּתַפֵּשׂ. זֶה עֵשָׂו שֶׁנֶּאֱמַר ״וְהַיָּדַיִם יְדֵי עֵשָׂו״ (בראשית כז:כב):",21,0],[30,31,"בְּהֵיכְלֵי מֶלֶךְ. שֶׁנִּכְנַס לְהֵיכַל מֶלֶךְ וְהֶחֱרִיבוֹ:",22,0],[30,31,"(ל) לַיִשׁ גִּבּוֹר בַּבְּהֵמָה. זֶה נְבוּכַדְנֶצַּר, שֶׁנֶּאֱמַר (ירמיהו ד:ז) ״עָלָה אַרְיֵה מִסֻּבְּכוֹ״:",23,0],[30,31,"זַרְזִיר מָתְנַיִם. זוֹ מָדַי וּפָרַס, שֶׁזֵּרְזוּ מָתְנֵיהֶם וְהָרְגוּ לְבֵלְשַׁצַּר וְנָטְלוּ מַלְכוּת בָּבֶל (דניאל ה:ל):",24,0],[30,31,"אוֹ תָיִשׁ. זֶה יָוָן שֶׁנִּקְרָא תַּיִשׁ, שֶׁנֶּאֱמַר: ״וְהַצָּפִיר הַשָּׂעִיר״ הוּא ״מֶלֶךְ יָוָן״ (דניאל ח:כא):",25,0],[30,31,"וּמֶלֶךְ אַלְקוּם עִמּוֹ. זוֹ אֻמַּת אֲרָם, שֶׁאָמַר ״אֲנִי וְאַפְסִי עוֹד״ (ישעיה מז:ח), אֵין נִצָּב לְעֻמָּתוֹ, אַלְקוּם – אֵין עוֹמֵד עִמּוֹ:",26,0],[30,32,"אִם נָבַלְתָּ בְהִתְנַשֵּׂא. אִם נִתְנַבַּלְתָּ עַל יְדֵי חֲבֵירְךָ שֶׁחֵירְפְךָ (  עַל יְדֵי דַּבּוּרְךָ שֶׁחֵרַפְתָּ וְגִדַּפְתָּ) אֶת עַצְמְךָ, סוֹפְךָ לְהִנָּשֵׂא בַּדָּבָר:",1,0],[30,32,"וְאִם זַמּוֹתָ. בְּלִבְּךָ לְהִתְקוֹטֵט, שִׂים יָד עַל פֶּה וּשְׁתוֹק:",2,0],[30,33,"כִּי מִיץ חָלָב. כִּי כַּאֲשֶׁר תֵּצֵא חֶמְאָה עַל יְדֵי מִיץ חָלָב וְדָם עַל יְדֵי מִיץ הַחוֹטֶם יוֹתֵר מִדַּי, כֵּן יֵצֵא רִיב עַל יְדֵי מִיץ אַפַּיִם שֶׁל כַּעַס. מִיץ סְחִיטָה פרימדור״א בְּלַעַ״ז, כְּמוֹ ״וַיִּמֶץ טַל וְגוֹ׳״ (שופטים ו:לח). וְרַבּוֹתֵינוּ פֵּרְשׁוּ (ברכות סג:): אִם נִבַּלְתָּ עַצְמְךָ עַל דִּבְרֵי תוֹרָה, לִדְרוֹשׁ וְלִשְׁאוֹל סְפֵקוֹתֶיךָ לְרַבְּךָ, וַאֲפִלּוּ נִרְאֵיתָ לוֹ כְּשׁוֹטֶה בְּלֹא לֵב, סוֹפְךָ שֶׁתְּהֵא מְנֻשָּׂא; וְאִם זַמּוֹתָ – אִם שַׂמְתָּ זְמָם עַל פִּיךָ וְחָסַמְתָּ אוֹתוֹ וְלֹא שָׁאַלְתָּ לוֹ הַכֹּל, סוֹפְךָ כְּשֶׁיִּשְׁאָלְךָ דְּבַר הֲלָכָה, תִּתֵּן יָד לַפֶּה וְתֵאָלֵם, שֶׁלֹּא תֵדַע לַעֲנוֹת כְּלוּם בּוֹ. כַּאֲשֶׁר מִיץ חָלָב יוֹצִיא חֶמְאָה, כֵּן מִיץ אַפַּיִם. שֶׁרַבְּךָ כּוֹעֵס בְּךָ שֶׁלֹּא הֲבִינוֹתָ מַהֵר, וְאַתָּה מִתְנַבֵּל עָלֶיהָ – סוֹף יוֹצִיא מִפִּיךָ אַחַר זְמַן הֲלָכוֹת רַבּוֹת וְהוֹרָאוֹת:",1,0],[31,1,"דִּבְרֵי לְמוּאֵל מֶלֶךְ. דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ שֶׁאָמַר לְמוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּלוֹמַר: בִּשְׁבִיל שֶׁהֶעֱוָה כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא. לְמוּאֵל לָאֵל, כְּמוֹ ״לְמוֹ פִי״ (איוב מ:ד). דְּבָרִים לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאָמַר הַמֶּלֶךְ:",1,0],[31,1,"מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ. כְּשֶׁהִתְחַתֵּן עִם בַּת פַּרְעֹה בְּיוֹם חֲנֻכַּת בֵּית הַמִּקְדָּשׁ, וְהִכְנִיסָה לוֹ כַּמָּה מִינֵי כְּלֵי זֶמֶר, וְנֵעוֹר כָּל הַלַּיְלָה, וְיָשַׁן לְמָחֳרָת עַד אַרְבַּע שָׁעוֹת; כִּדְאִיתָא בִּפְסִיקְתָּא (ויקרא רבה יב, ה), וְהָיוּ מַפְתְּחוֹת בֵּית הַמִּקְדָּשׁ תַּחַת מְרַאֲשׁוֹתָיו. וְעַל אוֹתָהּ שָׁעָה שָׁנִינוּ (עדיות ו, א): עַל תָּמִיד שֶׁל שַׁחַר שֶׁקָּרַב בְּאַרְבַּע שָׁעוֹת, וְנִכְנְסָה אִמּוֹ וְהוֹכִיחַתּוּ עַל הַמַּעֲשֶׂה הַזֶּה:",2,0],[31,1,"מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ. מַשָּׂא שֶׁל מָשָׁל שֶׁיִּסְּרַתּוּ אִמּוֹ (סנהדרין ע:):",3,0],[31,2,"מַה בְּרִי. מֶה זֹּאת עָשִׂיתָ, וְהִגַּדְתָּ שֶׁאַתָּה בְּנִי וְלֹא בֶן אָבִיךָ? הַכֹּל יוֹדְעִין שֶׁאָבִיךָ צַדִּיק גָּמוּר הָיָה, וְאִם אַתָּה רָשָׁע, יֹאמְרוּ: אִמּוֹ גָּרְמָה לוֹ:",1,0],[31,2,"בַּר בִּטְנִי. כָּל נְשֵׁי אָבִיךָ, כֵּיוָן שֶׁמִּתְעַבְּרוֹת אֵינָן שָׁבוֹת לְתַשְׁמִישׁ; וַאֲנִי דָּחַקְתִּי וְנִכְנַסְתִּי כְּדֵי שֶׁיְּהֵא לִי בֵּן מְלֻבָּן וּמְזֹרָז, שֶׁהַתַּשְׁמִישׁ יָפֶה כָּל שִׁשָּׁה חֳדָשִׁים אַחֲרוֹנִים:",2,0],[31,2,"וּמֶה בַּר נְדָרָי. כָּל נְשֵׁי אָבִיךָ הָיוּ נוֹדְרוֹת שֶׁיְּהֵא לָהֶן בֵּן הָגוּן לַמַּלְכוּת, וַאֲנִי נָדַרְתִּי שֶׁיְּהֵא לִי בֵּן מְלֻבָּן בַּתּוֹרָה:",3,0],[31,3,"אַל תִּתֵּן. אַל תַּתִּישׁ:",1,0],[31,3,"לַנָּשִׁים חֵילֶךָ. כֹּחֲךָ:",2,0],[31,4,"אַל לַמְּלָכִים לְמוֹאֵל. אֵין זֶה דָּבָר הָגוּן לַמְּלָכִים, שֶׁהֵם לְהַקָּדוֹשׁ בָּרוּךְ הוּא. לְמוֹאֵל כְּמוֹ ״לְמוֹ פִי״ (איוב מ:ד):",1,0],[31,4,"אַל לַמְּלָכִים שְׁתוֹ יָיִן. אֵין נָאֶה לָהֶם לְהִשְׁתַּכֵּר:",2,0],[31,4,"אֵי שֵׁכָר. כְּמוֹ אֵין שֵׁכָר:",3,0],[31,5,"מְחֻקָּק. הַכָּתוּב בַּתּוֹרָה, וְכָל שֶׁכֵּן מַה שֶּׁהוּא בְּגִרְסָא:",1,0],[31,6,"לְאוֹבֵד. לְמִי שֶׁסּוֹפוֹ לְאִבּוּד, לָרְשָׁעִים (עירובין סה.):",1,0],[31,6,"לְמָרֵי נָפֶשׁ. הַמִּצְטַעֲרִין עַל עָנְיָם וְעַל אֶבְלָם (במדבר רבה י:ד):",2,0],[31,8,"כָּל בְּנֵי חֲלוֹף. אֵלּוּ הֵן הַיְתוֹמִים, שֶׁחָלְפָה עֶזְרָתָם וְהָלְכָה לָהּ:",1,0],[31,11,"וְשָׁלָל לֹא יֶחְסָר. כְּלוֹמַר: לֹא יֶחְסַר טוֹב:",1,0],[31,15,"טֶרֶף. מָזוֹן:",1,0],[31,15,"וְחֹק. הוּא מָזוֹן הַקָּצוּב לָהֶם:",2,0],[31,19,"בַּכִּישׁוֹר. שֶׁקּוֹרִין וִוירְטוֹי״ל בְּלַעַ״ז, הַמַּכְשִׁיר אֶת הַפֶּלֶךְ לִטְווֹת. פָלֶךְ פּוּשִׁי״ל בְּלַעַ״ז:",1,0],[31,21,"לֹא תִירָא לְבֵיתָהּ. לִבְנֵי בֵיתָהּ:",1,0],[31,21,"מִשָּׁלֶג. מִצִּנָּה:",2,0],[31,21,"לְבוּשׁ שָׁנִים. בִּגְדֵי צִבְעוֹנִין:",3,0],[31,22,"מַרְבַּדִּים. מַצָּעוֹת נָאוֹת לַמִּטָּה, כְּמוֹ ״מַרְבַּדִּים רִבַּדְתִּי״ (משלי ז:טז):",1,0],[31,23,"נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ. נִכָּר הוּא בֵּין חֲבֵירָיו מִפְּנֵי מַלְבּוּשָׁיו שֶׁהֵם נָאִים:",1,0],[31,24,"לַכְּנַעֲנִי. תַּגָּר:",1,0],[31,25,"לְיוֹם אַחֲרוֹן. בְּיוֹם מוֹתָהּ נִפְטֶרֶת בְּשֵׁם טוֹב:",1,0],[31,25,"וַתִּשְׂחַק. כָּל יָמֶיהָ עַל יוֹם מִיתָתָהּ, שֶׁיְּהֵא נִכְבָּד בְּשֵׁם טוֹב:",2,0],[31,27,"צוֹפִיָּה. הִיא בְּבֵיתָהּ נוֹתֶנֶת לֵב עַל צָרְכֵי בְּנֵי בֵיתָהּ, אֵיךְ יִנְהֲגוּ בֶּאֱמֶת וּצְנִיעוּת:",1,0],[31,29,"רַבּוֹת בָּנוֹת. כָּךְ מְאַשְּׁרִין אוֹתָהּ בַּעְלָהּ וּבָנֶיהָ:",1,0],[31,30,"שֶׁקֶר הַחֵן. אֵשֶׁת הַחֵן וְיוֹפִי אֵין מְהַלְּלִין אוֹתָהּ, אֶלָּא הַכֹּל הֶבֶל וְשֶׁקֶר; אֲבָל אִשָּׁה יִרְאַת ה׳ הִיא לְבַד תִתְהַלָּל:",1,0],[31,31,"מַעֲשֶׂיהָ. כִּשְׁרוֹן מַעֲשֶׂיהָ מֵעִיד עָלֶיהָ, לְהַלְּלָהּ בְּשַׁעַר הָעִיר כָּל יוֹצֵא וָבָא. זוֹ הַמְּלִיצָה שֶׁפֵּרַשְׁתִּי. אֲבָל לְפִי הַמָּשָׁל עַל הַתּוֹרָה וְלוֹמְדֶיהָ הַפָּרָשָׁה מִתְבָּאֶרֶת:",1,0],[31,31,"(י) אֵשֶׁת חַיִל. הִיא הַתּוֹרָה:",2,0],[31,31,"מִי יִמְצָא. אַשְׁרֵי הַזּוֹכֶה לִמְצֹא אוֹתָהּ:",3,0],[31,31,"מִפְּנִינִים. מַרְגָּלִיּוֹת:",4,0],[31,31,"(יא) וְשָׁלָל לֹא יֶחְסָר. אוֹכֵל פֵּרוֹת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא:",5,0],[31,31,"(יג) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים. לְפִי שֶׁהִמְשִׁילָהּ לְאִשָּׁה, דִּבֵּר לְפִי הַמְּלִיצָה כְּצָרְכֵי מְלֶאכֶת הַנָּשִׁים, וְהַמָּשָׁל כָּךְ הוּא: דּוֹרֶשֶׁת הַתּוֹרָה מִקְרָא, מִשְׁנָה, מִדְרָשׁ, וּמְחַזֶּרֶת אַחֲרֵיהֶם, שֶׁהֵם צָרְכֵי הַתַּלְמִידִים:",6,0],[31,31,"(יד) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר. מְבִיאָה הִיא לְלוֹמְדֶיהָ בְּרָכָה וּמָזוֹן:",7,0],[31,31,"(טו) וַתָּקָם בְּעוֹד לַיְלָה. מַשְׁכִּימִים בָּאַשְׁמוֹרֶת (מסכת ברכות ג:):",8,0],[31,31,"וְתִתֵּן טֶרֶף לְבֵיתָהּ. שׁוֹנֶה הָרַב לַתַּלְמִידִים הַחֹק הַקָּצוּב לָהֶם:",9,0],[31,31,"(טז) זָמְמָה שָׂדֶה. זָמְמָה בְּזֶמֶם וּבְרֶסֶן אֶת ״עֵשָׂו אִישׁ שָׂדֶה״ (בראשית כה:כז):",10,0],[31,31,"וַתִּקָּחֵהוּ. מִן הָעוֹלָם, לְהַאֲבִידוֹ:",11,0],[31,31,"מִפְּרִי מַעֲשֶׂיהָ נָטְעָה כֶרֶם. יִשְׂרָאֵל, לְקַיְּמָם לְחַיֵּי הָעוֹלָם הַבָּא:",12,0],[31,31,"(יח) טָעֲמָה. דְּבוּרָהּ:",13,0],[31,31,"לֹא יִכְבֶּה בַלַּיְלָה נֵרָהּ. בְּלֵיל כְּתִיב, חָסֵר ה׳: בְּלֵיל שִׁמּוּרִים שֶׁנִּגְּפוּ הַמִּצְרִיִּים (שמות יב:מב) הֵאִירָה לְיִשְׂרָאֵל וְהֵגִינָה עֲלֵיהֶם:",14,0],[31,31,"(יט) בַּכִּישׁוֹר. בְּכִשְׁרוֹן מַעֲשֶׂיהָ:",15,0],[31,31,"תָּמְכוּ פָלֶךְ. ״מַשְׁעֵן וּמַשְׁעֵנָה״ (ישעיה ג:א), כְּמוֹ ״מַחֲזִיק בַּפֶּלֶךְ״ (שמואל ב ג:כט):",16,0],[31,31,"(כ) כַּפָּהּ פָּרְשָׂה. לְמִי שֶׁמֵּשִׂים עַצְמוֹ עָלֶיהָ כְּעָנִי, בּוֹ הִיא מִתְקַיֶּמֶת (אבות ו:ד):",17,0],[31,31,"(כא) לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג. שֶׁדָּנִין בּוֹ הָרְשָׁעִים מֵאֵשׁ לְשֶׁלֶג (גֵּיהִנֹּם):",18,0],[31,31,"לָבֻשׁ שָׁנִים. בְּרִית דַּם מִילָה. דָּבָר אַחֵר: מְלֻבָּשִׁים בְּכֶפֶל ״נָתֹן תִּתֵּן״ (דברים טו:י), ״פָּתֹחַ תִּפְתַּח״ (דברים טו:ח), ״הַעֲנֵיק תַּעֲנִיק״ (דברים טו:יד). כָּל אֵלּוּ מַצִּילִין אוֹתָן מִשֶּׁלֶג גֵּיהִנֹּם. כָּךְ הוּא נִדְרָשׁ בַּתַּנְחוּמָה (יל״ש משלי תתקסד):",19,0],[31,31,"(כד) סָדִין עָשְׂתָה. לְבוּשׁ תִּפְאֶרֶת נוֹתֶנֶת לַחֲכָמִים:",20,0],[31,31,"וַחֲגוֹר נָתְנָה לַכְּנַעֲנִי. ( ) (לְמִי) לְפִי שֶׁהוּא חָגוּר בִּסְחוֹרָתָהּ, נוֹתְנָה אֵזוֹר לְמָתְנֵיהֶם:",21,0],[31,31,"(כה) לְיוֹם אַחֲרוֹן. אֵין לָהֶם לְהִתְעַצֵּב מִמִּדַּת הַדִּין כִּי יִנָּצְלוּ מִמֶּנּוּ, וְכָל יְמֵי חַיֵּיהֶם יִשְׂחֲקוּ לְיוֹם הַדִּין. מִי שֶׁאֵינוֹ צָרִיךְ לִדְאֹג נוֹפֵל בַּדָּבָר לְשׁוֹן צְחוֹק, כְּמוֹ ״וְיִשְׂחַק לְרַעַשׁ כִּידוֹן״ (איוב מא:כא):",22,0],[31,31,"(כז) צוֹפִיָּה הֲלִיכוֹת בֵּיתָהּ. הַתּוֹרָה מְלַמֶּדֶתָם דֶּרֶךְ הַטּוֹב, לִפְרוֹשׁ מֵעֲבֵירָה:",23,0],[31,31,"(כח) קָמוּ בָנֶיהָ. הַתַּלְמִידִים:",24,0],[31,31,"בַּעְלָהּ. הַקָּדוֹשׁ בָּרוּךְ הוּא:",25,0],[31,31,"(ל) שֶׁקֶר הַחֵן. שָׁב עַל כָּל הָעוֹבְדֵי גִּלּוּלִים:",26,0],[31,31,"וְהֶבֶל. גְּדוּלָּתָן וְיָפְיָן:",27,0],[31,31,"תְּנוּ לָהּ. לֶעָתִיד לָבֹא:",28,0],[31,31,"מִפְּרִי יָדֶיהָ. תִּפְאֶרֶת וּגְדוּלָּה, עֹז, פְּאֵר וּמֶמְשָׁלָה:",29,0]]);
